window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"현재 ○○○ 대웅전의 정면 향좌측벽에 봉안되어 있는 ○○○로서, 1883년에 금어(金魚)인 대허 체훈(大虛 軆訓)과 금곡 영환(金谷 永煥), 한봉 창엽(漢峰 蒼曄)이 그린 것이다. 일반적으로 ○○○가 석가8상을 8폭으로 나누어 그리는데 비하여 이 ○○○는 장방형의 화면을 여덟 부분으로 나누어 석가팔상의 장면을 한 폭에 표현한 화면 분할식 구도를 보여준다. 화면은 4폭의 비단을 이어 만들었으며 유리를 끼워 봉안하고 있고, 보관상태는 양호한 편이나 변색으로 인하여 화면은 전체적으로 어두운 편이다.","a":"개운사 팔상도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2021072109241600.png"},{"q":"1940년대에 지은 집으로 안채, 사랑채, 행랑채 등을 갖추고 있다. 각각의 건물이 서로 독립되어 있어 남부지방 가옥과 비슷한 배치를 보인다. 사랑채는 앞면 4칸·옆면 1칸 규모의 건물로 앞뒤를 퇴칸으로 터 놓았다. 뒤편에 마련된 안채는 앞면 6칸·옆면 3칸 규모의 건물인데, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다.","a":"보은 선병우 고가","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660717.jpg"},{"q":"선조 37년(1603) 강원도 관찰사 이광준이 벗들과 함께 금강산을 유람하고 적은 글이다. 금강산은 문인이라면 꼭 들러야하는 순례지로 인식될 정도로 금강산에 오르길 원했다. 『○○○○○』은 현재 복간본 3책이 전해지고 있는데 이광준의 후손가, 이광준의 3남 민환의 사위 송세빈 후손가, 부산의 고서화 수집가 도종현씨가에 소장되어 있다. 이 작품은 이광준 후손가에 전해지고 있는 것으로, 선조 37년(1603)에서 영조 11년(1735) 사이에 만들어졌다. 유금강산기 외에 이호민이 짓고 한석봉이 쓴 감상문, 이정의 묵죽도와 이익의 감상문이 첨부되어 있다.","a":"유금강산권","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641025.jpg"},{"q":"이 건물군은 조선시대의 진양강씨 문중이 낳은 일곱 분의 충효열 삼강을 기리기 위해 세워진 정려각(旌閭閣)으로써 일명 삼강문(三綱門)으로도 불리며 6동(棟)의 건물이 한곳에 자리 잡고 있다. ○ 제1려 강 우(姜 瑀) 자는 백규(伯圭) 호는 모암(慕庵) 이니 청풍군수 혜의 증손이며 남명과 종유 하였다. 연산 을묘생(1495)으로 1513년 성균진사 1517년 모부인 중상일에 여막에서 계서 1744년에 효정 1847년 충효사에 배향 ○ 제2려 강 서(姜 瑞) 자는 숙규(菽圭) 호는 매곡(梅谷)이니 진사 우(瑀)의 아우요 남명 문인이다.","a":"의령 칠정려","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654883.jpg"},{"q":"서울특별시 강남구 삼성동에 소재한 “○○○○○”은 1856년에 창건되고 1878년 중수된 단층 맞배집 목조 건축물로, ○○○ 경내에서 가장 오래된 건축물이다. 본 건물은 경판을 보관하는 장경각(藏經閣)인 동시에 예불을 드리는 불전(佛殿)으로, 경판보관 및 예불 기능을 병용하기 위하여 독특한 창호 구성을 갖추는 등 건축적 희소성이 있다. 정면 어칸 처마에 걸려 있는 현판에는 ‘○○’ 두 글자가 양각되어 있는데 추사 김정희(1786~1856)의 글씨이며 현재 서울특별시 유형문화유산으로 지정되어 있다.","a":"봉은사 판전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102217331800.jpg"},{"q":"의열사의 건립과정과 그곳에 모신 인물에 관한 내용을 기록한 비이다. 의열사는 조선 선조 8년(1575) 부여현감 홍가신에 의해 건립된 것으로, 선조 10년(1577)에 임금이 이름을 지어 현판을 내렸다. 비의 형태는 네모진 바닥돌 위에 비몸을 세우고 지붕돌을 올린 모습이다. 비문의 내용에 의하면 이 고장 출신이었던 백제의 3충신(忠臣)인 성충, 흥수, 계백과 고려시대에 신돈을 탄핵하다가 물러난 이존오의 공로가 후대에 전해지지 않음을 안타깝게 여긴 홍가신이 사당을 지어 이들을 모시게 되었다고 한다. 후에는 조선시대의 정택뢰, 황일호를 모셨다는 내용도 적혀 있다.","a":"의열사비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639081.jpg"},{"q":"조선 후기 이 지방 유학자들과 시인들이 어울려 풍류를 즐기던 곳으로 남읍리와 함께 양반촌으로 알려진 한림읍 명월리에 있다. ○○○는 옆으로 맑고 고운 시냇물을 끼고 있으며, 수십 그루의 팽나무가 울창한 자연림을 이루고 있어 한여름 찌는 듯한 더위를 식히기에 좋은 곳이다. 또한 아담한 반달형 돌다리가 놓여 있어 운치를 한층 돋구고 있다.","a":"명월대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657747.jpg"},{"q":"○○○란 옛 선현의 자취를 살피어 후세에 전하고 이를 계기로 그의 공적을 기리기 위해 세워두는 것으로, 이 비는 조선시대 전기의 문신인 대전 이보흠 선생의 행적을 적고 있다. 이보흠(1397∼1457) 선생은 세종 11년(1429) 과거에 급제하여 동부후도관과 사정을 거쳐 집현전 박사가 되었다.","a":"이대전유허비","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662385.jpg"},{"q":"○○○는 통도사에 딸린 절로, 사명대사의 충훈을 추모하기 위하여 세운 ○○○당이 있는 절이다. 조선 철종 11년(1860)에 월암선사가 세운 ○○○는 H자형의 독특한 구조로 아미타불의 48원을 상징하는 48칸과, 108번뇌를 상징하는 108평으로 되어 안쪽에 아미타불을 모시고 있다. 무량수각 또는 서래각이라고도 불리는데 이곳은 중생을 구제하고자 사부대중이 만일회를 결성하였던 곳이다. 나중에는 참선하는 방인 선방으로 사용하였으며, 대한불교조계종 초대 종정을 지낸 효봉대종사가 만년을 보낸 곳이다.","a":"밀양 표충사 만일루","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664168.jpg"},{"q":"경포호의 북쪽 언덕 위에 위치한 정자로 조선 중종(재위 1506∼1544) 때 김습독이 처음 지었다. 그 뒤로 그의 사위 장호를 거쳐 장호의 동생 민의 사위 김몽호에게 넘겨진 후, 지금까지 그의 자손들이 관리하고 있다. 이 부근 대부분의 정자들이 호수가 바라보이는 곳에 있는데 반해, 호수의 동북쪽 깊숙한 산기슭에 자리잡고 있다. 앞면 2칸·옆면 2칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 소박한 모습을 띤 이 정자는 온돌방과 마루방을 두고 방 사이에 분리할 수 있는 분합문을 달아, 필요할 때 하나의 방으로 사용할 수 있게 하였다.","a":"강릉호해정","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638007.jpg"},{"q":"조선 중기 문신 ○○○의 ○○이다. 본래 경기도 파주시 조리면 오산리에 있었던 것을 1977년 현재의 위치로 옮겼다. 현재 ○○○○○에는 봉분 바로 앞에 상석이 있고, 왼쪽에 1687년 송시열이 지은 묘표가 있다. 또 상석 앞에는 문인석과 동자석 및 망주석 등이 있다. 이 밖에도 근래에 조성한 ○○○ 사적비와 장명등이 있다. ○○○는 본관은 상주尙州이고, 자는 국이國耳이며, 호는 필재畢齋·잠소당潛昭堂, 시호는 문정文貞이다.","a":"청주 박광우 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649965.jpg"},{"q":"고려 후기 왜구토벌에 공을 세운 조선 개국공신 필암(筆菴) ○○○의 ○○이다. 고려 공민왕 때 문과에 급제하였으며, 진주수령·상주목사·계림부윤·화령부윤 등을 역임하였다. 우왕 2년(1376) 진주도원수가 되어 왜구를 대파하였으며, 우왕 4년(1378) 경상도원수로서 욕지도에서 왜구를 대파하였다. 고려 우왕 14년(1388) 요동출병 때 이성계 휘하에 참여하여 위화도 회군을 도와주었다. 이후에 여러 관직을 역임하였으며, 정도전·조준 등과 함께 공양왕을 폐하고 이성계를 조선 태조로 즉위시켜서 그 공으로 1등개국공신이 되었고 조선 최초의 영의정이 되었다.","a":"증평 배극렴 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650361.jpg"},{"q":"서울시 노원구 중계동 천보산 중턱에 자리잡고 있는 ○○○이라는 단아한 암자에 모셔져 있는 마애불로, 거대한 바위면에 돋을새김으로 새긴 높이 13.4m의 ○○○○이다. 바위 측면에 새겨진 기록에는 고종 7년(1870) 명성황후가 불심(佛心)으로 만들었다는 내용이 남아 있으며, 고종 15년(1878) ○○○을 고치면서 마애불상을 보강하였다고 적고 있다. 당당한 체구에 얼굴은 원만한 모습이며 머리에는 화려한 관(冠)을 쓰고 있다. 관의 정면에는 작은 부처가 새겨져 있어 ○○○○을 표현한 것임을 알 수 있다.","a":"학도암 마애관음보살좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636309.jpg"},{"q":"이 건물은 조선시대 무장현의 객사로 쓰이던 것으로 선조 14년(1581)에 건립하였다. 객사는 궐패를 모셔 두고 현의 수령이 매달 초하루와 보름에 배례하는 정청과 왕명으로 지방에 내려오는 벼슬아치들의 숙소로 쓰이는 좌·우현으로 구성된다. 이 객사의 정청은 바로 위까지 내려와 있다. 눈썹은 초승달처럼 갸날프게 처리되어 있고 눈은 반쯤 뜨고 정면 3칸, 측면 3칸의 홑처마 맞배지붕 건물로 초석의 석재 하부는 네모지게 상부는 반구형으로 다듬고 그 위에 두리기둥을 세운 외에 별다른 특징이 없다. 우현은 정청보다 지붕을 낮게 꾸미어 건물의 격식을 낮추었다.","a":"고창무장객사","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639411.jpg"},{"q":"조선 선조 때 학자인 매헌(梅軒) 금보(琴輔, 1521­1586)가 60세 때 처음 지었다. 정면 4칸, 측면 1칸 반 규모의 一자형 집으로, 현재의 건물은 1933년 문중에서 중수하였다. 수운정(水雲亭)이라는 이름은 금보가 자연을 사랑하여 항상 물 맑고 경치 좋은 곳에 아담한 정자를 지어 물과 구름을 벗하며 사우(士友)들과 학문을 논하고 후학을 양성하고자 하는 뜻으로 이름지었다고 한다. 비록 20세기 초에 중수하였으나, 이전 건물의 건축양식을 그대로 적용한 건물로 현재 19세기 건축물의 특징으로 드러나는 평면 및 구조양식을 잘 지니고 있다.","a":"안동수운정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663438.jpg"},{"q":"이 암자는 조선 정조 10년(1786)에 광혜(廣惠) 스님이 창건했으며, 경내에는 자음전(慈蔭殿)과 극락전(極樂殿)이 있다. 19세기 중엽 다시 세운 자음전에는 나무로 만든 부처를 가운데 모시고 그 좌우에는 돌로 만든 보살이 자리잡고 있으며, 6점의 불교 관련 그림이 있다. 최근 건립한 극락전에는 극락세계의 부처인 아미타여래를 나무로 만들어 모셔두고 있다. 이 암자는 고덕산 서쪽 산기슭에 아담하게 자리잡고 있는데, 학의 둥지를 연상케 하여 ○○○이란 이름이 붙여진 듯하다.","a":"학소암","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661605.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위해서 영토내 접경지역 이나 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 대개 높은 평지에 쌓아두는데, 밖은 성곽을 높게 하고, 안은 낮게 하여 포를 설치해 두는 시설물이다. 이 돈대는 정포보 소속의 돈대로서, 6조(六朝)에 올리는 조운의 감시소 역할과 국토방위의 임무를 겸하였다고 한다. 조선 숙종 5년(1679) 윤이제가 ○○유수로 있을 때, 병조판서 김석주의 명을 받아 이 돈대를 설치하였다고 전한다.","a":"강화 건평돈대","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645644.jpg"},{"q":"○○○ 탑평(塔坪) 마을에 위치하며 탑 주변의 경작지와 인근 민가일대까지 주초석과 많은 기와들이 나오고 있다. 또한 ○○○사지의 암자로 추정되는 뒤쪽 8부 능선상에도 많은 기와가 확인되고 있다. 사명(寺名)은 밝혀진 바 없으나 자기(磁器)와 고려시대 와편(瓦片)들이 상당량 출토되고 있어 고려시대 전반기인 11세기경 축조된 탑으로 추정된다. 이 주변 사지(寺址)는 조선왕조실록에 기록되어 있는 ‘엄정사(嚴政寺)’일 가능성이 크나 현재로선 확인할 수는 없다. 절터는 3층석탑이 있는 주변과 인근 민가일대까지 포함되는 약 3,000평 규모로 추정된다.","a":"충주 추평리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638813.jpg"},{"q":"○○○○○은 시조인 동래부원군 정난종鄭蘭宗의 위패를 봉안한 사당이 있는 종갓집이다. 조선 전기의 문신인 정난종의 아들 정광보鄭光輔가 아버지 무덤을 만들 때 지은 건물로 알려져 있다. 이 ○○은 중앙에 ㄱ자로 안채를 배치하고, 주변으로 큰사랑채와 작은사랑채를 두었으며, 남쪽으로 곳간인 광채를 배치하였다. 북쪽으로 신주를 모시는 사당이 있고, 남쪽 바깥쪽으로는 마굿간인 마방채를 두었다. 사람의 생활공간을 중심에 두고 주변에 제례를 준비하거나, 손님의 이동을 맞이하는 공간을 배치하여 종갓집의 기능성이 엿보인다.","a":"군포 동래정씨 동래군파 종택","c":"문화유산자료","nc":"","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660152.jpg"},{"q":"조선 중기 문신 석담 이윤우(1569∼1634)와 그의 아들 낙촌 이도장(1603∼1644)이 정착한 매원마을에 후손들이 세운 집 중 하나이다. 안채인 정침은 이동유(1768∼1836)가 정조 12년(1788)에 짓고 사랑채는 순조 16년(1816)에 지었다. 그 뒤 이동유의 후손 이철연(1851∼1905)의 호를 따라 ‘○○○○’이라고 부른다. 대문채를 들어서면 사랑채, 곳간채, 정침을 ㄷ자형으로 배치하였으며, 정침 오른쪽에는 담장을 둘러 별도로 사당을 두었다. 정침은 앞면 6칸 반·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"칠곡 해은고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658992.jpg"},{"q":"옥동서원으로 통칭되는 ○○○은 주벽으로 모시고 있는 수우당의 역사적 의의나 가치가 높이 평가되며 일제강점기의 혼란중에도 민족정신 고취를 위한 활발한 건축 활동을 보여주는 자주적 정신문화계승의 노력을 담고 있는 근대적 전통건축이며 공간구성도 전학후묘의 정형적 축적 구성에 따른 영역성을 갖추고 있음.","a":"하동 수정당","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666325.jpg"},{"q":"○○○이 자손에게 가족간에 지켜야 할 태도 및 관직생활을 자세 등을 경계하여 지은 글이다. 글을 통해 그가 어떻게 청백리가 될 수 있었는지를 알 수 있으며, 조선시대 청백리 정신을 이해하는 중요한 자료이다.","a":"이원익계자손서","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637803.jpg"},{"q":"임진왜란 때 순국한 박형준(1548∼1592)과 그의 아들인 박효남(1568∼1592)·박호남(？∼1592) 등 3부자의 충절을 기리기 위해 세운 비와 이를 보호하고 있는 비각이다. 조선 헌종 12년(1846) 이 지방 유림들이 상소문을 올려 철종 11년(1860) 지은 것이다. 고종 38년(1901), 1932년 2차례 보수를 하였고 1946년에 다시 지었으며, 1982년 지금의 모습으로 고쳐 세웠다. 규모는 앞면 3칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양의 간결한 맞배지붕으로 꾸몄다.","a":"영암삼충각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654266.jpg"},{"q":"조선 중기 문신 ○○○의 ○○이다. ○○○은 본관이 전주全州이고, 자는 자겸子謙, 호는 지천遲川·창랑滄浪이다. 일찍이 이항복李恒福 문하에서 수학하였으며, 1605년(선조 38) 문과에 급제하여 관직에 나아갔다. 1614년(광해군 6) 폐모廢母사건에 연루되어 파면되었으며, 그 뒤 1623년 인조반정에 가담, 정사공신靖社功臣 1등이 되어 완성부원군完城府院君에 봉해졌다. 1627년(인조 5) 정묘호란 때 청나라와의 강화講和가 불가피함을 역설하여 이로부터 강화가 논의되었다.","a":"청주 최명길 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017012309434000.jpg"},{"q":"조선 전기의 무신 유곡 ○○○ 장군의 묘이다. 19세 때 무과에 급제한 뒤 여러 관직을 거쳤다. 세종 6년(1434)에 대마도의 왜구를 소탕하고 황해도와 평안도 일대의 여진족을 물리친 공로를 인정받아 무인으로서 좌의정에까지 올랐다. 어려서부터 힘이 세고 활을 잘 쏘았는데, 어느날 소에게 풀을 먹이고 산에 갔다가 호랑이를 만나 화살 하나로 쏘아 죽였다는 일화가 전해진다. 묘 아랫부분은 커다란 화강석을 사용하여 2단으로 쌓고 그 위에 흙으로 둥글게 봉분을 만들었다. 묘의 좌우에는 문인석이 2기 있고, 묘의 뒤편에는 부인의 묘로 추정되는 같은 형태의 봉분이 하나 더 있다.","a":"창원 최윤덕 묘역","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655619.jpg"},{"q":"진은 진영(鎭營)을 줄여 부르는 말로 지방의 군사를 관리하던 지방관제의 하나이다. ○○○은 조선 후기 자주 나타나는 서구의 함선을 감시하기 위해 군대가 주둔하던 곳으로 장도포대와 논현포대를 관장하였다. ○○○의 설치는 인천 항구의 개방을 요구하는 일본에 대비하여, 조정에서 어영대장 신정희와 강화유수 이경하에게 만들도록 하여, 1879년 완성되었다. 그러나 갑오개혁에 따른 군대 관리제도 개혁으로, 진이 철폐되고 건물도 철거되었다. 한편, ○○○은 1982년 ○○○을 그린 『○○○도』를 보고 옛 건물을 복원하였다.","a":"화도진 터","c":"시도기념물","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/0000000001645436.jpg"},{"q":"○○○는 충청북도 ○○군 ○○읍 장령산에 있는 사찰로, 법주사의 말사(末寺)이다. 용처럼 생긴 바위가 있어서 ○○○라고 이름지었으나, 일제시대 일본인에 의해 용바위가 파괴되어 현재는 그 흔적만이 남아 있다. 대웅전 안에는 불상과 5종의 탱화(幀畵)가 보관되어 있다. 현재 이 대웅전에 모셔져 있는 목조불상은 이전의 연혁이 알려지지 않고 있다. 1880년 불상을 열어 보았을 때 속에서 ‘순치 8년 신묘년(효종 2년, 1651)’에 만들어진 다라니경이 발견되었다.","a":"옥천 용암사 목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638697.jpg"},{"q":"전북특별자치도 익산시 ○○○에 위치한 이 산성은 일명 ‘용화산성’으로 불리는데, 옛날에는 ○○○을 용화산이라 했기 때문이다. 고조선시대 기준왕이 이곳으로 내려와 쌓았다고 하여‘기준성’이라고도 부르기도 하지만, 마한의 여러 나라 중 하나가 이곳을 중심으로 세력을 누리고 있었던 것으로 보아, 산성도 그때 만들어진 것으로 추정된다. 고려 태조가 후백제의 신검과 견훤을 쫓을 때 이를 토벌하여 마성에서 신검의 항복을 받았다고 하는데, 그 마성이 바로 이 산성이다.","a":"익산미륵산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653330.jpg"},{"q":"○○○ 명부전에 봉안된 ○○○○○이다. 최근 개금불사에서 출토된 복장품에서 강희12년 계축4월일(1674)에 조상했고 건륭6년 신유3월20일(1741)에 중수개금을 시작하여 4월6일에 마쳤다고 하는 복장기를 확인하였다. 즉 조상연대와 중수기록이 있고 또한 ○○○○로서는 비교적 큰 규모이며 조선후기 작품이면서도 조선 전기 양식을 일부 간직하고 있어 조상사 연구에 좋은 자료가 된다.","a":"소재사 목조지장보살좌상","c":"문화유산자료","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659507.jpg"},{"q":"○○○○○은 2001년 시굴조사와 2001년에서 2002년에 걸친 1차 발굴조사를 실시한 결과 내·외곽을 갖춘 목책성으로 확인되었다. 정상부에서 바라보면 ○○ 시내와 금강이 한눈에 내려다보이며, 남서쪽으로 계룡산, 북서쪽으로 조치원까지 조망이 가능하다. 전체적인 구조는 내곽의 성터 부분과 성터 북서쪽의 낮은 사면대지 부분, 동쪽의 능선대지 부분으로 이루어진다. 내곽의 전체 둘레는 약 300m이고, 능선 대지의 평탄부는 폭 16.5m, 길이 53.5m이다.","a":"부강 남성골산성","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2023050113315400.JPG"},{"q":"‘○○○’는 부처님의 불법을 수호하고 부처님을 믿는 사람들까지도 외호하는 천신들의 무리를 그린 불화이다. ‘○○○○○’는 1883년에 수락산 흥국사에서 불상 3구를 개금(불상에 금칠을 다시 함)하고 시왕도 10축을 개채(改彩)하는 불사를 할 때 함께 제작되었다. 상궁 신씨(申氏)가 부모를 위해 발원하였다. 우두머리 화승인 경선당응석(慶船堂應碩)이 불화의 밑그림(出草)을 그렸으며, 작품(昨品)·진철(震徹)·긍법(亘法)·봉조(奉祚)와 함께 제작하였다. 하단 중앙의 위태천과 상단 좌우 자리한 범천과 제석천이 역삼각형 구도로 배치되어 있고, 주변에는 권속들이 에워싸고 있다.","a":"의정부회룡사신중도","c":"문화유산자료","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660244.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위해서 영토내 접경지역이나 해안지역의 감시가 쉬운 곳에 마련한 초소로, 대개 높은 평지에 쌓아두는데 밖은 성곽으로 높게 하고, 안은 낮게 하여 포를 설치해두는 시설물이다. 망월평야 남서방향의 언덕 위에 자리하고 있는 이 돈대는 바깥벽 측면에 기록이 남아 있으며, 망월돈대와 함께 관아에서 관리하던 돈대이다. 남아 있는 기록에 의해 조선 숙종 5년(1679)에 설치된 것임을 알 수 있는데, 이처럼 돈대의 제작년대에 대한 기록이 남아 있는 것은 보기드문 예이다.","a":"강화 계룡돈대","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645587.jpg"},{"q":"대전광역시 동구 판암동 해발 240m의 산꼭대기를 빙 둘러쌓은 산성이다. 둘레는 약 200여m이고 남북으로 긴 타원형이며, 남벽에는 일부 겹으로 쌓은 흔적이 남아 있는데, 그 성벽 폭은 5.2m였다. 산능선이 지나고 있는 동북쪽과 서남쪽의 성벽에는 돌출부가 있는데, 적의 접근시 관측하여 격퇴시킬수 있도록 성의 취약 지점에 설치하는 치성의 흔적으로 여겨진다. 또한 서쪽 성벽의 가까운 주변을 감시하기 위해 만든 건물이 있었던 것으로 보인다. 이 산성은 옥천 방면으로 통하는 길목을 지키기 위하여 쌓은 것으로 추정된다.","a":"삼정동산성","c":"시도기념물","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645800.jpg"},{"q":"절제 ○○○ 선생의 생가지이면서 그의 가족이 평생을 살았던 곳으로 의당 초등학교와 인접한 곳에 위치하고 있다. 의당초등학교 개교(1927년) 이후 현재까지 학생들의 역사교육장소로 관리해 왔으며, 의당초등학교 건립 시 해당 부지를 확보하여 관리하였다. 비계실이라는 자연마을 사람들은 이 터를 <정승의 집터>라고 일컬었으며, 절제(節齊)선생의 순천 김씨 가문이 멸문(滅門)을 당한 이후 현재까지 다른 가옥이 건축되지 않은 상태로 보존되면서 <○○○ 생가지>로 불렸다.","a":"김종서유허지","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661575.jpg"},{"q":"송암 권호문(1532∼1587)을 추모하는 서원이다. 권호문은 조선 선조(재위 1567∼1608) 때의 문인이며 학자로 평생을 자연에 묻혀 살았는데, 덕망이 높아서 찾아오는 문인들이 많았다. 선조 41년(1608)에 세운 이 서원은 광해군 4년(1612)에 선생의 위패를 모시고 제사를 지내다가, 영조 43년(1767)에 지금 있는 자리로 옮겨 세웠다. 고종 5년(1868)에 흥선대원군의 서원철폐령으로 철거되었다가 그 뒤 1909년 도내 유림들의 뜻에 따라 옛터에 복원하였다. 서원 안에는 강당, 동재·서재, 정도문, 청풍사, 전사청, 신문 등 모두 7동의 건물이 있다.","a":"안동 청성서원","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018021911155800.jpg"},{"q":"○○○에 보관되어 있는 청동으로 만든 동고(銅鼓)로 징과 같은 형태이다. ○○○는 고려 의종 원년(1146)에 각화사 주지인 성원이 암자를 지으면서 개창되었다. 1896년에 불타버린 것을 이후 다시 지어 오늘에 이르고 있다. 이 동고는 가로 31.3㎝, 세로 30.3㎝ 크기로, 절을 다시 지을 때 발견되어 보관하게 되었다. 동고의 위부분과 그 양옆에 각각 1개씩의 고리가 있으며, 아랫부분에는 길이 15.5㎝, 최대 폭 6.2㎝의 울림통이 있다.","a":"안동용수사대정삼년명금동고","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641059.jpg"},{"q":"19세기 중엽에 지은 것으로 보이는 부농 계층의 옛집이다. ㄱ자 모양의 안채와 ㄴ자 모양의 사랑채로 구성된 튼 ㅁ자형이다. 안채는 앞면에서 볼 때 사다리꼴을 한 우진각지붕집으로, 퇴칸이 없는 일반적인 구성 방식을 따르고 있다. 사랑채는 초가로 일반적인 농가의 사랑채 평면을 보이고 있는데, 건넌방 앞에 살림방을 둔 것이 특이하다. 대문간에는 내외담을 설치하여 밖에서 안마당이 직접 보이지 않으면서 꺾어 돌아 들어가도록 하였는데, 이는 우리나라 주택의 특징이다. 안마당과 사랑마당은 대문을 통해서만 연결되도록 사랑방 옆에 담장을 둘러 구분하였고 편의를 위하여 쪽문을 두었다.","a":"제천 중전리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638518.jpg"},{"q":"조선 인조 16년(1638)에 박범성이 세운 가옥이다. 앞면 4칸·옆면 2칸 규모이며, 지붕은 앞면에서 볼 때 사다리꼴인 우진각지붕으로 꾸몄다. 왼쪽 1칸은 누각으로 되어 있다.","a":"박기성가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661349.jpg"},{"q":"이 문서는 ○○○○의 조부모와 부모등 ○○○○의 일가에 임금의 명을 담아 내린 ○○이다. 이 ○○들 가운데 4장은 선조 35년(1602) 10월 30일에 ○○○○ 일가에 벼슬을 내린 증직○○이고, 나머지 한 장은 선조 40년(1607) 6월 8일에 내려진 ○○이다.","a":"밀양 표충사 사명대사 관련 교지","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642118.jpg"},{"q":"고흥 ○○○ 산성은 고흥군 남양면 ○○○와 중산리 일대에 있는 해발 162m의 산 정상부를 감싸고 있는 산성으로 동서 양쪽의 바다를 조망할 수 있는 위치이다. 이 지역 일대는 백제시대에 조조례현(助助禮縣)이 있었던 곳이다. 조조례현은 통일신라 경덕왕대에 이르러 충렬현(忠烈縣)이 되었다가 다시 고려시대에 이르러 남양현(南陽縣)으로 이름이 바뀌었다. ○○○ 산성은 돌을 쌓아 만든 산성이며, 총 둘레는 534m이고, 너비는 4m내외이다. 산성의 평면형태는 부정형으로 남북이 동서에 비해 길며, 성벽은 동벽과 북벽 일부가 잘 남아 있다.","a":"고흥남양리산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020052414105500.JPG"},{"q":"동헌은 아헌이라고도 하며, 관청의 중심이 되는 건물로 조선시대 감사나 수령이 공무를 처리하던 곳이다. 세워진 연대는 정확히 알 수 없지만 순조(재위 1800∼1834) 때 고친 것으로 전한다. 한때 보은경찰서로 사용되면서 내부구조가 많이 바뀌긴 했으나, 17세기 말경에 지어진 것으로 추정하고 있다. 앞면 7칸·옆면 3칸으로 1층이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 내부는 평면이 특징있게 꾸며져 있다. 전면 1칸은 모두 마루이고 오른쪽 4칸은 대청이며, 왼쪽 3칸은 온돌방을 두었다.","a":"보은동헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638576.jpg"},{"q":"가정 이곡(1298∼1351)과 목은 이색(1328∼1396)의 학문과 덕행을 추모하기 위해 세운 서원이다. 이곡은 고려 후기 학자로서 이색의 아버지이다. 원나라의 과거에 급제하여 실력을 인정받았고, 문명을 떨쳤다. 이색은 고려 후기 문신이며 학자이다. 원·명교체기에 친명정책을 지지하였고, 유교의 입장에서 불교를 이해하고자 하였다. 그의 문하에서 권근, 김종직, 변계량 등을 배출하여 조선 성리학의 주류를 이루게 하였다. ○○○○은 선조 27년(1594)에 세웠으나, 임진왜란 때 불타버렸다. 그 뒤 광해군 2년(1610)에 한산고촌으로 옮겨 다시 세웠다.","a":"문헌서원","c":"문화유산자료","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661100.jpg"},{"q":"○○○○○ 유적은 병인박해 당시 ○○○을 중심으로 신앙생활을 하다 순교한 분들을 모신 줄무덤 및 신앙공동체였던 교우촌 유적이다. 줄무덤(제1,2)에는 소학골에서 체포되어 1866년 11월 8일 공주 황새바위에서 순교한 배문호(베드로), 최천여(베드로), 최종여(라자로), 고의진(요셉), 채씨 며느리 등 5명의 시신과 무명 순교자들이 안장되어 있다.","a":"천안 성거산 천주교 교우촌터","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653210.jpg"},{"q":"○○○에 보존되어 있는 그림으로, ○○○이라 함은 지옥에 빠진 중생을 극락으로 인도해주는 장면을 그린 불화이다. 이 ○○○은 비단 바탕에 채색하여 그려진 것으로, 화면은 크게 상하 이단으로 구분하여 상단 중앙에 칠여래상(七如來像)이 연꽃 위에 서 있고, 그 아래에는 향로·촛대·꽃·과자가 성대하게 차려진 제단이 설치되어 있다. 여래상의 좌우에는 각각 인로왕보살과 지장·관음·대세지보살이 배치되어 있다. 좌우 보살상의 아래쪽에는 성곽을 배경으로 왕과 군중들의 행차장면과 범패(梵唄)와 작법(作法)을 행하는 의식승의 모습이 각각 묘사되어 있다.","a":"양산 통도사 광무4년명 감로탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642359.jpg"},{"q":"20세기 초 서울에 상수도시설이 본격적으로 도입되기 전 ○○은 서울의 주된 음수(飮水), 생활용수 공급원이 되어 왔다. 조선시대에 ○○○가 있던 터에 위치한 이 ○○은 화강암 두 덩이를 원형으로 이어 붙여 만든 것으로 상부에 네 귀가 조출(彫出)되어 있다. 내부는 자연석을 둥글게 쌓아 올려 만들었는데 이는 이 ○○의 원래의 형태가 아니고 1984년에 기무사에서 뜰 공사 도중 지하 3m에서 ○○돌을 발견하면서 원래의 위치에서 옮겨 새로 조성한 것이다. 물받이 돌로 사용되었을 구조물 1점을 현재 이 ○○ 내부에 놓여져 있다.","a":"종친부 터 우물","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659305.jpg"},{"q":"조선 고종 17년(1880)에 청호공이 지은 집이다. 안채와 사랑채가 一자형으로 앞뒤로 나란히 배치되고, 사랑채를 중심으로 헛간과 대문채 등이 ㅁ자형으로 놓인 구조를 이루고 있다. 안채는 앞면 5칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면 5칸 중에서 대청마루가 2칸으로 다른 공간에 비해 유달리 큰 것이 특이하다. 대청 뒷면은 격자무늬 문을 설치하여 제사 도구를 보관하게 하고 제사 의식 때 사용하는 공간으로 넓혔다.","a":"진주 청원리 이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664068.jpg"},{"q":"이 영정(○○○영정)은 ○○○ 휴정(서산대사, 1520-1604)선사의 영정으로 정면관의 전신교의좌상이다. 전체 화면은 방형의 격자문이 시문된 청색상단과 돗자리로 구분된 이단구도의 형식을 갖추고 상반신은 정면관을, 하반신은 측면으로 앉아 왼손에 불자(拂子)를 잡고 오른손으로 그 술을 가볍게 만지고 있는 모습이다. 정방형의 둥근 형태의 얼굴에 조용한 눈매와 단정한 코, 작게 다문 입술 등 자상하며 덕망 높은 고승의 이미지를 표현하였다.","a":"청허당 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642982.JPG"},{"q":"선돌은 길쭉한 자연석이나 커다란 돌을 일부만 다듬어 똑바로 세운 기념물 또는 신앙대상물을 말한다. 상입석리 마을 산에 서 있는 이 선돌은 높이 264㎝, 너비 66㎝인 사각형의 화강암으로 되어 있으며, 정면에는 보살상이 조각되어 있다. 여기에는 착한 마음씨를 가진 사람이 복을 받고, 나쁜 일을 하는 사람은 벌을 받게된다는 설화가 전하고 있다. 고려시대에 인색하기로 소문난 부자가 살았는데, 그의 며느리만은 마음씨가 곱고 착했다. 어느날 스님이 이 집에 시주를 하기위해 들렀을 때 부자는 스님을 박대하였으나 며느리는 선뜻 시주를 하였다.","a":"보안입석","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658293.jpg"},{"q":"김순범 소장 ○○○는 호적관련 문서(準戶口 2건, 戶口單子 35건)와 기타 문서(上書 2건, 所志 4건, 完文 2건)로 구성되어 있으며 신분적 지위가 불안했던 가문의 호적 자료가 이와 같이 대량으로 남아 있는 예는 전국적으로 그리 흔하지 않다. 이 가문에 남아 있는 호적자료 37건은 이 가문의 역사뿐만 아니라 당시 사회변화를 연구하는 데 중요한 자료이며 여러 종류의 청원장도 이 가문의 신분적 지위의 불안정으로 인해 이들에게 군역이나 일반 잡역의 침책이 이루어진 것에 대한 억울함을 호소하는 것이 대부분이고, 완문도 이러한 호소에 대한 조치를 취해주는 문서이다.","a":"거창 선산김씨 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666539.jpg"},{"q":"<○○○○○>는 중국 화엄종(華嚴宗)의 제5조(祖)인 규봉종밀성사(圭峰宗密禪師)의 만년작으로서 자신이 저술한 <○○○○○> 101권 전체에 대하여 서문을 지은 것이다. <○○○○○>이 현재 전해지지 않으므로 <○○○○○>를 통해 <○○○○○>의 내용을 짐작할 수 밖에 없다. 선교양종이 서로 적대하던 시대적 분위기 속에서 규봉은 화엄종의 입장에서 선교일치(禪敎一致)를 주장하여 당시의 불교계를 회통시켰는데, 이러한 선교일치를 주장한 대표적인 저술이 <○○○○○> 101권과 <○○○○○>에 대한 <○○○○○> 2권이다.","a":"복천사 선원제전집도서","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636730.jpg"},{"q":"일명 ‘미륵골’이라 불리는 전라남도 구례군 광의면 ○○○ 상대 마을의 북쪽 저수지 끝부분에 서 있는 석불이다. 얼굴은 비바람에 의하여 많이 닳아 희미하지만 달걀형으로 온화한 모습이다. 손모양은 오른손으로 왼손을 감싸쥔 형태인데 다소 시대가 떨어지면서 변형된 형식을 보여주고 있다. 석불 바로 옆에는 무릎을 굽히고 앉아있는 높이 80㎝의 공양상이 있고 그 주변에는 2개의 돌기둥이 남아 있다. 이것은 화엄사 석등과 같이 4사자 3층석탑 앞에 있는 석등 밑에 공양상을 앉히고 그 주위로 돌기둥을 세워 불을 밝히는 곳을 만든 형식을 취한 듯하다.","a":"구례대전리석불입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640121.jpg"},{"q":"전남 ○○○에 있는 ○○○○의 유품과 ○○들이다. ○○○○는 선조 25년(1592) 임진왜란이 일어나자 왕의 특명으로 팔도십육종도 총섭이 되어 73세의 노령으로 전국에 격문을 돌려 승병 1,500명을 규합 총수가 되어 활약하였다. 유품들은 다음과 같다. 교지는 임금이 신하에게 명령을 전달하거나 어떤 사람을 임명할 때 내리는 문서로, 2매이다. 하나는 선조 35년(1602)에 ○○○○를 ｀일도대선사선교도청섭´으로 임명하는 내용의 것이고, 다른 하나는 표충사가 건립된 때인 정조 12년(1788) 정조가 이전의 교지에 첨부하여 ｀표충선사´라는 칭호를 내리는 내용이다.","a":"해남 대흥사 서산대사 의발 등 유물 일괄","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640097.jpg"},{"q":"현재 강남구 삼성동 ○○○ 진여문(奉恩寺 眞如門) 안에 봉안되어 있는 이 ○○○○ 4구(軀)도 원래는 ○○○ 진여문과 법왕루 사이에 있던 천왕문에 봉안되어 있었으나 천왕문 철거로 현재의 위치에 임시 봉안되게 되었다. 이 ○○○○은 복장물 기록에 따르면 1746년(영조 22년)에 조성되었는데 능창군 이씨(綾昌君 李氏: 선조宣祖의 7子인 인성군仁城君의 증손)와 상궁 박필애(尙宮 朴弼愛) 등 궁중 관련 인물 현상성(賢上城)에서 건달바(乾達婆,Gandharva)와 비사사를 거느리고 동쪽 인간세계 사람들, 특히 국가와 국왕을 보호하는 역할을 한다고 알려져 있다.","a":"봉은사 목 사천왕상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590263.png"},{"q":"백치성은 천등산(해발 550m)에서 비봉산(해발 447.6m)으로 연결되는 능선의 중간부분인 당치(해발 207.6m) 정상부를 둘러싼 산성이다. 특히 지리적으로 백치성에서 북쪽의 고흥 독치성(전남기념물 제208호)과 남서쪽의 고흥 오치 음성(전남기념물 제210호)이 눈으로 관찰될 정도로 가까운 곳에 위치하고 있다. 돌로 쌓은 산성으로 성의 총 둘레는 444m이며, 평면형태는 남북방향으로 직사각형이다. 성 안에는 건물터로 추정되는 4곳이 남아 있다. 이 성에서 출토된 유물은 기와류가 대부분인데 격자문·선문·무문·복합문 등의 평기와 조각이다.","a":"고흥백치성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654364.jpg"},{"q":"고흥읍 ○○○와 서문리 마을에 흐르는 고흥천에는 약 150m 간격을 두고 2기의 다리가 놓여 있는데, 모두 무지개다리(홍예교)의 양식으로 건립된 돌다리이다. 위쪽에 있는 다리는 맨 밑바닥에 다듬은 돌을 놓고, 그 위로 27개의 직사각형돌을 무지개 모양으로 쌓았으며, 그 양 옆으로는 다듬은 돌과 막돌을 섞어 쌓아 올렸다. 맨 위에는 다시 직사각형돌을 덮어 통행의 무게를 견디도록 하였다. 무지개 모양의 앞면에는 용머리를, 반대쪽에는 용꼬리를 새겨 놓았다. 아래쪽 다리는 ○○○쪽에 있으며 위쪽 다리보다 규모가 크다.","a":"고흥옥하리(수구)홍교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639920.jpg"},{"q":"용암공의 덕을 후세에 전하기 위해 세운 비로, 이웃한 마을에 불이 나서 비석이 불에 타 형태가 일그러질 지경이 되자, 마을의 여러 유지들이 논의하여 다시 세운 것이다. 조선 순조 34년(1834)에 세웠으며, 비 양 옆에 기둥을 세우고 그 위에 지붕돌을 얹어 이를 보존하고 있다.","a":"창녕 진만석 영세불망비","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664472.jpg"},{"q":"○○○ 진남루 북서쪽에 있으며, 조선 영조 10년(1734)에 처음 세운 정자이다. 인조가 이괄이 일으킨 반란(1624)을 피하여 공주로 잠시 피난 왔을 때, 이곳에 머물렀던 일을 기념하기 위해 세운 것이라고 한다. 이후 여러 차례 보수되어 오다 1970년에 전체적으로 해체하여 지금의 모습으로 복원하였다. 건물은 앞면 3칸·옆면 2칸이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"공산성쌍수정","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660946.jpg"},{"q":"이 불화는 가로가 긴 화면이 상하로 구분되어 있는데, 상단에는 삼신불이 나란히 앉아있고, 하단에는 보살들이 일렬로 늘어서 있다. 삼신불은 중앙에 지권인(智拳印)을 취한 법신 비로자나불, 왼쪽(向右)에는 양손을 어깨높이로 들어 설법인(說法印)을 취한 보신 노사나불, 오른쪽에는 오른손을 가슴 앞으로 올린 설법인을 취한 석가모니불이 자리하고 있다. 삼불은 모두 원형의 두광(頭光)과 신광(身光)을 지고 목리문(木理文 : 나무결 무늬)이 표현된 불단 위의 연화좌에 앉아 있다.","a":"천축사 비로자나삼신불도 및 복장유물","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636518.jpg"},{"q":"○○○은 태종 9년(1409)에 장표가 지은 정자이다. 정자 준공식 때 관직에 있는 장표의 아들 4명과 사위 3명이 참석하여 두 그루의 회화나무에 인수(印綬 : 관청 또는 관리가 직무상 쓰는 도장에 달린 끈)를 걸은 것을 기념하여 ○○○이라 이름 붙였다고 한다. 현재 있는 건물은 18세기 후반에 다시 지은 것으로, 1986년에 낡거나 부서진 곳을 보수하였고, 1993년에 기와·담·장벽 등을 다시 고쳐 지었다. 건물은 앞면 3칸·옆면 2칸 규모이며 양쪽에 온돌방을 두고, 중앙에는 마루를 두었다. 앞면과 양쪽 옆면에 툇마루를 두고, 풀 모양을 조각한 난간을 둘렀다.","a":"칠인정","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020040211081100.bmp"},{"q":"공주 공산성 내 위치한 ○○○ 원통전에 있는 ○○○○. 북극성을 불격화한 치성광여래를 중심으로 좌우에는 일광보살과 월광보살이 협시하고 있는데, 일반적으로 머리에 쓴 보관에 해와 달을 표시하는 것이 일반적이나 양손에 해와 달을 들고 있는 모습으로 표현한 점이 특징이다. 불보살의 주위로 위쪽에는 북두칠성을 상징하는 일곱명의 부처를 배치하였고, 그 아래로 중앙에는 삼태성을, 양쪽에는 북두칠성의 도교신격인 일곱명의 칠원성군을 배치하였다. 붉은 색과 황토색을 주조색으로 하고, 군데군데 보이는 코발트블루의 사용은 당시의 시대적 경향을 잘 보여준다.","a":"공주영은사칠성탱화","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661546.jpg"},{"q":"○○○○○은 조선 중종(中宗)의 손자이자 덕양군(德陽君) 이기(李岐)의 아들이다. 임진왜란 때 선조(宣祖)의 어가(御駕)를 호종(扈從)하였다. 이후 소덕대부(昭德大夫, 종1품)로 종친부(宗親府)의 일을 관장하였고 사후 현록대부(顯祿大夫)에 추증되었다. ○○○ 묘는 부인 금원군부인(錦原郡夫人) 나주박씨(羅州朴氏)와 합장묘이며 봉분은 8각의 호석(護石)이 둘러져 있다. 호석은 지대석(地臺石) 위에 호석을 올려놓은 형태로 조선전기와는 다른 형태이다. 봉분 앞 묘표(墓表)는 원수방부(圓首方趺; 둥근 머리의 비신과 네모난 비좌) 형태다.","a":"풍산군이종린묘역","c":"문화유산자료","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660265.jpg"},{"q":"○○○는 중국 삼국지에 나오는 이름난 장수 관우 운장의 제사를 지내는 곳이다. 이 사당은 조선 선조 31년(1598) 당시 ○○에 주둔하던 쉬후첸이 지은 것이다. 지금 있는 자리로 옮긴 시기는 선조 39년(1606)이라는 설과 인조 14년(1636)이라는 2가지 설이 있으나 어느 것이 맞는지는 알 수 없다. 다만 ○○향교와 마주보고 있는 것을 꺼려 ○○○를 옮기게 되었다고 한다. 현재 건물은 1904년 해체·복원한 것으로 ○○○ 가운데 유일한 석상(石像)이 모셔진 곳이기도 하다. 광감루를 지나 좌우에 동재·서재가 있고 조금 더 오르면 묘우 삼문이 있다.","a":"안동 관왕묘","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658518.jpg"},{"q":"백암사는 백제 무왕 33년(632) 여환이 세웠다고 하는데, 시대를 거치면서 여러 차례 고쳐 지었다. 지금의 절은 1917년 송만암이 고쳐 세운 것이다. ○○○○은 조선 선조 7년(1574)에 한응선사가 지었다는 기록이 있으나 확실히 알 수는 없다. 다만 『조선사찰사료』를 보면 건물을 지을 때 조선 중종(재위 1506∼1544)의 비인 문정왕후가 참여했음을 알 수 있다. 앞면 3칸·옆면 4칸 규모로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 지붕을 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 있는 다포양식이다.","a":"장성 백양사 극락보전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639855.jpg"},{"q":"조선중기 헌마공신(獻馬功臣) ○○○ 분묘는 비교적 정확한 축조시기를 알 수 있어, 17세기 제주분묘의 산담과 봉분의 축조양식 및 구조를 파악할 수 있는 자료이다. 묘역 내에는 동일시기로 추정되는 봉분 1기, 혼유석(魂遊石) 1기, 비석 1기, 문인석 2기 등이 있으며, 문인석은 돌하르방과 같은 형태의 제주형으로 제주 고유의 석물문화를 밝히는데 중요자료가 된다. 헌마공신 ○○○은 1592년부터 인조대(1623~1649)에 걸쳐 계속된 전쟁당시에 자신의 제주마를 수차 국가에 헌납하여 ‘헌마공신’이란 칭호를 받았다.","a":"의귀리 김만일묘역","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658019.jpg"},{"q":"○○○은 토지의 신 사(社)와 곡식의 신 직(稷)에게 제사를 지내던 곳이다. 조선시대 ○○현의 ○○○에 관한 기록은 1530년에 간행된 『신증동국여지승람(新增東國輿地勝覽)』에 처음 등장하며, 이후 『여지도서(輿地圖書)』(1757～1765), 『경상도읍지(慶尙道邑誌)』(1832), 『조선후기지방지도(朝鮮後期地方地圖)』(1872), 『교남지(嶠南誌)』(일제강점기) 등의 문헌에 꾸준히 보이고 있다. 모든 기록에 ○○○은 현의 서쪽 1리에 위치한다고 하였는데, 실제로 현존하는 ○○○은 위치나 방향 등에서 기록의 내용과 일치한다.","a":"창녕 사직단","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657585.jpg"},{"q":"충청북도 ○○군 ○○읍 신정리에 있는 높이 7m의 커다란 불상으로 타원형의 얼굴에 은근한 미소가 보인다. 머리 꼭지에는 벙거지 같은 것이 올려져 있는데 나중에 고친 것이 아닌가 생각된다. 목에는 3줄로 새겨진 삼도(三道)가 있고 그 아래에 표현된 목걸이 장식은 얼굴과 함께 불상을 돋보이게 하고 있다. 신체는 부피감이 거의 없는 커다란 직사각형을 이루고 있다. 옷은 가슴을 드러낸 채 양 어깨에 걸쳐 입었고 하체에는 U자 모양의 주름을 겹쳐 나타냈다. 가슴 앞에 들고 있는 오른손이나, 연꽃을 들고 배에 댄 왼손은 작게 표현되었다.","a":"진천 용화사 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638606.jpg"},{"q":"무덤은 관리하고 제사를 지내기 위해 지은 건물이다. ○○○ 윤전은 조선 중기 문신으로 광해군 2년(1610)에 과거에 급제하였으며, 1627년 정묘호란이 일어나자 김장생의 종사관으로 활약하였다. 1636년 병자호란 때에는 강화에 들어갔으나 성이 함락되어 자결하려 하였지만 실패하여 적병에게 피살되었다. 윤전은 인정이 두터우며 신중하다는 평을 들었으며 시호는 충헌(忠憲)이다. 이 재실은 ㄱ자형 구조로 한쪽 지붕은 옆면에서 볼 때 사람 인(人)자 모양의 맞배지붕이며, 다른 한쪽은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다.","a":"충헌공윤전재실","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661501.jpg"},{"q":"척화비는 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양세력을 배척하고 이를 온 백성에게 일깨워 주고자 전국의 중요 지역에 세워두도록 한 것이다. 비는 거북을 본뜬 듯한 단조로운 모습의 받침돌 위에 비몸을 세웠고, 비의 윗변 양쪽을 비스듬히 다듬었다. 고종 8년(1871)에 세웠으나, 한일합방 당시 일본인에 의해 두 조각으로 갈라져 땅에 묻혀 있었던 것을, 산청초등학교를 지을 때 발견하여 학교 교정에 복원해 놓았다.","a":"산청척화비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642172.jpg"},{"q":"경상남도 ○○군 금남면 ○○○의 바위굴 암벽에 선으로 새긴 불상이다. 보존 상태가 양호하며, 불상 옆에 9층 석탑이 조각된 특이한 형태를 하고 있다. 얼굴 표정은 자세히 알 수 없으나 머리 위에는 상투 모양의 머리묶음이 큼직하게 솟아 있다. 옷은 양 어깨를 감싸며 흘러 내리고 있다. 몸광배와 머리광배를 구분하여 광배(光背)를 표현했는데, 광배 안에는 아무런 장식이 없어 소박해 보인다. 구름을 타고 달을 업은 채 하늘을 나는 형상을 하고 있는 이 마애불은 고려시대에 만든 작품으로 추정된다.","a":"하동 금오산 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642164.jpg"},{"q":"조선 초기의 무신인 위양공 ○○○ 장군의 묘이다. 1419년(세종 1) 우군절제사로 이종무 등과 함께 대마도 정벌에 나가 크게 승리하였다. 묘역은 부인과 함께 매장된 쌍분(雙墳; 두개의 봉분)의 형태이다. 봉분은 사각형인데, 봉분 아래에는 2단으로 둘레석을 쌓아 봉분을 보하고 있다. 묘역은 계단식으로 올라가면서 계체석(階砌石; 묘역을 구분하는 편평하고 긴 경계석)을 경계로 3단으로 나뉘었는데, 조선 초기의 묘제 원형이 잘 남아 있다. 묘표는 ○○○ 봉분 앞에만 1기가 남아 있는데, 건립연대는 1509년(중종 4)이다.","a":"이순몽장군묘","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646331.jpg"},{"q":"○○○은 고려 공민왕 19년(1370)에 세운 절로 수도사라고도 한다. ○○○은 조선 중종 12년(1517)에 지었으며 광해군 9년(1617), 순조 14년(1814), 1910년 등 여러 차례 고쳐 세운 건물이다. 앞면 3칸·옆면 1칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 현판에는 ‘○○○’이라 써 있으나 나한전처럼 안쪽에는 나한상을 모시고 있다.","a":"수도암무루전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662129.jpg"},{"q":"중국 삼국시대 당시의 정치가였던 제갈공명을 모시는 사당이다. 『조선왕조실록』에 의하면 선조 38년(1605) 평안도 영유현에 공식으로 ○○○를 짓게 하였고, 그 후부터 왕들이 관원을 보내어 제를 올리거나 제문(祭文)을 지어 보낸 예도 있으며, 사액(賜額)의 예도 전하는데, 이 ○○○와의 연관성은 확실치 않다. 기와지붕을 얹은 건물로, 내부로 들어가면 2m 크기의 제갈공명 석고상과 함께 2.5m 높이의 관운장의 석고상이 있고, 그밖에 대북·소북·종 등 의식용 악기들을 갖추고 있다.","a":"와룡묘","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658040.jpg"},{"q":"○○○○는 고령 읍내 연조리 성지 내에 자리잡고 있으며, 대성전과 명륜당, 빈홍재, 창고 등이 배치되어있다. 현학이건기(縣學移建記)에 의하면 고령군 서쪽 2리(소재 불명)에 ○○○○를 창건한후 1701년(숙종 27)에 군수 구문유가 중건하였으나 향교터가 불길하다 하여 다음해 2월 현 위치로 다시 이건하였다. 대성전과 명륜당을 제외한 건물들은 근년에 신축했는데 빈홍재는 1917년 민간 재실을 이건한 것이며 외삼문은 1974년, 내삼문은 1983년, 동·서무는 1990년경에 각각 신축했다. ○○○○는 전학후묘 형식의 향교로 이산 기슭에 동남향으로 배치되어 있다.","a":"고령향교","c":"문화유산자료","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662871.jpg"},{"q":"화면중앙에 위치한 ○○○은 좌안7분면으로 왼손에는 주장자를, 오른손에는 염주를 쥐고 결가부좌하고 있다. 안면부는 백색을 바른 후 담묵선과 주선으로 윤곽을 잡았다. 눈의 상검선은 농묵으로, 하검선은 담묵으로 그었고 눈 양쪽 가장자리는 담묵으로 바림하였으며, 눈동자는 갈색을 바른 후 농묵으로 동공을 찍었다. 얼굴의 주름은 주색으로 긋고 그 주변을 엷게 바림하여 음영을 나타내었다. 머리의 정상부 모발과 수염은 백색의 짧은 선으로, 눈썹은 묵선과 백색의 세선으로 표현하였다. 인물은 흰 깃에 짙은 잿빛장삼위에 홍가사를 입은 후 녹색과 황색의 두 매듭으로 연결하였다.","a":"남해 용문사 경암당 진영","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001666223.jpg"},{"q":"◦ 보령출신의 조선전기 문신인 김극성(金克成, 1474~1540)의 위패를 봉안한 사당으로 창건연대는 알 수 없으나 처음에는 청라면 장산리에 세웠던 것을 청천저수지의 조성으로 수몰지구가 되자 1960년 후손들이 그의 묘소가 있는 이곳에 옮겼음. ◦ 보령지역에는 김극성의 후손인 광산 김씨들이 유력 성씨를 이루며 오랫동안 세거해 오고 있음. ◦ ○○는 목조 기와집으로 정면 3칸, 측면 2칸의 맞배지붕으로 출입문은 하나이고 토석 혼축으로 담장을 만들었음.","a":"광성부원군 사우","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661131.jpg"},{"q":"○○○는(靑山齋) 문광공 홍귀달의 후손인 우암 홍언충(寓庵 洪彦忠,1473~1508)의 재사(齋舍)로서, 정면 3칸, 측면 2칸의 맞배지붕 형태이다. 이곳을 중심으로 지금까지 이루어지고 있는 외손봉사(外孫奉祀)는 ○○지역의 전통 유교문화를 이해하는데 매우 큰 의미가 있다. ○○○의 건축적 평면구성은 재ㆍ정ㆍ당ㆍ정사(齋ㆍ亭ㆍ堂ㆍ精舍) 등의 유형 중에서 가장 앞선 형태에 속하며, 기능상으로 정자 역할까지 겸한 건물이라 할 수 있다.","a":"문경 청산재","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663539.jpg"},{"q":"사재(思齋) ○○○은 조선 중기 문신으로 형인 모재(慕齋) 김안국(金安國)과 더불어 기묘사화(己卯士禍)에 해를 입었던 인물이다. 1538년 복직되어 전라도관찰사, 중추부사, 돈녕부사 등을 지냈다. ○○○ 묘는 계배(繼配)인 경주이씨(慶州李氏)와 함께 쌍분(雙墳)으로 조성되어 있다. 묘소의 석물로는 묘표(墓表), 상석(床石), 향로석(香爐石), 망주석(望柱石), 장명등(長明燈), 문인석(文人石) 등이 있다. 묘역 하단에는 신도비도 건립되어 있다. 묘표는 원수방부(圓首方趺; 둥근 머릿돌과 사각 받침돌의 비석 형태) 형태로, 1546년에 건립되었다.","a":"사재김정국묘역","c":"문화유산자료","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019043008051100.PNG"},{"q":"○○○은 1624년 임진왜란 때 의병장인 사우당(四友堂) 김대진(金大振) 선생이 경상감사 이민구와 지역 사림의 협조로 건립하였으나 1721년 소실된 것을 1866년 그의 후손 김규한이 중건한 건물이다. 이 건물은 정면 5칸, 측면 1칸의 일자형 건물로 지붕은 옆면에서 볼 때 팔작지붕이다. 가운데 대청을 중심으로 오른쪽에는 1칸의 온돌방을, 왼쪽에는 2칸의 온돌방을 배치하였다.","a":"관수정","c":"문화유산자료","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659497.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 광령○○○ 제○○○는 남방식(2형식)으로, 지하매장주체 형식을 띄고 있으며, 장축 214㎝, 단축 123㎝, 두께 62㎝이다.","a":"광령리지석묘10호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657732.jpg"},{"q":"조선시대의 대표적인 음악가 ○○ 선생의 묘이다. 자는 탄부(坦夫), 호는 난계(蘭溪), 시호는 문헌(文獻)이며, 고구려 왕산악, 신라의 우륵과 더불어 우리나라 3대 악성으로 불린다. 태종 11년(1411) 문과에 급제하여 집현전 교리가 되었고, 세종이 즉위한 뒤 악학별좌에 올라 음악을 정비하는데 많은 노력을 기울였다. 조율의 필요와 악보 편찬의 중요성을 상소하여 수많은 악기와 악보를 만들어냈으며, 조선 초기의 궁중음악을 정리하여 국가의 음악 체제를 세우는데 많은 기여를 하였다.","a":"영동 박연 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650022.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생의 행적을 기리고 있다. ○○○은 선조 22년(1580) 문과에 급제하여 승문원에 등용되었다. 임진왜란(1592), 이봉학의 난(1596), 이괄의 난(1624) 당시 큰 공을 세웠으며, 생을 마친 후에는 영의정에 추증되었다. 선조, 광해군, 인조에 걸친 세 임금을 섬기면서 백성의 생활안정과 지방민을 평온하게 하였던 그의 공로를 찬양하고자 이 비를 세웠다.","a":"진천 이시발 신도비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638612.jpg"},{"q":"경상북도 김천시 어모면 ○○○의 넓은 바위면에 높이 2.9m로 돋을새김한 마애○○○이다. 머리에는 삼산관(三山冠)을 쓰고 있으며, 왼쪽 어깨만을 감싸고 있는 옷은 두껍게 표현하였다. 손모양은 오른손을 무릎 위에 올려 손등을 위로 향하게 하고, 왼손은 손바닥을 위로 향하게 하여 왼쪽 무릎 위에 놓았다. 오른발을 왼쪽 무릎에 올리고 있는 반가(半跏) 자세이며, 연꽃이 새겨진 대좌(臺座) 위에 앉아 있다.","a":"금릉은기리마애반가보살상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640780.jpg"},{"q":"조선 전기의 문신인 문효공 하연 선생과 그 부인의 초상화이다. 하연은 조선 태조 때에 문과에 급제한 후, 우의정과 좌의정을 거쳐 세종 31년(1449)에는 영의정에 까지 올랐다. 그의 문집인『경재집』에서는 원래 효성이 지극하고 그림에도 뛰어났던 아들 하우명이 이들의 초상화를 직접 그린 적이 있다고 적고 있다. 이로 미루어, 이 그림 역시 하우명이 그린 원본을 보고 옮겨 그린 것으로 추정되는데, 합천이나 청원의 영당에 보존되고 있는 부부상에 비해 높은 품격을 갖추고 있다.","a":"문효공과 정경부인 영정","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639482.jpg"},{"q":"○○○은 조선 후기 선비인 김형진이 지은 집으로, 경포호가 바라보이는 경포대 북쪽 시루봉 아래에 자리잡고 있다. 주변에는 매화를 심어 학과 더불어 노닐던 곳이라 하여 매학정(梅鶴亭)이라 이름하였다. 그 뒤 주인이 바뀌어 지금 있는 자리로 옮겨 지으면서 이름을 ○○○이라 고쳐 불렀다. 건물 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면에는 ‘○○○’이라는 현판이 걸려 있고，옆면에는 ‘경중별업(鏡中別業)’이라는 현판이 걸려 있다.","a":"금란정","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660311.jpg"},{"q":"인주면 ○○○ 언덕에 자리하고 있는 천주교 성당이다. 130여 평 규모에 본당·사제당·피정의 집·회합실 등의 건물이 있고 병인박해 때 순교한 3인의 묘가 조성되어 있다. 본당은 1층 적벽돌 건물로, 정면에는 높은 첨탑이 있고, 내부에는 무지개 모양의 회색 천장이 마련되어 있다. 사제관은 2층 벽돌 건물로, 정면이 팔자(八)계단으로 2층을 오르게 되어있으며, 계단 아래에 1층 입구를 두었다. 1894년 교회를 설립하였고, 1897년에 사제관을 세웠으며, 1922년 연와조 고딕양식의 근대식성당을 완성하였다.","a":"아산공세리성당","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653038.jpg"},{"q":"야산을 뒤로하고 있는 이 집은 마을의 제일 높은 곳에 위치하고 있다. 집을 지은 정확한 연대는 알 수 없지만 약 200년 정도 되었다고 하며, 현재 경주 김씨의 후손이 살고 있다. 전체적으로 H자 모양을 하고 있는 전형적인 겹집으로, 안채와 사랑채·부속건물로 되어 있다. 안채와 사랑채는 지붕 옆면이 여덟 팔(八)자 모양의 화려한 팔작지붕집이고, 부속채는 사람 인(人)자 모양의 단순한 맞배지붕집이다. 안채는 6개의 방이 겹쳐서 배치되었고, 그 오른쪽으로 샛방을 만들어 사랑채와 연결하고 있다. 사랑채 2칸은 외부에 툇마루를 놓아 연결통로로 활용하고 있다.","a":"양양김택준가옥","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638090.jpg"},{"q":"원나라의 염상이 석가여래의 탄생에서 고려 충숙왕 3년(1334)까지의 고승대덕(高僧大德)의 전기를 편년체(編年體:사건을 시간의 순서대로 기록하는 역사서술의 한 방식)로 수록한 책이다. 모두 22권 10책으로 구성되었는데 현재 ○○○에는 권2∼5가 빠져 9책만이 소장되어 있다. 이 책은 선조 9년(1576)에 전라도의 사자산 쌍봉사에서 약간 수정하여 다시 간행한 것이다. 하지만 이것은 세종 12년(1430)에 대자은사 광의(廣議)에 의해서 중간되어 유통되었던 목판을 다시 중간한 것이다. 조선 전기의 목판 인쇄와 왕실의 불교신앙 양상을 알 수 있는 중요한 자료이다.","a":"범어사 불조역대통재","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636673.jpg"},{"q":"한강 이남에서 발굴조사된 6세기 전반의 신라 때 만든 굴식돌방무덤(횡혈식석실분)이다. 구조는 매우 큰 편이고 특이한 내부 형식을 갖추고 있다. 돌방무덤에는 옆방(측실)이 설치되어 추가장 되었던 것으로 생각된다. 널길(연도)의 옆면에 부실이 딸리고 현실 안에는 2개의 벽감이 설치되어 있다. 도굴된 상태였으나 관장식, 달개(영락), 금반지 등 많은 유물이 출토된 것으로 보아 이 지역 수장층의 무덤으로 추정된다. ○○○ 무덤들 주변에는 이 무덤외에도 86기 이상이 분포하고 있어 중요한 연구자료가 되고 있다.","a":"영일 냉수리 고분","c":"시도기념물","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654557.jpg"},{"q":"○○○○○은 \"기미(1919년) 3·1운동\"보다 5개월 먼저 일어난 제주도내의 최초 최대의 ○○○○이자 1910년대 종교계가 일으킨 전국 최대 규모의 무장○○○○이다. 1918년 10월 7일(월) 서귀포시 도순동 산1번지에 있는 ○○○에서 평소 일본제국의 통치를 반대하던 불교계의 김연일(金連日) · 방동화(房東華) 등 승려들이 중심이 되어 ○○○ 신도와 ·선도교도 · 민간인 등 700여명이 집단으로 무장하여 2일 동안 조직적으로 일본에 항거한 ○○○○으로서, 1919년대의 3·1운동을 비롯하여 민족항일의식을 전국적으로 확산시켜나가는 선구적인 역할을 하였다.","a":"무오법정사항일운동발상지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658004.jpg"},{"q":"백촌 김문기(1399∼1456)의 학문과 덕행을 추모하기 위해 세운 서원이다. 김문기는 조선 전기의 문신으로 형조참판·공조판서 등을 역임하였고, 세조 2년(1456) 사육신에 연루되어 처형되었다. ○○○○은 인조 3년(1625)에 세웠고, 흥선대원군의 서원철폐령으로 고종 5년(1868)에 해체되었다가 1948년 지방유림이 복원하였다. 경내의 대표적인 건물로는 상충사, 경의당 등이 있다. 상충사에는 김문기의 위패를 모시고 있고, 경의당은 앞면 4칸·옆면 2칸 규모의 강당이다. 중앙에 마루를 두고 양쪽으로 온돌방을 배치한 형태로 유림들이 모임을 갖는 장소로 사용되었다.","a":"덕양서원","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662951.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호화고, 군사적·행정적인 기능을 함께 하는 성을 말한다. 경상남도 밀양시 ○○○○은 성종 10년(1479)에 만든 것으로, 다른 읍성들을 임진왜란 직전에 만들기 시작한 것에 비하면 100년 이상 일찍 만든 것이다. 『동국여지승람』의 기록에 따르면 ○○○○은 둘레가 4,670척, 높이 9척이며 성 안에 우물이 4개, 연못이 1곳 있다고 한다. 1902년 경부선 철도부설 공사 때 성문과 성벽을 모두 헐어 철도부설공사에 이용하여, 지금은 성문의 위치와 일부 성곽만 남아 있다. 아동산과 아북산을 잇는 산등성이에는 성곽이 남아 있다.","a":"밀양읍성","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656045.jpg"},{"q":"이 곳은 ○○○○○가 있던 자리로, 1960년대 말 도심의 확장과 함께 ○○○가 이전하면서 담장과 ○○○ 본관은 철거되었다. ○○○○○는 3·1운동 이후 계속적으로 만세운동이 이어지자 독립 투사들을 수감하기 위해 일제가 소규모로 설치하였던 것을 1939년 대규모 시설로 확장·준공하였다. 도산 안창호 선생을 비롯한 많은 독립 투사들이 수감되어 옥고를 치렀고, 6·25전쟁 때는 연합군에 쫓기던 북한군이 1,300여 명의 양민을 포함 6,000여 명을 무참하게 학살하기도 하였으며, 근래에는 화가 이응로가 수감되기도 한 곳이다.","a":"구대전형무소망루","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659761.jpg"},{"q":"○○○을 언제 지었는지 정확한 기록은 없으나, 양팽손(1488∼1545)과 김종직(1431∼1492)의 시로 미루어 조선 전기 관청에서 지은 것으로 추정된다. 인조 10년(1632)에 능주목사 정연이 아전들의 휴식처로 고쳐 지었다고 전하며, 고종 9년(1872)에 불타 버린 것을 고종 10년(1873)에 새로 고쳐 지었다. 이후에도 보수를 거듭해 오다가 1920년에는 주민들이 모은 비용으로 손질하여 고쳐 지었다. 앞면 3칸·옆면 2칸 규모의 2층 누각이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄는데 3겹으로 처리한 것이 특징이다.","a":"영벽정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662001.jpg"},{"q":"경상북도 성주군 가천면 해발 955m의 독용산 정상에 있는 산성으로, 둘레가 7.7㎞에 이른다. 성 안에 물이 풍부하고 활용공간이 넓어 장기전투에 대비하여 만들어진 것으로 보인다. 이와 같이 계곡을 포함하여 산정을 두른 형태를 포곡식이라 하는데, 영남지방의 산성 중 가장 큰 규모이다. 성이 만들어진 시기는 정확하지 않으나 가야 때 쌓은 것으로 추정되며, 임진왜란을 피하던 중에 발견되었다고 한다. 이 성은 임진왜란 때 전쟁의 화를 입지 않은 유일한 성이기도 하다.","a":"독용산성","c":"시도기념물","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654572.jpg"},{"q":"당초 안동부의 우향계는 조선 태종 때 좌의정을 역임한 이원(1368∼1430)의 아들 이증(李增)이 안동으로 낙향하여 학덕있는 안동의 선비 12명(안동권씨 3명·흥해배씨 4명·영양남씨 4명·안강노씨 1명)과 함께 우향계를 조직하고 회원 13명이 ‘계첩’을 하나씩 나누어 가졌다. 그것에는 회원 13명의 직역·성명·본관·아버지의 직역과 이름을 기재한 명부와 원첩 및 당시 문호인 서거정(1420∼1488)이 조선 성종 9년(1478)에 쓴 7언시의 송시(頌詩)가 첨부되어 있다.","a":"우향계안","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641063.jpg"},{"q":"조선시대 홍성지방 관리들이 업무를 처리하던 곳이다. 행정업무를 처리하던 동헌과 치안업무를 처리하던 형방청, 책과 문서를 보관하면서 관리의 자제가 지내던 책실로 구성되어 있다. 동헌은 고려말에 결성면 금곡리 분우터에 있다가 정종 2년(1400)에 결성읍 산성 정상으로 옮겼다．현종 6년(1665) 현재의 위치인 읍내리에 다시 지었고, 이후 여러 차례 고쳐 지었다. 동헌은 앞면 5칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"결성동헌","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661387.jpg"},{"q":"이 2구의 불상은 1740년 10월 도봉산 원통암(圓通菴)에서 조성되어 진관암(津寬菴)에 봉안되었던 불상으로 현재 ○○○에 함께 모셔져 있다. 복장에서 발견된 조성원문(造成願文)에 의하면 이 상을 만들기 이전에 원래 아미타삼존이 있었으나 어떠한 연유로 ○○○○상과 ○○○○○이 훼손되고 관음보살만 남게 되자 1740년 인성(印性), 치준(緇俊), 지한(智閑), 삼안(三眼), 충신(忠信) 등의 조각장이 ○○○○상과 ○○○○○을 만들었으며, 그 후 도금한 것이 벗겨지자 1856년에 새로 도금하였다고 전한다.","a":"도선사 목 아미타불·대세지보살상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590623.png"},{"q":"이 묘역은 조선 제 9대왕인 성종(成宗)의 손자로 임진왜란 때 선조를 호종(扈從)한 공로로 선무종훈(宣武從勳)된 바 있는 ○○○○○의 분묘와 그 부인인 현부인(縣夫人) 평강채씨(平康蔡氏)의 분묘가 자리한 묘역으로 현재 동작동 국립현충원 안에 위치하고 있다. ○○○○○는 성종과 명빈김씨(明嬪金氏)와의 사이에 난 무산군(茂山君)의 아들로 중종 19년(1524) 태어나 선조 31년(1598) 세상을 떠났다. 처음 창선대부(彰善大夫) 부안정(扶安正)을 제수 받았으나 갑진년에 혼전(魂殿)에 입직한 공로로 명선대부(明善大夫) 도정(都正)을 제수 받았다.","a":"부안군이석수묘역","c":"문화유산자료","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314310900.jpg"},{"q":"고려 왕조의 마지막 임금인 ○○○의 묘로 전하는 곳이다. ○○○은 1392년 이성계가 왕위에 오르면서 폐위되었고, 태조 3년(1394)에 왕자 석(奭), 우(瑀)와 함께 삼척으로 간 뒤 교살되었다. ○○○○은 강원특별자치도 삼척시와 경기도 고양시 두 곳에 있는 것으로 전해지는데, 문헌의 기록이 부족하여 어느 쪽이 왕릉인지 확실히 알 수 없다. 고양시의 능은 조선 왕조가 인정하고, 삼척시의 능은 민간에서 전해 내려오는 것이나 둘 다 조선시대 문헌에 남아있기 때문이다.","a":"삼척공양왕릉","c":"시도기념물","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648412.jpg"},{"q":"전남 영암군 서호면 장천리에 있는 충효문으로, 임진왜란 때 큰 공을 세운 전몽성(1561∼1597) 장군 형제의 충절과 효성을 기리고자 세운 것이다. 전몽성은 선조 16년(1583)에 무과에 급제하여 여러 관직을 역임했고 임진왜란(1592)이 일어나자 왜구를 무찔러 큰 공을 세웠다. 정유재란(1597) 때 동생 몽진 등과 의병을 일으켜 왜적을 무찌르다가 해암포 싸움에서 전사하였다. 동생 전몽태 장군은 선조 36년(1603) 무과에 급제하여 여러 벼슬을 거쳐 인조 2년(1624) 이괄의 난 때에 큰 공을 세웠다.","a":"전씨충효문","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654199.jpg"},{"q":"산청 ○○○에 있는 나무로 만든 아○○○○○상이다. 가운데 본존인 ○○○여래상을 중심으로 왼쪽에는 관음보살상이 배치되고 오른쪽에는 대세지보살상이 자리하고 있다. ○○○의 크기는 1m 이상의 사람의 키만 한 불상으로서, 자세는 등을 세우고 고개를 약간 숙인 모습의 반가부좌상으로 전체적으로 균형감 있는 모습이다. ○○○여래상은 머리는 육계의 구분이 명확하지 않으며 정상계주와 중앙계주를 표현하였고, 나발의 표현이 촘촘한 편이다. 얼굴은 방형에 가깝고, 턱선을 비교적 둥글게 처리하였으며, 이목구비가 뚜렷하여 서로 조화를 이룬다.","a":"산청율곡사목조아미타삼존불좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642350.jpg"},{"q":"○○란 절에서 사용하는 도구로, 대중을 불러모으거나 급한 일을 알리는데 사용하는 금속으로 만든 타악기이다. 보광전 법당에 걸어 지금까지도 사용되고 있는 이 ○○는 바깥지름 67.7㎝ 안지름 54.8㎝ 너비 12.6㎝이다. 표면 둘레 가장자리에는 별다른 문양이 없으며 중심부 역시 문양이 없는 소박한 형태이다. 옆면에는 시주자명과 건륭 49년에 제작되었다는 내용의 글이 새겨져 있어 정조 8년(1784)에 만들어진 것임을 알 수 있다. 이 ○○는 보존상태가 양호하며, 옆면의 글을 통해 시주자명과 제작연도를 알 수 있는 중요한 자료이다.","a":"통영 용화사 금고","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642337.gif"},{"q":"○○○을 고쳐 짓고 이를 기념하기 위하여 세운 비이다. 홍주는 서해로 가는 길목으로 교통의 중심이며, 충청 서부지역의 군사적 요충지가 되는 곳이다. ○○○은 조선시대 문종 1년(1451) 지방행정구역을 개편하면서 쌓아 놓은 곳으로, 민종식, 이세영, 채광묵, 안병찬 등이 일제에 의해 강제로 체결된 을사조약에 반대하며 의병을 일으켜 이곳에 와서, 성에 머물러 있던 일본군을 덕산으로 쫓아내 성을 되찾았던 전투로 유명하다. 비문에는 순조 24년(1824) 진장 김계묵과 목사 이현규가 이 성을 돌아보고 성이 황폐해진 모습에 탄식하여 수리하게 되었다는 내용이 적혀있다.","a":"홍주성수성비","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661163.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 묘 남동쪽에 세워두는 비로, 이 비는 통일신라말의 학자인 ○○○ 선생을 기리고 있다. ○○○은 통일신라말에 새로 성장하는 6두품 출신의 지식인 가운데 가장 대표적인 인물로, 문장가로도 잘 알려져 있다. 12세의 어린나이로 당나라에 유학가서 7년만인 18세에 과거에 급제하였고, 그후 2년동안 중국의 낙양지역에 머물면서 시를 짓는데 몰두하기도 하였다.","a":"함양 최치원 신도비","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663980.jpg"},{"q":"1. 내용 * 上書(丁巳(1857) 11월): 대구 角初同面 주민 (일부 파손) 등이 암행어사에게 올림. 각초동 臺山里에 살던 文日泰가 모친에 대한 효행이 극진했던 것에 감복하여 대구 유림들이 大丘府와 감영에 정장을 올렸고, 이에 대해 감영과 본 고을에서 음식 및 금전 등을 상으로 내렸으나, 아직 정부에 장계를 올려 정려가 내려지도록 하는 조처가 취해지지 않았음. 이 사실을 조정에 알려 旌褒의 은전이 베풀어지도록 해 달라고 요청. 제사: 聞甚嘉尙 褒揚之節 當博探裁處事. * 上書(壬戌(1862) 4월): 대구 유생 徐恪贊 등이 관찰사에게 올림.","a":"창녕박물관 소장 남평문씨 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666646.jpg"},{"q":"○○○○는 조선 광해군 2년(1610)에 악사 양덕수(梁德壽)가 엮은 거문고 악보이다. 양덕수가 임진왜란을 피해 남원에 은거하고 있을 때 거기서 옛 친구인 임실현감 김두남(金斗南)을 만나 그의 권유에 따라 엮은 것이다. 판본은 여러 종류가 있고, 그 영인본이 국립중앙도서관에 보관되어 있다. 강태중씨 소장의 이 거문고 악보는 필사본으로 모두 30장 1책이다. 가로 21㎝·세로 30.3㎝ 크기의 한지로 되어 있다. 비록 필사본이기는 하나 전국적으로 그 존재가 희귀하므로 가치가 높다.","a":"양금신보","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664796.jpg"},{"q":"○○○은 상량문에 따르면 1897년에 지었다. 이 당안의 돌들은 양근석 모양이었으나 모두 도둑맞았다. 보성군민들은 고목을 신체로 섬기고 있으며, 이곳처럼 양근석을 7개나 모신것은 보기 드문 일이다. 이곳 주민들은 돌 일곱개는 칠성님을 상징한다고 말하고 있다. 그리고 칠성신체인 돌은 양근석을 닮아서인지 아기 못 낳은 여인들이 공을 들이는 장소로 많이 이용되었다. 또 양근 귀두부분을 여자들이 깍아가서 수난을 당하기도 하였다.","a":"보성당촌별신당집및당제","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658401.jpg"},{"q":"조선 선조 25년(1592) 동래부사(東萊府使)로 재임 중 발발한 임진왜란의 동래성 전투에서 맞서 목숨을 바친 천곡(泉谷) ○○○의 업적을 알려주는 기록물들로서 임진왜란(壬辰倭亂) 당시 동래성전투(東萊城戰鬪) 상황 및 천곡 ○○○의 인품을 알 수 있는 귀중한 자료들이다. 천곡 ○○○ 유물은 동래부순절도(東萊府殉節圖) 1점, 교지(敎旨) 3점, 치제문(致祭文) 4점, 혈선발(血扇跋) 1점, 혈선도 1점,『천곡수필집(泉谷隨筆集)』 1점, 『천곡수필집(泉谷隨筆集)』 1점 등 총 12점이다.","a":"송상현 문적","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638796.jpg"},{"q":"동서로 서 있는 쌍탑으로, 탑을 품었던 절터는 민가와 경작지로 변하여 탑 이외의 다른 유물은 남아있지 않다. 2층 기단(基壇)위에 3층의 탑신(塔身)을 올린 모습이며, 두 탑이 거의 같은 규모와 양식을 갖추고 있다. 기단에는 기둥모양과 불법을 수호하는 8부신중(八部神衆)을 조각하였고, 탑신의 몸돌에는 기둥모양만 새겨 놓았다. 지붕돌은 밑면의 받침이 5단씩이다. 꼭대기에는 네모난 받침돌위로 둥근 머리장식이 남아 있다. 기단에 장식된 조각수법이나 각 부분의 짜임새로 보아 통일신라시대에 세운 것으로 추정된다.","a":"중금리삼층석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637900.jpg"},{"q":"임진왜란 때 밀양 박씨 문중의 14명이 의병운동을 일으켜 왜적과 싸웠던 일들을 기록하여 새긴 목판이다. 206매로 구성되어 있으며, 1매에 20행 18자로 이루어져 있다. 책의 간행에 있어 기초로 삼은 것은 정조 18년(1794) 혹은 21년(1797)에 간행된『충효록』이나, 후손 박정상이 지은『박씨충효록』이다. 하지만 이들 자료는 모두 임진왜란 당시의 기록이 아니라 200여년이 지난 후의 사실이라 그 자료적 가치에 한계를 지니고 있다.","a":"십사의사록판목","c":"문화유산자료","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662587.jpg"},{"q":"영양 남씨 괴시파종택(경상북도 민속문화유산) 오른쪽에 서향으로 자리잡고 있다. 규모는 앞면 3칸·옆면 1칸 반이고, 큰마루 앞면에는 4짝 여닫이문을 설치하여 마루방으로 꾸몄다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄으며, 서당 주위에는 네모반듯한 모양의 담장을 둘렀다. 또한 앞면 담장 사이에는 4개의 기둥문을 세워 출입구로 삼았다.","a":"물소와서당","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663283.jpg"},{"q":"19세기 말 미국 감리교회가 파견한 여자 선교사들의 ○○○로 사용했던 곳이다. 양철(함석)지붕으로 구조가 독특하며, 벽체는 빨간 벽돌로 쌓았다. 창호는 조선시대 서원이나 절의 승방 등에서 사용하던 방법을 빌어, 쓸 용(用)자 모양으로 꾸몄고, 가장자리는 빗살 모양으로 짜 넣었다. 내부는 목조로 되어 있으며, 2층 가로축에 지하로 드나들 수 있도록 시설하였다. 비교적 원형을 잘 보존하고 있는 근세 르네상스 양식의 건물이다.","a":"인천 구 여선교사 합숙소","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111916082200.jpg"},{"q":"진주 ○○○ 밀○○○○○는 1710년까지의 밀성 손씨를 전국적으로 망라하고 있는 대동보의 성격을 지니고 있으며, 특히 이 책의 간행을 주도한 것으로 보이는 孫佺(1634-?)의 상세하고도 치밀한 주석이 곳곳에 보임으로써 사실의 기술에 객관성을 인정할 만하다. 자녀를 기술하는 순서가 生年順이 아니라 先男後女로 바뀌었으며, 外孫의 기술에 있어서도 사위 이후 3대까지 기록되어 있다. 그래서 때에 따라서는 外孫壻의 外孫壻까지 알 수 있을 정도로 자세하다.","a":"진주원계리밀양손씨경인보","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665876.jpg"},{"q":"조선 순조 13년(1813)에 만들어진 것으로 크기는 높이 67㎝, 음통 높이 22㎝, 종입구 지름 55㎝이다. 종은 전체적으로 어깨 부분은 완만한 곡선을 이루다가 중간 부분부터 종 입구까지는 거의 직선으로 처리되었다. 종 머리에는 종을 매다는 용뉴와 음통이 있는데, 용뉴는 용의 머리를 조각하였으나 약식화되었고 조선시대 종에는 생략된 소리의 울림을 좋게 하는 음통은 모양만 갖추었을 뿐 구멍은 막혀 있다. 종은 전체적으로 가로로 선을 돌려 세부분으로 나뉘었다.","a":"봉정사동종","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663295.jpg"},{"q":"호지마을에 자리잡고 있는 이 집은 조선 순조 5년(1805)경 지은 건물이라고 한다. 호지마을의 집들은 산을 등지고 있으면서 서향으로 자리잡고 있는 것이 특징이다. 구계댁 역시 다른 집들과 마찬가지로 서향이면서 사랑채는 남향으로 배치한 이 마을 특유의 배치 유형을 따르고 있다. 건물은 크게 사랑채, 안채를 중심으로 구성되어 있으며 ㅁ자형 평면을 갖추고 있다. 사랑채는 사랑마루·사랑마루방 등을 배치해 놓았으며 앞면에는 퇴칸을 두고 마루방 앞면 마루는 퇴칸보다 길게 내밀었다. 안채는 앞뒤 2열로 공간을 나눈 겹집 형태이다.","a":"영해구계댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663285.jpg"},{"q":"○○○○은 석가모니불의 진신사리를 모셔놓는 건물을 가리킨다. ○○○○○은 지은 시기를 정확하게 알 수 없으나, 영조 47년(1771)에 고쳐 지은 것으로 미루어 18세기 초에 세운 것으로 추정되며 이 후에도 여러 차례 보수하였다. 이곳은 신라 선덕여왕 때 자장율사가 석가모니불의 사리를 ○○○에 수마노탑을 세워 안치하고 이를 지키기 위해 세운 것이다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식으로 꾸몄다.","a":"정암사적멸보궁","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660377.jpg"},{"q":"○○○의 독성탱은 민화풍의 산수 배경과 독성의 수도 장면으로 구성되어 있는 조선후기 일반적인 ○○○의 형식을 갖고 있으며, 화면전체를 메우는 독성의 안정된 자세, 눈빛 등으로 나타나는 수도자의 정신세계를 잘 표현하고 있다. 또한 화면의 단조로움은 청조의 다양한 자세를 통해 화면에 생명감을 주고 있는 점도 주목된다. 비록 최근에 중수되었다고는 하나 전체적인 화면의 짜임새와 구도가 좋으며, 창의적인 구성은 독성탱의 다양한 면모를 보여주는 것으로서 조선후기 불교회화의 한 경향을 파악하는 자료이다","a":"의령 천지사 독성도","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666345.jpg"},{"q":"○○○은 450여년전 무오사화를 파하여 온 보령현감 김수양이 건립하였던 것을 다시 1871년에 중건하였으며 가조면 대초리 선산김씨 집성촌 중앙에 위치해있다 양질의 건축부재와 수려한 건축미를 보이며 원형이 잘 보존되어 있음.","a":"거창 취수정","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017091317325100.jpg"},{"q":"○○○ 지눌(1158~1210)의 저술인 ○○○을 비현합(丕顯閤)에서 구결(口訣)하고 신미(信眉)가 역해(譯解)하여 세조 때 간경도감(刊經都監)에서 간행한 것을 연산군 6년(1500)에 가야산(伽倻山) 봉서사(鳳栖寺)에서 번각(飜刻)한 판본이다. ○○○은 지눌이 선수행의 요체인 마음 닦는 비결을 제시한 책으로 수심의 기초가 되는 공적영지심(空寂靈知心)의 성격을 밝히고 수심(修心)의 체계로서 돈오점수론(頓悟漸修論)의 내용과 구체적인 실천방안으로서 정혜쌍수론(定慧雙修論)을 9개의 문답형식으로 서술하고 있다.","a":"목우자 수심결·법어","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593213.png"},{"q":"○○○ 씨가 소장한 전적은 모두 필사원본(筆寫原本)으로서 조선 후기 및 한말의 정치·경제·사회·법제사 및 재지사족(在地士族)들의 범절과 서예사 연구에 중요한 자료이며, 특히 『훈령(訓令)』은 1895년부터 1901년까지 경상도관찰사가 선산에 하달한 훈령을 비롯하여 탁지부(度支部, 재정담당 중앙부서)와 내무부의 훈령과 칙령 등을 연월순으로 등록, 정리한 것으로 근대 행정사 연구에 귀중한 자료로 평가된다.","a":"선산노진환소장전적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641101.jpg"},{"q":"정규한의 제자와 유생들이 선생의 영정을 모시기 위해 조선 순조 32년(1832)에 세운 사당이다. 정규한(1750∼1824)은 조선 후기의 학자이며 호는 화산 또는 운수산인이다. 정조 4년(1780) 과거에 합격하였으나 벼슬에 뜻이 없어 관리로 나가지 않고 성리학 연구에 몰두하였다. 평소 산수와 자연을 좋아하고 시문을 즐겨 문장가로도 유명하였다. 그의 저서로는 『화산집』이 있다. 영정을 모신 사당 뒤쪽에 묘소가 있고 1962년 유림과 후손들이 사당을 중심으로 화산사를 지었다.","a":"화산영당","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660992.jpg"},{"q":"한말 의병장으로 활약했던 김도현(1852∼1914)이 개인재산을 털어서 항일운동을 위해 쌓은 산성이다. 경상북도 영양군 청기면의 검산은 동쪽에 하천이 흘러 절벽을 이루고, 북쪽과 서쪽은 경사가 심하며, 남쪽은 경사가 완만한 대지를 이루고 있다. 산성은 이러한 산의 지형을 이용하여 산 정상에서 남쪽을 향하여 서쪽과 남쪽에 성벽을 쌓아 올렸다. 서쪽의 경사면에는 약 200m 길이의 돌과 흙을 섞어 쌓았던 성벽의 흔적이 남아있다. 남쪽은 대지를 이용해서 그 둘레에 성벽을 쌓았으나, 동쪽은 자연 벼랑을 이용하고 따로 성벽을 쌓지 않았다.","a":"검산성","c":"시도기념물","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654507.jpg"},{"q":"밀성 박씨 우윤공파 가곡종중에 대대로 보관되어 온 ○○○이다. 『초문기』와『초문기원안』은 현종 4년(1663)에 당시 가선대부 한성부우윤 ○○○ 선생이 슬하의 적첩자녀 22명에게 재산을 분배한 재산분재문서이다. 이 문서는 당시 ○○○ 가문의 재산현황과 조선시대 사회·경제사를 연구하는데 참고가 되는 자료이다.","a":"박선승 관련 고문서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642285.jpg"},{"q":"○○○는 병자호란 당시 김화에서 큰 성과를 올린 홍명구와 유림 장군의 위패를 모신 사당이다. 조선 효종 1년(1650)에 지어져, 효종 3년(1652) ○○○라 이름지어 그것을 새긴 현판을 하사하였다. 『강원도지』에 의하면 후에 고쳐 지은 기록이 남아있으나 연대는 알 수 없고, 한국전쟁 당시 파손되었던 사당, 내삼문, 담장 등을 1998년 새로 고쳐지었다. ○○○에는 홍명구 충렬비와 유림 대첩비가 남아 있으며, 1997년에 비문 보호를 위해 보호각을 세워 보존하고 있다.","a":"철원충렬사지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648422.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나로, 모두 90종 166책이 나왔다. ○○○○○상의 배속에 들어있던 유물 중에서 가장 많은 책수를 보이고 있는데, 대부분 예수재(살아 생전에 미리 수행과 공덕을 닦아 두는 재의식)와 수륙재(물이나 육지에 있는 외로운 귀신이나 배고파 굶주리는 아귀에게 공양하는 법회)에 관련된 문헌들이다.","a":"보림사사천왕상복장진언ㆍ의식관계불서","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814432000.jpg"},{"q":"○○대는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며, 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○시 상모면 온천리와 괴산군 장연면 추정리의 경계부분인 ○○○ 봉우리에 있는 이 ○○대는 고려시대에 축조되어 조선시대까지 이용된 것으로, 남쪽의 미륵리 마골재에서 ○○를 받아 북쪽의 대림산 ○○대에 전하였다. 한국전쟁 당시 대부분 훼손되었으나 발굴조사 결과 남북으로 긴 타원형의 방호벽, 석등을 갖춘 남북 2곳의 출입구, 화구(火口)와 화덕을 갖춘 봉조 5개소가 확인되었다.","a":"충주 주정산 봉수","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650646.jpg"},{"q":"1900년경 진씨 가문의 제사를 지내려고 지은 집(재실)으로 한·일 절충식 건물이다. 지을 당시에는 앞면 5칸·옆면 1칸 반의 규모였으나, 나중에 뒤쪽 부분 전체를 반칸씩 늘려 겹집처럼 되어 있다. 마루는 장마루를 깔고 마루 밑에 붉은 벽돌을 쌓았으며 유리창문을 사용했다. 천장도 일본식에 가까운 우물반자로 꾸며 놓았다. 20세기 초 건축 양식의 새로운 경향을 보이는 건물로, 전통 양식이 일본 건축의 영향을 받아 변화하여 가는 모습을 잘 보여주고 있다.","a":"야수정","c":"문화유산자료","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659472.jpg"},{"q":"문경공(文敬公) 허조(許稠)의 위패를 모시기 위해 건립한 서원이다. 준도문(遵道門)이라 편액한 외삼문을 들어서면 정면하여 강당인 수교당이 자리 잡고 있으며 마당의 좌측에는 평기와를 얹은 4칸 규모의 맞배기와집인 성경재(誠敬齋)를 두었다. 성경재와 마주보는 마당 우측의 경사진 대지 위에는 사당이 배치되어 있는데, 사당의 주위에는 방형의 토석담을 둘러 별도의 공간을 이루게 하였으며 담의 정면에는 3칸 규모의 평대문인 내삼문을 세웠다.","a":"하양부호리금호서원","c":"문화유산자료","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663479.jpg"},{"q":"조선 중기의 무신인 황진(黃縉)의 본관은 장수(長水)이다. 1627년(인조 6)에 유효립(柳孝立)의 반란 모의를 고발한 공으로 아버지 황성원(黃性元)과 함께 영사공신(寧社功臣) 2등에 봉해졌다. 황진의 공신도상은 두 손을 소매 안에서 맞잡았고, 오른편으로 몸의 방향을 약간 틀어 의자에 앉은 좌상이다. 높이가 낮은 사모, 관복의 오른쪽 옆구리로 삐쳐 나온 삼각형 자락, 단령의 양쪽 옆트임을 묘사한 것은 17세기의 공신도상에서 볼 수 있는 공통점이다.","a":"황진초상","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637782.jpg"},{"q":"본 보살좌상은 방형의 얼굴, 뭉퉁한 코, 머리의 비례가 짧음, 대의의 특징 중 목 좌우측 옷깃이 역삼각형을 이룬 점, 대의 끝자락이 구불구불한 물결 모양으로 처리된 점 등은 모두 조선시대 17세기 불상 혹은 보살상에서 흔히 엿보이는 특징과 유사하다. 그러나 두 무릎부분의 깊은 가로줄선의 옷주름선 처리와 전체적으로 17세기 양식을 계승한 가운데 도식적이고 평판적인 점 등은 18세기 보살상과 흡사한 특징들이다.","a":"범어사 원효암 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636783.jpg"},{"q":"영광 ○○○ 서고마을의 서북쪽 미륵골에 있는 것으로 바위 위에 불상 머리만 조각하여 올려 놓은 특이한 형태이다. 네모나고 다소 넓은 얼굴의 이 불상은 명상에 잠긴 듯한 눈을 하고 있어 근엄하고 장중한 느낌을 준다. 민머리의 머리 위에 넓고 큰 육계가 있는 부처의 얼굴은 눈두덩이가 유난히 크며, 이마는 다소 좁은 듯하다. 알맞게 곧은 코에 단정하게 입을 다물고 있으며 특히 귀가 매우 길어 목의 중간까지 내려왔다. 불두(佛頭)의 뒷면은 평면적으로 처리하였으나 앞면의 조각 솜씨는 매우 정교하고 뛰어나다.","a":"영광설매리석조불두상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640158.jpg"},{"q":"○○○○○는 19세기 중엽 이후 서울･경기 지역에서 유행한 감로왕도의 전형적인 도상을 보여주는 작품으로, 당시의 재의식과 생활상을 충실히 묘사하였다. 상단에는 7여래가 합장을 한 채 나란히 서 있으며, 좌측에는 아미타삼존 일행이 구름을 타고 내영(來迎)하는 모습과 왕후장상, 선왕선후, 북채를 든 뇌신, 우측에는 지장삼존(지장보살･도명존자･무독귀왕)과 인로왕보살이 내영하는 모습이 묘사되어 있다.","a":"청룡사 감로도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593156.jpg"},{"q":"해안에 면해 있는 암벽의 평탄면에 새겨진 각기문(刻記文)이다. 서로 5m 가량 떨어져서 3곳에 기록이 있다. 1개소에는 가로로 ‘○○○’라 새겨져 있다. 3개소 중 가운데 것에는 ‘검찰사(檢察使) 이규원(李奎遠) 임오오월(壬午五月)’이라 새겨 두었으며, 다른 한 곳에는 풍화로 인한 마멸로 겨우 ‘서상□□김□□(徐相□□金□□)’이란 인명이 보일 뿐이다. 새겨진 글자의 크기는 10cm 내외이고 ‘○○○’라는 글자는 20cm 크기이다. 이 ○○○은 조선 고종 19년(1882) 임오년의 기록으로, ○○○의 근세 흐름을 금석문으로 입증한 귀중한 자료로 평가된다.","a":"울릉도태하리임오명각석문","c":"문화유산자료","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663314.jpg"},{"q":"○○○○는 영축산, 문수산, 남암산 등의 산등성이와 구릉으로 둘러싸여 있으며, 영축산 자락의 말단부 평지에 위치한다. ○○○○ 주변으로 통일신라시대의 사찰인 망해사지와 청송사지가 1㎞내외의 거리에 있어, 이 일대가 통일신라시대 울산 불교문화의 중심지였음을 알 수 있다. ○○○의 창건 유래는 『삼국유사』에서 그 흔적을 찾을 수 있다. 683년(신문왕 3), 온천에서 목욕하고 돌아오던 재상 충원공(忠元公)은 꿩이 매에게 쫓겨 굴정현(屈井縣) 현청(縣廳) 북쪽 우물 안으로 들어가는 것을 보았다.","a":"율리영축사지","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645895.jpg"},{"q":"인왕산 다섯 활 터 가운데 하나로 역사적 유래가 깊은 ○○○을 상징하는 각자바위로, 문헌상 숙종조의 명필인 엄한붕이 쓴 것으로 전해진다. 필획이 옹골차고 결구가 치밀한 매우 뛰어나며, 조선 중기 이후의 대자(大字) 글씨에서 느낄 수 있는 기식을 가진 수작이다.","a":"백호정","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102315331600.jpg"},{"q":"현재 도내 조성된 방형식 석곽묘는 고려말에서 조선조에 축조되었으나, 대부분 원형이 훼손되거나 이장되어 있다, 그러나 ○○○○○ 방묘 2기(昭威將軍韓公繼老 · 配淑夫人南平文氏)는 원형이 훼손되지 않고 보존 상태가 매우 양호하여, 제주도의 묘제사 연구에 매우 중요한 자료로 인정되어 문화유산으로 지정되었다.","a":"가시리설오름청주한씨방묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657996.jpg"},{"q":"종남산 기슭에 있는 ○○○는 867년에 보조국사(普照國師) 체징이 창건하였다고 전해지는 유서깊은 절이다. ○○○의 입구에 세워 속세와 불계의 경계역할을 하는 상징물인 ○○○은 조선시대에 지은 것이다. 원래 지금의 위치에서 약 3㎞ 떨어진 곳에 세웠던 것인데, 절의 영역이 작아져서 순조 14년(1814)에 조계교 부근으로 옮겼다가 1944년에 지금 있는 자리로 옮긴 것이다. 건물은 2개의 원기둥을 나란히 세우고 그 위에 지붕 옆면이 사람 인(人)자 모양을 한 간결한 맞배지붕을 올렸다.","a":"송광사일주문","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639369.jpg"},{"q":"○○○는 통일신라 진성여왕 6년(892)에 범일조사가 처음 지은 절로, 이때에는 운망사라 하였다. 조선 선조 18년(1585)에 사명대사가 지금의 자리로 다시 옮겨지으면서 ○○○라고 이름을 바꾸었다. 그 뒤 산불로 절이 모두 불탄 것을 순조 5년(1805)에 다시 지었다고 전한다. ○○○ 대웅전은 앞면 3칸·옆면 3칸의 규모이며, 옆에서 보았을 때 지붕선이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 지붕을 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 있는 다포양식이다.","a":"삼척영은사대웅보전","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638047.jpg"},{"q":"노수신 적소는 조선 중기의 유명한 신하인 노수신(1515∼1590)이 귀양살이를 하던 곳으로, 후에 건물명을 ○○○이라 하였다. 노수신은 중종 38년(1543) 과거시험에 합격하여 이황과 같이 학문을 연구하다가 정권다툼으로 관직에서 물러나고 순천, ○○ 등지에서 귀양살이를 하다가 선조 즉위 후 다시 관직에 올라 영의정에까지 오른 인물이다. 건물은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"괴산 수월정","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650014.jpg"},{"q":"○○○○○는 좌대와 비신, 지붕돌로 구성되어 있다. 1737년 김진동 등이 주도하여 문중사람들의 참여하여 2년 뒤인 1739년 기미에 세웠다. 높이 249cm의 비 전면에는 「신라왕자○○○」라 하였고, 앞면 오른쪽에 「○○○명(遺墟碑銘)」이란 제하의 119자의 내용이 쓰여 있으며, 왼쪽에 비를 세우는 일에 참여한 4명의 이름과 관직 등 26자가 각인되어 있다. 뒷면에 김진상(金鎭商)이 쓴 「○○○음기」라는 제목하에 180자의 내용과 23자의 세운 시기와 글씨를 쓴 사람의 이름이 새겨져 있다. 비각은 정면 1칸, 측면 1칸의 규모인데 팔작지붕의 건물이다.","a":"담양평장동광산김씨유허비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654356.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. 조천진에 소속되었던 ○○○○는 북제주군 조천읍 함덕리 서쪽에 있는 제주대학교 해양연구소 안에 있다. 현재 훼손이 많이 되어 아랫부분 가로 7.9m 세로 8.1m, 높이 1.6∼2.4m 정도가 남아 있다.","a":"함덕연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657831.jpg"},{"q":"조선시대에 이곳 제주도에 유배되거나 방어사로 부임하여 이 지방의 교학 발전에 공헌한 다섯 분(5현)을 기리고 있는 제단으로, 이들의 위패를 모시던 귤림서원의 옛 터에 마련되어 있다. 5현은 중종 15년(1520)에 유배된 충암 김정 선생, 중종 29년(1534)에 제주목사로 부임해 온 규암 송인수선생, 선조 34년(1601)에 안무사로 왔던 청음 김상헌선생, 광해군 6년(1614)에 유배된 동계 정온 선생, 숙종 15년(1689)에 유배된 우암 송시열 선생 등 다섯 분이다.","a":"오현단","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657609.jpg"},{"q":"묘지(墓誌)의 주인공인 정○○○○○는 울진현령 조계문(曺繼門)의 부인이자 문장공(文莊公) 매계(梅溪) 조위(曺偉)의 어머니이다. 연산군 원년(1495)에 69세로 세상을 떠나자 아들 조위가 홍귀달(洪貴達)로부터 ○○○을 받아 직접 글씨를 새긴 후 묘소 앞에 묻었다고 하며, 2001년에 묘소 보수작업 중 상석 밑에서 발견되었다. 조선시대의 묘지석(墓誌石)은 상당수 전해오고 있으나 이 묘지석처럼 돌로 만든 것은 그렇게 흔치 않다. 제작연대도 오래되었고 보존상태 또한 양호하다.","a":"정부인문화류씨묘지명지석","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641171.jpg"},{"q":"○○○는 통일신라 헌강왕 5년(879)에 도선국사가 세웠으며, 임진왜란 때 완전히 소실된 것을 광해군 때 다시 세웠다. ○○○은 ○○○를 세울 당시 대웅전 옆에 부속 건물로 지었는데 조선말 포우대사가 보수하였다. 명부전·지장전이라고 불리우는 ○○○은 앞면 3칸·옆면 1칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짠 익공 양식으로 꾸몄다. 건물 안쪽 천장은 우물 정(井)자 모양으로 천장 속을 가린 우물천장이고 지장보살을 중심으로 10명의 명부왕을 모시고 있다.","a":"진주 청곡사 업경전","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664162.jpg"},{"q":"○○○○○ 주용식이 소장하고 있는 ○○○로 교지 4매, 전령문 3매, 전령문피봉 1매, 등장문 5매, 차용문 1매, 분재기 1매 등 모두 15매이다. 교지는 4매로, 주경석(周敬奭)에게 내린 교지 3매와 주경석의 처 창녕 성씨(成氏)에게 내린 교지 1매이다. 주경석에게 내린 교지는 광서삼년(1877년)팔월의 통덕랑 교지, 광서구년(1883년)유월에 받은 통정대부 교지와 절충장군행첨지중추부사겸오위장 교지이다. 주경석의 처 창녕 성씨에게 내린 교지는 광서십년(1884)정월의 숙부인 교지이다.","a":"상주주씨 어은공파 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664802.jpg"},{"q":"종택에는 오봉 신시제(1562∼1624)의 위패를 모신 사당이 있다. 그는 문과에 급제하고 예안 현감을 지냈으며 임진왜란이 일어나자 의병을 모집하여 일본군과 맞서 싸웠다. 수령으로 제임할 때 많은 치적을 남겼고 의성에 근무할 때 ‘장대서원’을 세워 지방고을 자제의 교육에 힘썼다. 이 건물은 아주 신씨의 종가인 낙선당과 담장 하나를 사이에 두고 있는데 사당은 10여 개의 돌계단을 오르면 4각으로 두른 흙담장 중앙에 정남향을 향하고 있으며, 종택의 중심건물인 낙선당과 담장 하나를 사이에 두고 있다.","a":"오봉종택","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662789.jpg"},{"q":"○○○은 억새로 지붕을 이은 새풀집 민가 3동이다. 뒷산 중턱에 경강사라는 사찰이 들어선 후 이 민가3동 가운데 안채에 해당되는 1동이 재실 겸 요사체 기능을 하게 되면서 영강정으로 이름붙인 것이다. 이들민가 3동의 초창연대는 알 수 없으나 임진왜란(1592-1599)이후부터 낙동강 지류에 해당되는 화포천 연변에 피난 온 사람들이 억새로 지붕을 이은 초막집을 짓고 거주하기 시작했다는 증언과 유구의 건축수법 등으로 미루어 보면 이들 가옥은 최소 1900년대 이전에 초창되었을 것으로 판단된다.","a":"김해장방리갈대집","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666319.jpg"},{"q":"고려 후기 문신인 민안부 선생의 묘 근처에 세운 재실이다. 민안부가 예조판서로 있을 때 고려는 국운이 기울기 시작하여 이성계가 위화도회군을 하고 최영, 정몽주의 제거와 혁명을 일으킨 어수선한 시기였다. 그는 벼슬을 버리고 고려 유신 72현과 두문동(지금의 경기도 개풍군 광덕산)에 들어가 조선을 반대하며 항쟁하다 겨우 죽음을 면하고 경상남도 ○○군에 내려가 은둔하였다. 그곳에서 자연과 더불어 여생을 보냈으며 그의 아들들도 그의 뜻에 따라 조선시대에 벼슬을 하지 않았다. 그 뒤 후손들이 번성하여 ○○ 민씨의 시조가 되었다.","a":"산청 송계재","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664315.jpg"},{"q":"능동마을의 뒷편에 서 있는 문인석과 ○○으로, 그 앞에는 가락국의 왕릉이었다고도 하고 혹은 조선 전기 사대부의 묘였다고도 전해지는 능이 자리하고 있다. 문인석은 돌로 만든 문인상으로 능을 옹위하는 역할을 하고, ○○은 능에 제사지낼 때 쓰는 돌로 만든 상이다. 이렇듯 능 주위로 석조물을 배치하는 풍습은 중국에서 시작한 것으로 우리나라에서는 8세기 중엽 통일신라시대에 이를 받아들였다. 비록 중국의 영향을 받긴 하였으나 우리 나름의 독창적인 전개과정을 이끌어냈기 때문에 이러한 석조물을 통해 조각의 변천과정을 살펴 볼 수 있어 그 가치를 지닌다.","a":"김해 능동석인상 및 상석","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641500.jpg"},{"q":"\"부도란 승려의 무덤을 상징하여 시신을 화장한 후 그 유골이나 사리를 모셔두는 곳이다. ○○○로 들어가는 입구 왼쪽에 자리잡은 이 부도밭에는 7기의 부도가 나란히 자리하고 있다. 모두 비슷한 형식을 하고 있어서, 바닥돌 위로 3단을 이루는 기단(基壇)을 두고 탑신(塔身)을 올린 후, 머리장식을 얹었는데, 바닥돌을 제외한 각 부분이 8각의 평면을 기본으로 삼고 있다. 앞에서 보아 맨 왼쪽에서부터 살펴보면 다음과 같다. ①청심당 쌍인탑 - 탑신의 몸돌에 승려의 이름이 새겨 놓았으며, ○○○동종(보물)에 ‘쌍인’의 이름이 보이고 있어 17세기에 세운 것임을 알 수 있다.","a":"용흥사부도군","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640009.jpg"},{"q":"◦ 이곳 오천은 조선시대 충청도수군절도사영이 설치된 곳이었으나 1895년 폐영되었다가 1901년에 오천군이 신설된 곳임. ◦ 오천군 신설과 동시에 이곳 유림들은 고을에 향교를 갖추려 하였으나 여의치 못하여 간단한 제향을 할 정도의 기물과 시설을 갖춘 채 향교의 터전을 잡았음. ◦ 그 후 1905년에 이르러 토지 기증․헌납 등을 통한 유림들의 노력과, 군수의 조력으로 ○○○ 건물을 완성하여 향교의 모습을 갖추고 이 고을 유교문풍을 진작하면서 오늘까지 그 맥을 이어오고 있음.","a":"오천향교대성전","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661117.jpg"},{"q":"자는 사정(士貞), 호는 의암(衣岩)인 ○○○ 선생의 묘이다. 그는 어려서부터 힘이 세고 재주에 능하였다고 전해진다. 『삼척군지』에 보면 임진왜란 때에 충무공 이순신의 휘하에서 의병장으로 활약을 하여 많은 공을 세웠다고 한다. 그래서 조정에서는 선무원종공신 2등의 벼슬을 내렸고 병조판서에까지 올랐다고 한다.『밀성박씨세보』를 통해 선조 31년(1598)에 고향에 내려간 후 선조 36년(1603)에 세상을 떠났음을 알 수 있다. 그러나 임진왜란 당시 함께 활약을 한 오극성의 문집『문월선생문집』에 보면 경상도 지역에서 활동을 한 무신인 것으로 여겨진다.","a":"삼척박걸남묘역","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660598.jpg"},{"q":"○○○○ 명부전에 모셔져 있는 나무로 만든 지장보살상이다. 이 지장보살상은 삼각산 태고사에 있었는데 한국전쟁 때 태고사에 불이 나 ○○○○로 옮겨졌다고 전한다. 고개를 약간 숙이고 앉아 있는 이 지장○○○○은 신체에 비해 얼굴이 다소 넓적하고 큰 느낌이 있으나 전체적으로 단정하면서도 균형이 잘 잡혀 있어 안정감을 준다. 이마가 넓고 두 귀가 크게 표현된 얼굴에 머리는 민머리 형태를 하고 있다. 몸체가 그다지 큰 편은 아니지만 양감이 잘 표현되었다. 두 어깨를 모두 감싼 옷은 자연스러운 옷주름을 만들면서 흘러 내려 온몸을 감싸고 있다.","a":"본원정사 목 보살좌상(지장보살)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636319.jpg"},{"q":"바닷가 평지에 자리잡고 있는 정자로 조선 선조 23년(1590)에 조천관 건물을 새로 지은 후 쌍벽정이라 하였다가 선조 32년(1599)에 건물을 보수하고 이름을 ○○○으로 고쳤다. ‘연북’이라는 정자의 이름은 제주도로 유배 온 사람들이 한양의 기쁜 소식을 기다리면서 북쪽에 계시는 임금을 사모한다는 충정의 뜻을 담고 있다. 앞면 3칸·옆면 2칸의 지붕은 옆면이 여덟 팔(八)자 모양을 한 팔작지붕이다. 사람의 키보다 훨씬 높게 축대를 쌓고 다진 기단 위에 세웠다.","a":"연북정","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643255.jpg"},{"q":"전북특별자치도 김제시 황산동 ○○○ 산신각 옆에 새겨져 있는 마애불로, 1.7m 높이의 작은 바위에 선으로 불상을 새겼다. 민머리 위에는 상투 모양의 큼직한 머리묶음이 솟아 있는데, 머리는 마치 모자를 두른 것처럼 두툼하게 묘사되어 있다. 얼굴은 둥글고 원만한 편이며, 눈은 길고 가늘게 표현되어 있다. 눈썹에서 이어진 코는 큼직한 편으로 입 주위를 움푹 들어가게 묘사하여 코부분이 더욱 두드러져 보인다. 연꽃 모양의 대좌(臺座)에 앉아 있는 불상은 무릎 폭이 넓어 안정감 있어 보인다. 오른쪽 무릎은 약간 파손되었는데 원래 바위의 모양 때문인 것으로 보인다.","a":"문수사마애여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639656.jpg"},{"q":"강원특별자치도 강릉시 구정면 학산리 ○○○ 절터에 있는 ○○○○이다. 이 곳에 전해지는 3구의 석불 가운데 완전한 2구는 작은 암자에서 모시고 있고, 머리 부분이 없어진 1구는 우물에 있다. 석불 3구는 모두 한손이 다른 손의 검지를 감싸고 있는 손모양을 하고 있는데, 이는 비로자나불이 일반적으로 취하는 모습으로 아마도 함께 모시기 위해 만든 비로자나삼존불로 생각된다. 얼굴은 둥글고 긴 타원형이며, 어깨는 움츠린 듯하다. 옷의 표현이 두꺼워 몸의 굴곡이 드러나지 않으며, 가슴 부근에 있는 손의 모습은 다소 경직되어 보인다.","a":"강릉굴산사지석불좌상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660398.jpg"},{"q":"성주 이씨들의 선조 가운데 나라에 공헌하고 사회에 본보기가 될만한 13분의 영정을 모시고 제사지내는 건물이다. 지은 시기는 확실치 않으나 선조 14년(1581), 당시 성주 이씨의 후손인 이현배가 성주목사로 부임해오면서 이곳을 고쳐 지었다. 원래 월항면 인촌리 이장경의 묘 앞에 있었는데 그의 묘를 이장하면서 지금 있는 자리로 옮겼다. 그 뒤 숙종 6년(1680) 임금이 ‘안산서원’이란 이름을 내려 주었고, 나라에 공를 세운 조상 22분의 영정을 모시게 되었다. 그러나 임진왜란 등으로 소실되어 현재는 13분을 모시고 있다.","a":"안산영당","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662851.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 전라남도 고흥군 고흥읍 옥하리에 있는 이 읍성은 뒷쪽에 주월산을 끼고 쌓은 성이다. 평지에 읍성을 만드는 것은 조선 전기부터 나타나기 시작한다. 이 성은 왜구의 침입을 막기 위해 조선 태조 4년(1395) 광양현에 진을 설치한 것으로 보아 이 시기에 만든 것이라 여겨진다. 고종 8년(1871)에 크게 고쳐 쌓았던 것으로 보이는데, 원래는 여장(성 위에 쌓은 낮은 담), 곡성(성문을 보호하기 위해 성문 밖으로 쌓은 작은 성)이 있었다.","a":"흥양현읍성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654067.jpg"},{"q":"조선 제27대 왕이자 마지막 왕인 순종의 황후 순명효황후의 능이었던 옛 ○○○ 터에 남아 있는 왕릉 석조각들이다. 순명효황후는 민태호의 딸로 세자빈에 책봉되었으나 순종이 임금이 되기 전 1904년에 사망하여 ○○○에 묘소를 마련하였다가 순종이 세상을 떠난 1926년에 지금의 유릉에 옮겨와 함께 모셔졌다. 그 뒤 순종의 계비인 순정효황후가 사망하자 이 또한 함께 모셔져 있다. 순명효황후의 능을 마련하였던 ○○○ 터에는 능 주위에 세웠던 20여 기의 석조물이 남아 있다.","a":"순명비 유강원 석물","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590171.jpg"},{"q":"군서면 서구림리와 학산면 용산리의 경계인 ○○○○ 옆에 자리하고 있는 돌장승이다. 가까운 곳의 죽정리 국장승에 새겨 놓은 ‘석표사좌(石標四坐)’ 중의 하나로, 근처에 있는 도갑사(道岬寺)의 경계표시를 하기 위해 세웠던 것으로 보인다. 크기는 높이 121㎝, 너비 50∼70㎝, 두께 13∼30㎝ 이며, 보통의 장승이 사람이나 신장의 모습을 새기는 것과는 다르게, 자연석을 그대로 이용하여 한쪽 면에 3글자를 큼지막하게 새긴 비석의 형상을 하고 있다.","a":"영암메밀방죽옆장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658377.jpg"},{"q":"청양군 정산면 계봉산에 있는 이 산성은 두릉윤성 또는 계봉산성이라고 한다. 『동국여지승람』에 계봉산성은 돌로 쌓은 성으로, 성의 둘레가 1,200척이라고 기록되어 있다. 백곡리 백실부락 뒷쪽에 높게 솟은 2개의 산봉우리 정상에, 약 540m에 이르는 성벽이 자연 지형을 따라 둘러쌓여 있다. 이 산성은 백제의 수도 사비성 북방에 있어, 국토 방위에 중요한 역할을 한 산성으로, 백제 멸망 후 그 유민들의 부흥운동 근거지가 되기도 하였다.","a":"두릉산성(두릉이성)","c":"문화유산자료","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661152.jpg"},{"q":"삼세불이란 과거불 · 현재불 · 미래불을 뜻하기도 하고, 현재의 공간과 동방, 서방의 세 세계를 뜻하기도 한다. 조선 시대 절에서는 흔히 가운데 석가모니불을 중심으로 그 왼쪽에 약사불이, 그 오른쪽에 아미타불이 배치되는 형식이 일반적이었다. ○○○○○의 나무 삼세불도 이를 따랐는데, 기록에 따르면 삼세불은 1790년에 한 달 보름에 걸쳐 만들어 모셨다고 한다. 가운데의 석가불은 오른손을 가부좌한 무릎 아래로 내려 악마를 항복시킨다는 뜻의 항마촉지인(降魔觸地印)을 맺었고, 그 오른쪽의 아미타불은 엄지와 중지를 맞대고 아미타 수인을 맺었다.","a":"화성 용주사 대웅보전 목조삼세불좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637787.jpg"},{"q":"경상북도 경주시 배동의 거대한 자연 바위벽에 새긴 앉아 있는 모습의 ○○○○불로 높이는 6m이다. 몸을 약간 뒤로 젖히고 있으며, 반쯤 뜬 눈은 속세의 중생을 굽어 살펴보는 것 같다. 머리에서 어깨까지는 입체감있게 깊게 새겨서 돋보이게 한 반면 몸체는 아주 얕게 새겼다. 전체적인 양식으로 보아 통일신라 후기에 유행하던 양식의 마애불로 추정된다.","a":"삼릉계곡마애석가여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640589.jpg"},{"q":"조선시대 의병장인 ○○ 선생을 기리기 위하여 세운 비로, 본래 ○○시 상당구 서문동에 있었으나, 일제강점기 현재 위치인 중앙공원으로 이전하였다. ○○은 명종 22년(1567) 과거에 급제한 후 여러 벼슬을 거치면서 나라의 정치를 바로잡는데 힘을 다하였다. 임진왜란이 일어나자 옥천에서 의병을 일으켜, 승병장 영규와 힘을 합쳐 ○○성을 탈환하기도 하였다. 왜적이 금산을 중심으로 충청도 일대를 거머쥐려 하자 승병장 영규와 700명의 의병을 이끌고 금산에서 적과 싸웠는데, 적에게 막대한 타격을 주었지만 인원이 너무 적어 결국 모두 전사하고 말았다.","a":"청주 조헌 전장기적비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638603.jpg"},{"q":"○○○ 동네밖 길가에 마련된 흙으로 쌓은 작은 언덕으로, 조광익(1537∼1578)의 효행과 아우 조호익(1545∼1609)과의 우애를 기리어 후손들에게 귀감이 되도록 하기 위해 조성된 것이다. 조광익은 조선 중기의 문신이요 학자로, 호는 취원당이다. 이황의 문인이며 성리학을 깊이 연구하였으며, 명종 13년(1558) 생원·진사 두 시험에 합격하여 벼슬길에 올라 의금부도사에 이르렀다. 선조 11년(1578) 강동으로 유배된 아우 조호익을 만나려 평안도도사의 직책을 얻어 갔다가 42세 나이로 생을 마치었다.","a":"밀양오방리강동구","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655614.jpg"},{"q":"객사는 출장간 관리, 외국 사신 등이 숙소로 쓰거나 임금께 예를 올리던 곳이다. ○○○○는 조선 경종 2년(1722) 가리포진에서 첨사라는 벼슬을 지내던 이형이 지었고, 고종 6년(1869) 고쳐 지었다. 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 완도에서 가장 오래된 건물로 ‘호남 제일반(湖南 第一潘)’이라고 쓴 현판은 조선 철종 5년(1854) 홍선이 쓴 것이다.","a":"완도객사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662046.jpg"},{"q":"○○○○○는 동체 측면에 點刻되어 있는 銘文에 의해 조선 정조 4년(1780)에 제작된 것임을 밝혀졌고, 조선후기 ○○ 양식을 나름대로 잘 간직한 채 제법 규모가 큰 ○○이다.","a":"창녕 청련사 반자","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666350.jpg"},{"q":"조선 전기 문신이자 악성(樂聖)인 난계 박연(1378∼1458) 선생의 위패를 모신 사당이다. 세종을 도와 음악을 정비하는데 많은 공을 세운 박연은 악률에 정통하여 세종 7년(1425) 아악의 율조와 악기의 그림, 악보를 같이 실은 『악서』를 편찬하였고, 1427에는 편경 12매를 만들어 자작한 12율관을 따라 직접 연주하기도 하였다. 그는 피리의 일종인 적(笛)과 거문고, 비파의 연주에 뛰어났으며 조정의 조회 때 아악을 연주하도록 하는 등 국악의 기틀을 마련하였다.","a":"영동 난계사","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649180.jpg"},{"q":"조신의 충절을 기리기 위해 세운 서원이다. 조신은 고려 공민왕(재위 1351∼1374) 때 회양고을 군수를 역임하였으며, 고려말 신돈이 정권을 장악하자 정치에서 물러나 은거하였다. 이방원의 어릴적 스승으로도 알려져 있으며 박팽년·유성원 등의 학자를 길러냈다. ○○○○은 조선 철종(재위 1849∼1863) 때 지역 유림들이 지었으나, 고종 5년(1868) 흥선대원군의 서원철폐령으로 철거되었다가 1930년에 복원하였다. 건물 배치는 ㅁ자형으로 되어 있는데, 바깥채는 전학당이라 하고 안채는 화수루라고 부른다.","a":"동곡서원","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661037.jpg"},{"q":"○○군 하일면 ○○○ 927번지내 ○○○○○는 약 330년전 하일면 학동마을에 정착하면서 축조한 건축물로 토담과 납작한 돌로 축담을 층층이 쌓은 후, 그 위에 건축물을 축조한 형태는 다른 지역에서는 볼 수 없는 특이하고 독특한 양식으로 안채와 사랑채, 고방채, 토담으로 잘 쌓은 창고, 집안의 텃밭, 마을의 특색인 돌축대, 축대위로 토담과 넓은 돌덮개 지붕으로 된 닭장, 안채뒤 장독대는 계단식 돈대로 그 면적이 상당히 넓고 고풍스러움을 풍긴다","a":"고성 학림리 최씨종가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659073.jpg"},{"q":"조선 후기 애국지사인 최익현(1833∼1906)선생의 위패를 모신 사당이다. 최익현은 이학로의 제자로 문학과 도학에 조예가 깊었으며 철종 6년(1855)에 문과에 급제하고 벼슬이 현감에까지 올랐다. 그러나 나라를 걱정하며 대원군의 정책을 비판하는 상소문을 여러 차례 올리고 흑산도에 유배되기도 하였다. 또한 1905년 일제에 의해 강제로 을사조약이 체결되자 을사 5적을 처단할 것을 주장하였고 같은 해 일본의 죄상을 16개 항목에 적어 항쟁하며 전라북도 태인에서 의병을 모집, 일본군과 싸웠다.","a":"모덕사","c":"문화유산자료","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661143.jpg"},{"q":"충청북도 ○○군 불정면 ○○○에 있는 불상으로 낮은 연꽃무늬 대좌 위에 앉아 있는 모습이다. 민머리 위에는 큼직한 상투 모양의 머리묶음이 있으며, 목에는 3줄의 뚜렷한 삼도(三道)가 있다. 체구는 단아하며 굴곡이 없는 신체에는 양 어깨를 덮은 옷자락과 몇 가닥의 간략한 옷주름이 선으로 표현되어 있다. 오른손은 무릎 위에 올리고 왼손은 가슴 앞에서 독특한 모양을 나타내고 있다. 도식적인 연꽃잎의 형태에서 기술의 한계가 보이지만 앞 시대의 특징이 엿보이는 고려시대의 뛰어난 작품으로 평가된다.","a":"괴산 삼방리 마애여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638591.jpg"},{"q":"鳩摩羅什 著의 ○○○○○ 제1권으로 折帖裝 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 인간된 것으로 보임. 折帖裝은 권자본에 이어 고려 중후기에 많이 인행된 것으로 서지학적으로 중요한 자료로 취급되고 있는데 본 불경의 경우 인쇄상태가 아주 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"묘법연화경 권제일","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642608.jpg"},{"q":"조선 숙종 30년(1704)에 만들어진 높이 83㎝의 전형적인 조선 후기 범종이다. 종을 매다는 용뉴가 종의 몸체에 비하여 가냘프며, 2마리의 용이 다소 형식화 된 느낌을 준다. 종 윗쪽의 4곳에 일반적인 종과 같이 정사각형의 유곽이 있고, 유곽 안에는 돌출된 9개의 유두가 있다. 유곽 사이의 빈 공간에는 윗부분에 범자를 돌려가며 4곳에 양각하고, 아래로 머리광배을 갖춘 보살상을 그렸다. 종의 입 가장자리에는 화려한 덩굴무늬 띠가 있으며, 아랫부분에 글씨가 양각되어 있다.","a":"양양명주사동종","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638014.jpg"},{"q":"석재준(1866∼1945)의 공을 기리기 위해 1923년 제자들이 지은 것으로, 호를 따라 ‘○○○’이라 부른다. 석재준은 학당을 열어 문하생들이 오랑캐의 풍속에 물들지 않게 하고 선비정신을 일깨워준 인물이다. 건물 규모는 앞면 3칸·옆면 1칸 반이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"소계정","c":"문화유산자료","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659492.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○○○는 군사적 목적으로 설치한 것으로, 고성읍에서 약 30㎞ 지점에 있는 해발 392m의 산 정상에 자리잡고 있다. ○○○의 둘레는 73m 정도이나 현재까지 남아있는 석축은 36m이고, 높이는 1.6∼2.2m이다. 이곳 ○○○는 조선시대 전기에 설치된 것으로 우산 봉화대에서 신호를 받아 사천의 각산 봉화대와 사량진 봉화대 및 소을비포 진영에 보고하는 망대로 활용되었다.","a":"고성좌이산봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655748.jpg"},{"q":"용성관은 조선시대 관원들의 숙소로 사용된 건물로, 그 규모가 웅대하여 남원 광한루, 관왕묘와 함께 고대건물의 3걸로 불리웠다. 한때는 조선 태조의 전패(殿牌:전(殿)자를 새긴 나무패로 왕의 상징임)를 모시어 ‘휼문관’이라고도 하였으며, 이 후에 불에 타 다시 짓는 등 몇 차례의 보수 과정을 거쳤다. 한국전쟁 때 또다시 불에 타 지금은 건물의 기단 70여m와 이 계단석물 1기만 남아있다. 잘 다듬은 계단은 아래의 난간 양쪽에 반원을 그리듯 둥글게 처리된 석물이 놓여있는데, 표면에 도깨비상을 조각해 놓아 독특한 모습이다.","a":"용성관석물","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661718.jpg"},{"q":"심산유곡을 배경으로 산신과 호랑이, 동자, 공양자를 배치한 ○○○로서 현재 ○○○ 산신각에 봉안되어 있다. 향 우측 하단에 마련된 화기란 중의‘全羅南道 羅漢山 砂坮庵 …乙酉五月 一日󰡑이라는 내용으로 미루어 보아 조성․봉안처는 전라남도 나한산 사태암이고, 조성시기는 1885년으로 추정된다. 향 좌측 상부에는 잎이 무성한 큼직한 소나무가 그려져 있으며, 구름과 붉은 해가 소나무를 감싸고 있는데, 굵은 줄기에 태점을 찍고 옅은 수묵을 사용하여 줄기를 사실적으로 묘사함으로써 해묵은 노송(老松)의 질감을 잘 나타내준다.","a":"기원사 산신도","c":"문화유산자료","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659335.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 정종 1년(1399)에 세워진 ○○○○는 임진왜란(1592) 때 불에 타 없어졌다. 광해군 6년(1614)에 남천리로 옮겨 지었으나 불이나서 정조 15년(1791)에 현재의 자리로 옮겼다. 그 뒤 여러 차례의 수리를 거쳐서 오늘에 이르고 있다. 현재 남아있는 건물은 대성전·명륜당·동재·서재·교직사 등이 있다. 대성전은 공자를 비롯하여 여러 성현들의 위패를 모시고 제사지내는 곳이고, 명륜당은 학생들이 공부하던 강당이다.","a":"단양 영춘향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638553.jpg"},{"q":"이 석등은 흥륜사지(興輪寺址)에서 가져왔다고 전해지고 있다. 일반적으로 석등은 불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 3단의 받침을 두고 위로는 지붕들과 머리장식을 올리는데, 이 석등은 화사석과 지붕돌을 두지 않은 독특한 모습이다. 꼭대기에는 꽃봉오리 모양을 한 머리장식이 남아있으나, 옆으로 살짝 비뚤어졌다. 대석은 네모난 형태로 된 지대석이며, 사면에는 십이지신상(十二支神像)의 좌상이 조각되어 있다. 지대석 상부에는 간주가 있고 또 그 위에 연꽃이 위로 솟은 듯이 표현된 대석이 있다. 석등 밑에 십이지신상이 새겨진 예는 매우 드물어 주목된다.","a":"경주교동석등","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662364.jpg"},{"q":"○○○○○에 보존되어 있는 그림으로, 석가가 영취산에서 설법하는 모습을 그린 ○○○○○이다. 이 ○○○○○는 면 바탕에 채색하여 그려진 것으로, 화면은 중앙에 석가여래상이 연꽃무늬 대좌 위에 앉아 있고, 그 앞쪽 좌우측에는 총 4명의 보살상이 지물을 쥔 채 시립하고 있으며, 뒤쪽 좌우측에는 아난·가섭 등 총 4명의 제자상이 배치되어 있다. 그리고 화면 좌우측 가장자리에는 사천왕상이 2구씩 각각 위치하고 있다. 본존의 육신은 황색 바탕에 가는 붉은색 선으로 육신선을 표현하였다. 머리 부분은 군청을 바르고 윤곽선은 먹선으로 처리하였다.","a":"마하사 응진전 영산회상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659361.jpg"},{"q":"아미타불을 본존으로 한 아미타불후불탱화로서 극락구품도를 묘사하였다. 화면 가운데 본존불인 아미타불을 크게 그리고 그 주위로 많은 권속들이 둘러 싸고 있다. 아미타불은 연꽃대좌에 양어깨를 모두 감싼 옷을 입고 있으며, 오른손은 가슴 위로 올리고 왼손은 무릎위에 올려놓은 모습이다. 몸 주위로는 머리광배와 몸광배가 표현되었다. 본존의 양 무릎 아래쪽으로 정병을 들고 있는 관음보살과 연꽃가지를 들고 있는 세지보살이 그려져 있고, 본존의 양옆과 화면 위쪽에는 여러 보살과 승려, 팔부중의 모습이 있다.","a":"단양 구인사 아미타회상도","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638753.jpg"},{"q":"조선 태종의 장남이며 세종의 맏형인 ○○○○의 묘와 사당이다. 사당은 숙종 1년(1675) 임금의 명에 의해 세운 것으로, 원래 숭례문 밖에 있던 것을 1912년 지금의 자리로 옮겨 놓은 것이다. 지덕이란 ‘인격이 덕의 극치에 이르렀다’는 뜻으로 세조가 친히 지어준 이름이라고 한다. 사당 안에는 ○○○○과 부인 광산 김씨의 위패가 모셔져 있고, ○○○○의 친필인 숭례문 현판의 탁본과 정조가 지은 지덕사기, 허목이 지은 지덕사기 등이 있다. ○○○○의 묘소는 사당 뒤편에 자리하고 있다.","a":"양녕대군 이제 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636077.jpg"},{"q":"이 영정은 경상도관찰사를 역임한 바 있는 정헌대부행예조판서 ○○○의 ○○화로 화면은 황토색 돗자리를 경계로 상하 2단으로 구분된다. 인물은 정면향에 가까운 전신교의좌상으로 호피를 걸친 의자에 앉아 있으며, 얼굴은 좌안7분면이다. 양손은 腹前에 모아 소맷자락 안으로 넣었고 두 발은 족좌대 위에 얹은 모습이다. 인물의 자세는 양발을 족좌대 위에 정면을 향해 밖으로 약간 벌린 채 얹고 있어 측면관의 족좌대 시점과 대조를 이룬다. 안면부는 담황색을 바르고 윤곽선은 옅은 주색으로 그었다. 상검선은 농묵, 하검선은 담묵으로 그었으며, 눈꼬리 선은 살짝 위로 올려 마무리 하였다.","a":"양산 통도사 신석우 초상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643046.jpg"},{"q":"병풍처럼 생긴 ＇ㄷ＇자형 황색 벽을 배경으로 중앙 의자에 앉은 현왕을 중심으로 성왕, 판관, 녹사, 동자, 동녀 등 현왕의 권속들이 에워싼 형식이다. 그림의 주제인 현왕은 머리위에 경책을 얹은 관을 쓰고 의자에 앉아 있다. 오른손은 가슴에 대고 왼손으로 책장을 넘기며 뭔가를 가리키고 있으며, 머리에는 녹색의 두광이 표현되었다. 좌 ·우측에서 성왕이 협시하고 있으며 아래편에는 경권과 경책을 가지고 있는 판관, 기록을 하고 있는 녹사, 사자, 동자, 동녀가 표현되었다.","a":"강화 청련사 현왕도","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637125.jpg"},{"q":"갑사 대웅전의 오른쪽에 자리하고 있는 탑으로, 원래는 갑사에 딸린 암자인 ○○○에 있던 것을 대적전 뒷면에 옮겨 세웠다가 지금의 자리로 옮긴 것이다. 탑은 옆면에 안상(眼象)을 새겨 놓은 바닥돌 위로 기단(基壇)의 일부분이 놓여 있고, 그 위로 3층의 탑신(塔身)이 쌓여 있다. 기단은 맨 윗돌을 제외하고는 모두 없어졌고, 탑신은 몸돌의 모서리마다 기둥 모양을 얕게 새겼다. 지붕돌은 네 귀퉁이가 살짝 치켜올라 갔으며, 밑면에 3단씩의 받침을 두었다. 꼭대기에는 본래의 머리장식이 없어진 채, 돌의 질이 다른 연꽃봉오리 모양의 새로운 머리장식이 놓여 있다.","a":"갑사중사자암지삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660961.jpg"},{"q":"이 불상은 신체에 비해 머리가 작은 편이고, 어깨는 좁고 아래로 처져 다소 왜소하다. 수인은 중품하생을 결하였는데 왼손은 손바닥을 위로하고 오른손은 손등을 위로 하여 중지와 엄지를 맞대고 있다. 별조된 손은 가늘고 길게 조각되었는데 엄지손가락은 다른 손가락에 비해 짧고 두툼하여 조각의 미숙함이 엿보인다. 나발이 표현된 머리는 육계와의 구분이 불분명하고 그 경계에는 반달형의 중간계주를 표현하고 정수리에는 원통형의 계주를 두는 조선후기 불상의 일반적인 형식을 따랐다.","a":"함양법인사목조아미타여래좌상 복장물일괄","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642665.jpg"},{"q":"충청북도 ○○시 앙성면 모점리 오갑사 절터에서 발견된 불상으로, 얼굴의 일부와 머리가 떨어져 나갔을 뿐 거의 완전하게 남아 있다. 부드러운 얼굴은 인간적인 모습을 나타내지만 짧은 목, 상체에 비해 큰 하체, 두꺼운 옷속에 감추어진 신체 등 다소 불균형한 모습을 보여준다. 이러한 점은 통일신라의 사실주의 조각과는 거리가 있지만 옛 양식을 수용한 면이 엿보인다. 이 절터에서 금나라 연호인 명창(明昌)과 오갑사(烏岬寺)가 쓰여진 기와가 출토되어 이 불상이 고려 초기에 만들어진 것임을 알 수 있다.","a":"충주 오갑사지 석조여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638615.jpg"},{"q":"경상북도 구미시 장천면 오노리의 길가에 있는 ○○○○○으로, 크기는 높이 220㎝, 어깨 폭 95㎝이다. 몸에 비해 머리가 큰 편이고, 몸에 걸친 옷의 주름 표현이 형식화되었다. 불신 뒤에 몸 전체에서 나오는 빛을 형상화한 광배(光背)는 머리광배만을 나타내었고 몸광배는 생략하였다. 고려 중기에 만들어진 것으로 추정된다.","a":"미륵당석조미륵입상","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663155.jpg"},{"q":"○○○○은 長淵盧氏 반곡파종중 소유로 상량문이나 중건기 등의 구체적인 문헌기록이 없어 창건 시기는 명확하지 않음. 안채와 盧希簡(호 盤谷)이 45세 때인 1852년(철종 4)에 창건하였음. 안채는 정면4간 측면1간반 규모의 전퇴집으로 실은 가운데 대청을 중심으로 좌, 우에 각각 방을 배치하고 붙여 부엌을 배치한 형식임.방의 배면쪽으로는 벽장을 두었고, 마루의 배면에는 쪽마루를 두었으며, 부엌의 배면에는 천방을 두었고, 우측으로는 기둥의 바깥쪽으로 덧대어 공간을 확장함.","a":"창녕 반곡고택","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666301.jpg"},{"q":"제주도의 고인돌은 한반도와는 달리 청동기시대가 아닌 탐라시대에 만들어진 거석문화유산으로 북방식․남방식․개석식(무지석식)으로 구분된다. 이 ○○○는 남방식고인돌 형식을 취하고 있으며, 장축 방향은 북서쪽이다. 상석 아래 지석은 작은 괴석이나 할석으로 6매가 상석 주변을 돌아가면서 고여 있고, 남동쪽은 이중으로 고여 있어, 매장시설은 지하에 두었던 것으로 추정된다. 뚜껑돌의 장축 242cm, 단축 185cm, 두께 60cm이며, 축조 시기는 탐라국시대 로 추정된다.","a":"하모리지석묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657733.jpg"},{"q":"의성 김씨 개암공파의 종가이다. 해저마을은 영남의 대표적인 동성촌으로 의성 김씨 가문에서 정조(재위 1776~1800)대에 많은 문과 급제자들을 배출하였고, 이 시기 영남 사람들의 정치·사회적 활동에 주도적으로 참여하면서 영남의 대표적인 명문으로 자리잡았다. 1·2차 유림단 사건으로 불리는 항일 독립운동에 김창우가 주도적으로 활약하여 건국포장을 받았고, 이러한 독립운동이 주로 이 종가를 중심으로 논의되고 있었다는 점에서 뜻깊은 의의를 찾을 수 있다.","a":"개암종택","c":"시도기념물","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654643.jpg"},{"q":"경상남도 ○○시 일운면 ○○○리 선창마을 뒤편에 있는 산성으로, 돌을 쌓아 성벽을 마련하였다. 성의 동쪽은 대부분 잘 보존되어 있지만 그 외의 부분은 논밭의 축대나 가옥의 담장으로 사용되고 있다. 동서남북 사방에 성문을 두고 그 사이사이에 성루(城樓:망을 보기 위하여 성문이나 성벽 위에 높이 세운 건물)를 두었던 것으로 추측한다. 현재 성 안의 바닷가에는 마을이 들어서 있고 그 외는 논밭이며, 성 밖 역시 논밭과 임야로 되어 있다.","a":"거제 지세포진성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656572.jpg"},{"q":"1558년 돈암 정지영이 현 위치보다 조금 상류인 덕추폭포 부근에 초가로 건립하였으나 임란 때 소실되었고 1770년에 후손들이 중수하였으나 풍수해로 훼철되었다. 1845년 7세손 정복운 등이 현재의 위치에 재건하였으며 1948년에 중수가 있었다. 심원정은 용추계곡 입구의 매표소 바로 우측을 흐르는 지우천 계곡의 제 1담소인 청심담의 거북바위위에 건립되었으며 심진동 초입에 세운 정자이다. 옛 안의에는 삼가승경(三佳勝景)인 심진동 심원정, 원학동 수승대, 화림동 농월정을 삼가승경(三佳勝景)으로 불렀다.","a":"함양심원정","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665621.jpg"},{"q":"조선 중기의 무신 ○○○ 장군의 업적을 기리는 ○○○로, ○○○는 왕이나 고관 등의 평생업적을 기리기 위해 무덤 근처 길가에 세운 비(碑)를 말한다. ○○○의 호는 은암(隱庵)이며, 선조 16년(1583)에 무과에 급제한 후 임진왜란 때 의병을 일으켜 큰 공을 세웠다. 그 후 밀양부사와 경상좌도 수군절도사를 맡았으며 정유재란 때에는 왜적 격퇴에 공을 세워 가선대부에 올랐다. 인조 2년(1624) 이괄의 난이 일어났을 때에는 반란군을 크게 무찔러 이겨 서울을 수복한 공으로 진무공신 2등에 계림부원군에 봉해진 뒤 형조판서에 이르렀다.","a":"충주 이수일 신도비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638740.jpg"},{"q":"목이 길고 무게중심이 아래에 있는 전형적인 19세기 백자 병이다. 구연부(口緣部)의 끝이 작고 둥글게 마무리되어있고 목이 곧고 일정하며 몸체 아랫부분이 넓게 퍼져 풍만한 양감과 안정감을 보여주고 있다. 푸른빛을 머금은 유약(釉藥)과 태토(胎土)가 상품갑번(上品甲燔)에 속한다고 판단된다. 이 ○○○○는 분원기(分院期)의 자기로서는 드물게 세필(細筆)로써 성새(城塞)와 산수(山水)를 표현하고 있는데 강상(江上)의 전경(全景)을 다양한 소재를 가지고 표현한 점이 특징적이다. 표면에는 깔끔한 백유(白釉)가 전면 시유(施釉)되어 있으며 청화(靑畵)의 발색(發色)도 선명하다.","a":"청화백자성새산수문병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590215.png"},{"q":"비슬산 중턱의 옛 절터에 남아 있는 탑이다. 높은 벼랑 끝에 서 있는 이 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로, 절내의 여러 석재들과 더불어 쓰러져 있던 것을, 1988년에 겨우 복원한 것이다. 일반적인 탑과 달리 절벽의 높은 바위를 바닥돌 삼아 그 위로 기단과 탑신을 올려놓았다. 기단과 탑신의 몸돌에는 모서리마다 기둥모양의 조각을 둔 것 외에는 거의 꾸밈을 하지 않아 소박하다. 만들어진 시기는 절의 창건과 때를 같이하는 9세기 통일신라시대로 추측된다.","a":"대견사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636921.jpg"},{"q":"『동국여지승람』과 『탐라지』 등의 문헌에 나한을 모셨던 절로 기록되어 있는 절터이다. 나한은 아라한의 준말로 인간의 소원을 빨리 성취시켜 주는 복전(福田)이라 하여 일찍부터 신앙의 대상이 되어 왔다. 우리나라에서 규모가 큰 절에는 대부분 영산전을 두어 석가의 10대 제자를 비롯하여 16나한, 500나한 등을 봉안하고 있으며 나한전이나 응진전을 따로 둔 절도 있다. 1990년대의 발굴조사에서 건물지, 부도, 배수시설과 기와조각, 분청사기조각, 백자파편들이 발견되었으며, 1998년부터는 복원 작업이 이루어지고 있다.","a":"존자암지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657885.jpg"},{"q":"경기도 용인시 원삼면 문촌리 ○○○ 정상 가까운 암벽면에 조각한 고려 전기의 마애불이다. 이곳에서 약 50m 떨어진 곳에는 암자터로 추정되는 곳이 있다. 암벽은 두 개로, 각각의 바위에는 연화대좌 위에 서 있는 ○○○ 두 구를 대칭되는 모습으로 새겼다. 현재로서는 중앙에 본존불 없이 ○○○만을 조성하였기 때문에 어떤 식으로든 중앙에 원래 주존이 있었는지 혹은 본존불 조성에까지 이르지 못했던 것인지에 대해서는 알 수 없다. 좌측 ○○○은 우측 상에 비해 더 얕은 부조이다. 두 상은 우측상이 민머리임에 비해 왼쪽 상이 보관을 쓴 것으로 보인다는 점에서 차이가 있다.","a":"문수산마애보살상","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637572.jpg"},{"q":"구)○○○○○는 1909년 7월 공포한 대한제국의 「○○○○조례」에 의해 설립된 국책은행인 ○○○○ 부산지점(일제강점기 조선은행 부산지점)이 있었던 곳이다. 일제강점기에 현 부지에 있었던 조선은행 부산지점 건물은 경성(서울)의 본점과 함께 르네상스 스타일의 외관을 가진 건물로 타츠노카사이 설계사무실에서 설계하여 준공하였으나, 해방 이후인 1963년 옛 건물을 철거하고 지금의 근대식 건축물을 신축하여 사용하였다.","a":"구 한국은행 부산본부","c":"문화유산자료","nc":"","r":"부산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659439.jpg"},{"q":"○○○○은 조선말기의 유학자인 송산 권재규(1835～1893)가 문생들을 가르치기 위한 장소로 1934년에 건립하였다. 송산 권재규는 우천 권극유의 10대손으로 노산 기정진의 학문을 계승한 강우(江右)지역 노론계열의 대표적 인물 중 한사람이다. 지금도 ○○○○ 뒤쪽에 위치한 경현사(사당)에서는 매년 음력 3월 중정(中丁)일에 송산 권재규의 향사를 드리고 있다. 경현사(사당), 내삼문, ○○○○, 문간채가 일축선상에 남향으로 배치되어 있으며, 흙과 돌로 쌓아올린 담장이 건물 주위를 둘러싸고 있다.","a":"산청 인곡서당","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666524.jpg"},{"q":"○○○○는 서울특별시 중랑구 망우동에 관한 인문지리서로, 조선시대 지리지가 군현별로 편찬되는 것이 일반적인데 비해, 이 지리지는 동 단위로 편찬되었다는 특징이 있다. 내용상으로도 동계, 동규, 향약, 선생안, 선배비장 등 지방의 특수 사정을 상세히 기록하여, 조선 시대 지방사 연구의 귀중한 자료가 되고 현전사례가 매우 드물다.","a":"망우동지","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636524.jpg"},{"q":"연대가 오래되지는 않았지만 19세기 후반~20세기 전반 서울,경기 지역에서 유행한 괘불의 전형적인 양식을 보여주는 작품으로 괘불의 지역적 특징을 잘 반영하는 작품이다. 특히 1909년에 조선의 마지막 황제 순종과 순종비 순정효황후(純貞孝皇后) 및 황태자 영친왕의 수명장수를 기원해서 금어 혜과(惠果)와 한곡(漢谷)이 그린 괘불탱이어서 다른 예보다 우수한 편이다.","a":"사자암 영산회괘불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2595115.jpg"},{"q":"조선 철종 7년(1856)에 지은 옛 집으로, 안채, 사랑채, 행랑채, 문간채가 있다. 안채는 앞면 4칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 안채 앞쪽에 있는 사랑채는 앞면 4칸·옆면 2칸 규모로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이며, 기둥은 원기둥이다. 앞에서 볼 때 왼쪽 첫칸의 지붕은 다른 3칸보다 훨씬 낮고 각기둥으로 되어 있는데, 이는 후에 달아낸 것이기 때문이다. 행랑채는 앞면 3칸·옆면 2칸의 팔작지붕집이고, 공기가 잘 통하도록 땅에서 40㎝높이에 널판으로 바닥을 깔았다.","a":"장재영가옥","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658310.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 봉암사 뒤쪽 기슭에는 3기의 부도가 자리하고 있는데, 이 부도도 그 중 하나로, 조선시대 전기의 승려인 ○○○의 사리를 모셔두고 있다. ○○○의 호는 득통으로, 21세에 출가하여 승려가 되었다. 세종의 부름을 받아 4년동안 대차어찰에 머무르며 교화를 하였고, 봉암사를 새로이 보수하기도 하였다. 이 절에서『금강설의』를 지었으며, 세종 15년(1443)에 입적하였다.","a":"함허당득통탑","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662660.jpg"},{"q":"○○○은 신라 눌지왕 18년(435)에 세워졌다고 전해지며, 고려 광종 19년(968)에 혜거국사가 중수하여 칠성암이라고 칭하였다. 이후 임진왜란 때 큰 피해를 입은 뒤 인조 10년(1632)에 나한전을 건립하였으며, 효종 4년(1653)에 기성대사가 중수한 후 철종 5년(1854)에 ○○○○○가 다시 중수하여 ○○○이라 개칭한 후 지금까지 이어져 오고 있다. ○○○○○은 조선 철종 5년(1854)에 ○○○을 고쳐 지은 ○○○○를 그린 것이다. 그림 아래에 ‘동치2년(同治二年)’이라고 적혀 있어 1863년에 제작된 것을 알 수 있다.","a":"칠곡 도덕암 몽계당 선의대사 진영","c":"시도유형문화유산","nc":"","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2022041516263600.jpg"},{"q":"백촌 김문기(1399∼1456) 선생의 학문과 덕행을 추모하고 이를 계승하고자 세운 곳이다. 김문기 선생은 세종 8년(1426) 과거에 급제하여 여러 관직을 두루 거쳤으나 사육신과 함께 단종복위를 꾀한 사건으로 희생당하였다. 그 뒤 영조 7년(1731) 복관되고, 영조 33년(1757) 충의(忠毅)란 시호가 내려졌다. ○○○는 선생의 후손이 1870년에 세웠으며, 1994년에 크게 보수하여 오늘에 이른다. 현재 남아있는 건물은 외삼문, 추원재, 내삼문, 사당이 있다. 사당은 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"거창 오례사","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664287.jpg"},{"q":"1907년에 편수 보암긍법(普庵肯法), 두흠(斗欽), 금어 봉감(奉鑑), 법연(法沿)범천(梵天) 등이 조성한 ○○○후불화로, 대시주인 강문환ㆍ강재희가 황명을 받들어 황제, 황태자, 태자비, 귀비 엄씨, 의친왕과 비, 영친왕 등의 성수만세(聖壽萬歲)를 기원하며 제작한 것이다. 화면의 중앙의 ○○○○을 중심으로 8대보살과 10대제자, 사천왕, 팔부중, 천인 등이 화면 가득 배치되어 있다. ○○○○은 수미좌 위의 청련의 연꽃대좌 위에 하품중생인(下品中生印)을 짓고 결가부좌하였는데, 갸름한 얼굴에 가는 눈썹과 눈, 좁은 입, 높게 솟은 육계가 특징적이다.","a":"수국사 아미타불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636433.jpg"},{"q":"한성기 백제의 지방 마을 유적으로 북쪽 배후의 왕방산 줄기와 남쪽의 한탄강 지류인 ○○천 사이 충적지에 위치한다. 세 차례의 시굴 및 발굴 조사에서 집자리 27기, 작은 구덩이 89기, 도랑 11기, 지상식 건물지 2기 등이 조사되었다. 집자리는 대부분 남쪽에 돌출된 출입 시설이 있는 ‘凸’ 또는 ‘呂’ 모양의 반움집이지만, 거주 공간은 육각형 모습이다. 규모는 다양한데, 경기도박물관이 조사한 2호 집자리는 길이가 23.6m에 이르며, 기와와 철제 못과 같은 건축 부재가 사용된 점에서 이 마을의 최상위 계층 인물이 거주했던 것으로 보인다.","a":"포천 자작리 유적지","c":"시도기념물","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647527.jpg"},{"q":"○ 名 稱 : 河東 金鳳寺 銅造菩薩坐像 ○ 時 代 : 中國明代 ○ 數 量 : 1軀 ○ 材質形狀 : 銅造, 改金 ○ 規 格 總高 20.8cm 頂~顎 6.3cm 寶冠高 2.4cm 髮際線~顎 3.3cm 面幅 3.1cm 面厚 4.0cm 耳~耳 4.1cm 肩幅 8.3cm 胸厚 4.9cm 膝幅 10.9cm 膝高 1.5cm 臺座高 4.7cm 臺座底部前後最大徑 10.4cm 臺座底部左右最大徑 14.1cm 內孔深 15.3cm 現 狀 및 表現技法 전체 높이가 20.8cm인 소형의 이 보살상은 화려한 보관을 쓰고 앙련과 복련이 대칭적으로 조출되어 있는 연화대좌 위에 선정인과 같은 수인을…","a":"하동 금봉사 소장 동조 보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666660.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고 부르며, 주로 경제력이 있거나 정치권력을 가진 지배계층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 고흥군 천봉산의 서남향으로 뻗은 줄기가 보성만과 만나는 산기슭에 있는 이 고인돌군은 바둑판식으로, 40여 기가 산기슭을 따라 남북으로 열을 지어 분포하고 있다.","a":"고흥중산리지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654315.jpg"},{"q":"전북 태인현 고현내(현 정읍시 칠보면) 일대에 세거한 ○○○○ 문중의 ○○○ 8매(교지 4, 교첩 3, 분재기 1매)이다. 조선 개국원종공신 충민공(忠敏公) 김회련(金懷鍊)의 현손이며 사정 윤손(潤孫)의 장남인 희윤(希尹), 희윤의 장남 약회(若晦), 약회의 아들 원(元), 원의 3남 대립(大立)의 아들 관(灌) 등 4명의 교지와 교첩, 그리고 김희윤의 처 정씨의 분재기를 포괄하고 있다. 15세기 말(1495)에서 17세기 전반(1615) 5대에 걸친 문서들로 조선 전기 과거 관직제 및 경제사 연구에 중요한 자료이다.","a":"도강김씨 훈도공파 종중 고문서","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639799.jpg"},{"q":"원래 고래 후기에 제작된 것으로 추정되는 3○○○이나 2005년 도난되어 지대석만 남아 있다. 1층 탑신석만이 하나의 돌이고 나머지는 아래층의 옥개석과 윗층의 탑신석이 같은 돌로 만들어졌는데 옥개석의 파손이 심하였다. 석탑 주변에 다수의 기와편이 확인되어 절터로 추정되고 있으나 구체적으로 밝혀진 것은 없다.","a":"홍천양덕원삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660326.jpg"},{"q":"탱화란 액자나 족자 형태로 만들어 법당에 걸어둘 수 있게 만든 불교그림을 말한다. ○○○에 보존되어 있는 이 그림은 산신을 그린 그림으로, 크기는 가로 150㎝, 세로 150㎝이다. 일반 탱화에서는 산신이 호랑이 옆에 앉아 있는데, 이 그림에서는 산신이 호랑이를 타고 어딘가로 행차하는 모습이며, 그 양옆으로 그를 따르는 동자를 표현해 놓았다. 돋보이는 필치를 보여주는 작품으로, 제작 연대는 조선 순조 33년(1833)으로 기록되어 있다.","a":"산청 정취암 산신탱","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664453.jpg"},{"q":"후세들의 교육과 성리학 연구를 위해 세운 건물이다. 안동 권씨인 권극경 선생이 효종 1년(1650)경 창리마을 뒤 계곡에 ‘지족당’으로 이름 붙힌 초가집으로 시작했으나 그 뒤 1930년 규모를 늘려 창리마을로 옮겼고, 1987년 ○○댐 공사로 지금 있는 자리에 옮겨 지었다. 앞면 5칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다.","a":"합천 덕암정사","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664233.jpg"},{"q":"충헌사는 충헌공(忠憲公) 양기 선생을 비롯해 양치, 양희지, 양응춘, 양훤을 배향한 사당으로 양기 선생의 영정을 안치하고 있으며, 인조 4년(1626)에 건립되었다. 배향인물 중 양기 선생은 중국 홍능인으로 고려 말에 노국대장공주(공민왕 왕비)를 모시고 우리나라에 왔다가 당시 조선인의 궁핍한 생활을 보고 돌아가 고려의 조공제도를 폐지케 하였으며, 후일 우리나라에 귀화하여 상당백의 작위와 청주 양씨의 시조가 되었다.","a":"논산충헌사","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639319.jpg"},{"q":"순천시 석현동 소재의 ○○○ 대웅전에 소장되어 있다. 순천 선적사(順天善積寺)에서 제작된 것으로 언제 이곳으로 옮겨졌는지는 알 수 없으나, ○○○와 선적사와 관련은 선암사 중수비(1703년)의 기록을 통해 추정해 볼 수 있다. 중수비에는 ○○○와 선적사가 선암사의 말사 였다는 것을 알 수 있다. 이것으로 보아 정확히 알 수 없으나 스님들간에 교류가 이루어지면서 이동된 것으로 추정된다. 종의 양식을 보면 종정부는 단용의 용뉴와 반구형의 천판을 갖추고 있으며, 종신부는 상대·유곽·보살입상이 장식되어 있다.","a":"순천향림사동종","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640213.jpg"},{"q":"경상남도 진해시 남산 꼭대기에서 능선을 따라 산기슭으로 뻗쳐 쌓은 산성이다. 임진왜란 당시 왜군들이 장기전에 대비하기 위해 우리나라 남해안에 축조한 18개의 성 가운데 하나이며, 왜장 소서행장(少西幸長)이 진을 치고 왜군의 제2기지로 활용했던 곳으로 알려져 있다. 정상부에 본성(本城)을 두고 아래에 2개의 성을 질서있게 배치하였고, 육지방면의 방비를 철저히 하기 위하여 남쪽으로 긴 나성을 둘렀다. 성안의 넓이는 약 5,000평 정도이고, 현재 남은 성벽의 길이는 700∼800m이며 높이는 3∼8m이다.","a":"창원 웅천왜성","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655215.jpg"},{"q":"전라남도 광양시 진월면 ○○○ 해발 170m 고지에 자리잡고 있고, 지도상에는 봉임산성(鳳任山城)으로 표기되어 있다. 산성의 총 길이는 100m이고, 면적은 1,422㎡, 너비는 520㎝로 동서축으로 긴 타원형을 하고 있다. 축조 시기는 삼국시대부터 있었다는 설과 임진왜란 시기에 쌓았다는 설이 있으나, 산성의 형식과 축조 기법으로 보아 백제시대에 축조되었을 가능성도 있다. 산 정상부의 일정한 공간을 둘러싸고 있는 테뫼식 산성이고 성벽의 안팎을 모두 돌로 축성한 내외협축식 산성이다.","a":"광양진월신아리보루","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662317.jpg"},{"q":"성주 ○○○○○은 조선 철종조에 공조판서를 역임한 응와(凝窩) 이원조(李源祚)의 둘째 아들인 민와(敏窩) 이기상(李驥相)이 살림집으로 건립(1850년으로 추정)한 것이다. 우측으로 난 입구를 들어서면 넓은 마당을 사이에 두고 사랑채가 남향하여 자리 잡고 있으며, 사랑채의 좌측에는 안채가 배치되어 있다. 안채 전면에 세워진 중문채를 들어서면 안마당을 사이에 두고 안채가 남향하여 자리 잡고 있는데 안마당의 좌측에는 고방채를 두어, 전체적으로 튼‘ㅁ’자형의 배치형태를 이루게 하였다.","a":"성주대산리도동댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658895.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 법곡동에 있었으나 임진왜란 때 소실되었고 그 뒤 광해군 2년(1610)에 지금 있는 자리로 옮겨 세웠다. 전체적인 구조는 전학후묘의 전형적인 형태로 앞쪽에는 교육 공간을, 뒤쪽에는 제사 공간을 두었다. 입구에는 하마비·홍살문이 있고 외삼문을 지나면 정면에 교육 공간인 명륜당과 기숙사인 동재가 있다. 명륜당 뒤쪽 내삼문을 지나면 정면에 제사 공간인 대성전이 있다.","a":"온양향교","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652900.jpg"},{"q":"나주시청 앞쪽의 300여m 국도변에 있는 샘물이다. 고려 태조 왕건과 장화왕후 오씨부인이 인연을 맺은 장소로, 이 샘을 빨래샘 즉 ‘완사천(浣紗泉)’이라 부르고 있다. 전하는 말에 의하면, 왕건이 고려를 건국하기 전 나주에 10년간 머무르게 되었는데, 어느날 진 위쪽 산 아래에 다섯가지 색의 상서로운 구름이 있어 가보니 샘에서 아리따운 여인이 빨래를 하고 있었다. 왕건이 물 한그릇을 청하자, 여인이 버들잎을 띄워 주었는데, 급히 물을 마시지 않게 하기 위함이었다 한다.","a":"나주완사천","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654244.jpg"},{"q":"○○○○는 병인양요와 신미양요 등을 겪고 나서 경기 연안의 방어시설을 강화할 필요성을 절감한 정부의 명을 받은 어영대장 신정희(申正熙)와 강화유수 이경하(李景夏)가 경기 연안의 군사시설을 확충하면서 인천으로 들어오는 서양인들의 배를 막기 위해 1879년에 구축한 것이다. 축조당시의 명칭은 호구포대였으난 현재는 ○○○○로 부르고 있다. 축조된 후 인근에 설치되어 있던 묘도포대, 제물포대 등과 함께 화도진(花島鎭)에 소속되어 있었으나 1894년 화도진이 철폐되면서 이 포대도 폐쇄된 것으로 추측된다.","a":"논현포대","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636970.jpg"},{"q":"정암 조광조(1482∼1519)와 학포 양팽손(1488∼1545)의 학문과 덕행을 추모하기 위해 세운 서원이다. 조광조는 조선 중기 문신으로 성리학 연구에 힘써 김종직의 학통을 이은 사림파의 대표적 인물이 되었다. ‘여씨향약’을 8도에 실시하도록 하였고 현량과를 처음 실시하였으며 위훈삭제사건으로 반정공신들의 반발을 사서 죽음을 당했다. 조광조는 선조 1년(1568) 영의정으로 추증되었다. 양팽손은 조선 중기 문신이다. 중종 14년(1519) 기묘사화가 일어나자 조광조·김정 등을 위해 항소하다 삭직되었다. 회화에도 일가견을 보여 안견의 산수화풍을 계승하였다.","a":"죽수서원","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662079.jpg"},{"q":"경상남도 ○○군 수동면 우명리에 위치한 ○○○○에 있는 불상으로 ○○○○ 3층 석탑에서 20m 가량 떨어진 곳의 개천 주위에 있는 불상이다. 오른팔 등에 파손이 있고, 하체가 묻혀 있으나 상체의 상태는 비교적 좋은 편이다. 머리 부분은 신체와 비례가 맞지 않아 매우 어색한 느낌을 준다. 또한 선각에 가까운 띠주름식의 옷주름은 형식화되었고, 좁은 어깨, 평판적이고 직선적인 신체의 윤곽선 등은 생동감이 없다. 이러한 표현 등에서 당대 거구(巨軀) 불상에 나타난 조형성을 잘 보여주고 있는 고려시대의 석불좌상임이 분명하다.","a":"함양 승안사지 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641400.jpg"},{"q":"8첩 병풍에 평양성(平壤城)과 대동강(大洞江)의 전경 및 평양감사(平壤監司)의 대동강(大洞江)에서의 선유(船遊)광경을 가로로 길게 담은 성읍풍속도(城邑風俗圖)이다. 제 1첩은 평양성 밖, 제 2-5첩은 내성(內城), 제 6첩은 중성(中城), 제 7-8첩은 외성(外城)의 모습이 그려져 있다. 각종 지형과 시설물, 공해(公廨,관청)등에는 묵서(墨書)로 해당 명칭을 표기하였는데 매우 상세한 편이다. 평양성의 우측에서 비스듬하게 내려다본 시점이 일관되어 평행 사선 방향으로 늘어선 건물들의 모습과 지세의 원근(遠近)및 고저(高低)도 자연스럽다.","a":"기성도병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590404.jpg"},{"q":"충청북도 ○○시 상당구 율량동 ○○○에 있는 불상으로 왼손에 약그릇을 들고 있어 중생을 질병의 고통에서 벗어나게 해준다는 약사불을 형상화한 것임을 알 수 있다. 몸 뒤의 광배(光背)는 따로 만들어 놓았고, 목은 부러져 있던 것을 시멘트로 보강하여 놓았다. 머리 위에는 상투 모양의 머리묶음이 낮게 솟아 있으며, 얼굴에는 살이 통통하게 올라 있다. 당당해 보이는 어깨에는 왼쪽에만 옷이 걸쳐 있고 평행선을 이루는 옷주름을 그리면서 팔목과 무릎 아래까지 덮고 있다. 살이 찐 가슴은 노출이 많고 젖꼭지가 사실적으로 표현되어 주목되며, 손모양은 오른손 끝이 땅을 향하고 있다.","a":"청주 서기사 석조약사여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638665.jpg"},{"q":"조선 말기 근대식 무기를 제작하던 기기창 건물로 강화도 조약이 이루어지고 8년 후인 고종 21년(1884)에 지어졌다. 당시는 무기의 근대화를 위해 새 제도를 마련하고 근대식 군사훈련과 무기제조에 힘쓰던 때이다. 건물의 이름인 ‘번사(飜沙)’라는 말의 뜻은 흙으로 만든 틀에 금속용액을 부어 만드는 것을 말한다. 검은 회색 벽돌로 벽을 쌓았으며 붉은 벽돌로 띠를 두른 후, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕을 올렸다. 문은 무지개모양이며 정문은 화강암으로 만들고 옆문은 붉은색 벽돌로 띠를 넣어 장식하였다.","a":"기기국 번사창","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636198.jpg"},{"q":"○○○은 한국의 토속신인 산신 곧 산신령을 모시는 곳으로 마을과 절을 수호하는 기능을 갖는다. 삼각산 보현봉 기슭에 자리하고 이 ○○○은 남○○○으로, 원래는 여○○○, 부군당 신목과 함께 있었으나, 여○○○과 부군당 건물은 현존하지 않고 다만 ○○○○○과 부군당 신목(서울시지정보호수 제65호)만 남아있다. 건물은 앞면과 옆면이 모두 1칸으로 되어있고, 지붕은 옆면에서 보았을 때 지붕선이 ‘사람인(人)’자 모양과 비슷한 맞배지붕을 얹었다. 내부 정면에는 노인과 범을 그려 놓은 ‘기호노인상(騎虎老人像)’의 산신도가 걸려있다.","a":"평창동보현산신각","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658038.jpg"},{"q":"금당사 경내에 있는 탑으로, 현재 남아있는 부재들로 보아 5층 석탑이었을 것으로 추정된다. 기단부(基壇部)는 가운데돌이 없어져 다른 돌로 대신하였으며, 그 위로 3층의 탑신(塔身)을 쌓아 올렸다. 지붕돌은 밑면에 3단의 받침을 두었다. 꼭대기에 놓인 머리장식은 후에 보충한 것으로 보인다. 규모가 작은 탑으로, 제작양식이나 수법으로 보아 고려시대에 세운 것으로 추정된다.","a":"금당사석탑","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661749.jpg"},{"q":"송도(宋滔)는 연안 송씨로, 조선 초기 울산에 살았던 효자였다. 선생은 울산지역 최초의 생원(生員)으로 병든 부모를 10여 년 동안이나 정성껏 간호하였다. 모친이 병이 깊어 물고기회를 구하고자 하였으나, 가난하여 마련할 수가 없어 얼음판을 두드리며 울었다. 그러자 붕어가 뛰어나왔다고 한다. 또한 제사를 지내려고 제수를 구하니 산의 꿩이 날아들어 왔다고 한다. 1년 사이에 부모가 잇달아 돌아가시자 몸소 흙과 돌을 져다 무덤을 만들고, 유교식 예법에 따라 사당을 세워 신주를 모시고 새벽마다 배알하고, 때에 맞추어 제사지냈다.","a":"효자송도선생정려비","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637269.jpg"},{"q":"대구에 있는 비슬산(琵瑟山) 일원에는 신라시대 이래의 많은 불교 유적이 산재해 있는데 ○○○○○이 있는 곳도 그 중의 하나이다. 높이 2.8m의 화강암을 이용하여 한쪽면에 광배(光背)와 불상을 조각한 것으로 왼손에 약항아리를 들고 있어 약사불을 형상화한 것임을 알 수 있다. 민머리에 상투 모양의 머리묶음이 큼직하게 솟아 있으며, 얼굴에는 풍만한 인상이 나타나 있다. 부처의 몸에서 나오는 빛을 형상화한 광배는 배(舟)모양으로 원형의 머리광배와 가는 타원형의 몸광배를 도드라진 선으로 나타내고 있다.","a":"달성 용봉동 석불입상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636908.jpg"},{"q":"○○이란 선사시대 사람들이 먹다버린 조가비 껍데기나 생활쓰레기들이 쌓여 만들어진 것으로 조개더미라 부른다. 이곳에서는 중석기시대에서 신석기시대에 이르는 다양한 유물이 출토되었다. 이 조개더미에서는 뗀석기에서 간석기로 넘어가는 과정과 흑요석석기가 톱날석기로 변하는 과정, 연모와 치레걸이 등의 변화와 같은 신석기시대 구분에 좋은 길잡이가 될 수 있는 유물이 다량 출토되었다. 특히 세석기는 우리나라에도 중석기가 있었음을 증명해 주는 중요한 유물이다. 동항리에서는 신석기시대 돌무지 시설과 유물이 출토되었는데, 돌무지 시설아래에서 2구의 사람뼈가 발견되었다.","a":"통영 욕지도 패총","c":"시도기념물","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654835.jpg"},{"q":"조선의 무관인 ○○○의 묘이다. ○○○의 자는 군실(君實), 시호는 정익(貞翼)이며 본관은 한산(韓山)이다. 병마절도사(兵馬節度使) 의배(義培)의 손자로서 조선 효종 2년(1651) 무과에 급제, 비변랑(備邊郞), 도총사를 거쳐 숙천(肅川)부사로 선정을 베풀어 거사비(去思碑)가 세워졌다. 충청병마절도사를 거쳐 특히 회령(會寧)부사에 보직되어 가선대부(嘉善大夫)의 위계에 오르고 한흥군(韓興君)에 봉해졌는데, 회령은 북방의 거진(巨鎭)으로서 야인(野人)들과 서로 무역하는 시장이 있어 야인상인들이 오는 정원도 없고 체류하는 기한도 없어서 우리의 피해가 많았다.","a":"이여발 묘","c":"시도기념물","nc":"","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645671.jpg"},{"q":"부인사는 신라 선덕여왕의 명복을 빌던 법당으로 ‘부인(夫人)’이란 선덕여왕을 말하는 것이라고 한다. 원래 이곳은 부처의 힘으로 외침을 막고자 새긴 고려 초조대장경판을 보관하던 곳이었으며, 고려 무신집권에 항거해 일어나 승려들의 본거지이기도 하였으나, 고려 고종 19년(1232) 몽고 침입으로 불타 없어졌다. 이 절터에는 축대, 초석, 당간지주 등 당시의 석조물이 많이 남아 있고, 주변에는 건물초석, 석탑, 석등들이 흩어져 있다. 이 석조물들은 당시 부인사의 규모을 알려주는 자료이다.","a":"부인사지","c":"시도기념물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645337.jpg"},{"q":"조선 중기 무신 성은(城隱) ○○○ 장군의 묘이다. 장군과 부인 하동 정씨, 장군의 아버지 남유의 묘가 한 자리에 모셔져 있다. ○○○은 선조 31년(1598) 정유재란 때 아버지가 왜적에게 총을 맞고 죽자, 학업을 포기하고 활쏘기와 말타기에 전념하여 선조 35년(1602)에 무과에 급제하였다. 그 후 여러 벼슬을 거쳐 인조 5년(1627) 정묘호란 때 평안도 안주에서 청나라 군대와 싸우다가 성이 함락되자 자결하였다. 죽은 후에 충절의 인물로 여겨져 벼슬이 영의정으로 높여졌고 의천부원군으로 받들어졌다.","a":"남이흥장군묘일원","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652769.jpg"},{"q":"이 책은 조선과 영국이 통상을 조약한 내용을 담은 문서이다. 영문으로 된 것은 자세하게 기록되어 있으나, 말미에 붙은 한문은 한 장으로 양국대신을 파견하여 조약을 이행할 것을 간략하게 기록하고 있다. 고종 21년(1884) 3월 8일 고종이 창덕궁에서 직접 서명한 것이다. 이것은 영국과의 외교사를 연구하는데 중요한 자료이다.","a":"조영통상조약(영문)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587949.jpg"},{"q":"이곳은 함안 조씨 문중에서 1917년 세운 재각으로 집안의 대소사를 의논하거나 제사를 지낼 때뿐만 아니라 마을의 노인들이 모이는 장소로 이용하고 있다. 앞면 4칸·옆면 2칸 규모의 건물로 2층 기단 위에 세워 마당보다 높다. 건물 중앙에 있는 대청마루는 사람이 모일 때 문을 위로 들어 올려 넓은 공간을 마련할 수 있게 꾸몄다. 지붕은 옆에서 보면 여덟 팔(八)자 모양의 팔작지붕이며, 건물 주위에는 각종 나무와 정원석, 연못이 있다.","a":"영류재","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662155.jpg"},{"q":"○○○에서 서북쪽으로 30m 떨어진 공터에 있던 것을, 이 곳으로 옮겨 세웠다. 원래의 탑은 2층 기단(基壇) 위에 3층 탑신(塔身)을 세우고 머리장식을 얹었을 터이나, 지금은 아래층 기단과 머리장식의 일부가 없는 상태이다. 탑신의 각 몸돌에는 모서리마다 기둥을 새겼는데, 2층과 3층의 몸돌은 후대에 만들어 끼운 것이다. 각 층 지붕돌에는 밑면에 3단씩의 받침을 두었다. 전체적으로 통일신라시대의 일반적인 석탑양식을 따르고 있는데, 세워진 시기는 통일신라 후기∼고려 전기 즈음일 것으로 짐작된다.","a":"원효암 서편 삼층석탑","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636637.jpg"},{"q":"○○○ 소장 ○○○는 ○○○에 배향된 오신남의 교지 21매를 비롯하여 오미수(吳眉壽)·오팔원(吳八元)·오상지(吳尙志)·오회영(吳會英)·오도삼(吳道三)·오대항(吳大恒), 그리고 유인윤씨(孺人尹氏)·유인백씨(孺人白氏)·유인선씨(孺人宣氏)·유인위씨(孺人魏氏) 등 평해오씨문중 후손들의 교지 13건, 호구단자 11건, 등장 5건, 그리고 문중의 문중답과 송계안, 벽송사(碧松祠) 관련 양안(量案) 관련 자료가 현전한다. 그리고 1618년 오신남에게 안흥량의 도적소탕의 공을 기려 내린 교서가 있다.","a":"강진덕호사소장고문서","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101118355800.jpg"},{"q":"임진왜란 당시 최초로 승병을 일으켜 전국 곳곳에 승병이 일어나는 계기를 만든 영규대사의 호국정신을 기리기 위해 세운 비이다. 영규대사(?∼1592)는 서산대사 휴정의 제자로, 왜구들의 침략과 약탈에 분을 참지 못하여 스스로 승병장이 되었다. 승병 수백명을 모아 관군과 더불어 청주성을 되찾고, 이어 의병장 조헌과 함께 금산 연곤평 전투에 참가하였다가, 이 전투에서 크게 다쳐 숨을 거두었다.","a":"영규대사비","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660963.jpg"},{"q":"○○○○○은 조선시대 명현(名賢)인 이자·이연경·김세필·노수신 등 4현을 모신 서원으로 후생교육을 담당하던 곳이었다. ○○○○은 조선 선조 15년(1582)에 건립되었고, 현종 13년(1672)에 나라에서 ‘○○○○’이라는 현판을 내려 사액서원이 되었다. 고종 8년(1871) 전국적으로 내려진 서원 철폐령에 의해 폐원되었다가 터만 남아 있던 것을 1998년 전통양식으로 복원하였다. 건물은 앞면 3칸·옆면 2칸 크기로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다.","a":"충주 팔봉서원","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651271.jpg"},{"q":"금고란 절에서 사용하는 도구로서 대중을 불러모으거나, 급한 일을 알리는데 사용하는 금속으로 만든 타악기이다. ○○○ 금고는 지름 90㎝, 두께 15㎝의 대형 금고이다. 옆면은 뒷면을 향해 안으로 기울어진 좁은 입구를 가진다. 앞면에 동심원이 새겨 있을 뿐 전체적으로 무늬가 없다. 옆면에는 3개의 고리가 달려있으며, 만들어진 때와 금고에 대한 기록이 새겨 있다. 이 글로 보아 동치(同治) 원년인 조선 철종 13년(1862)에 만들어졌음을 알 수 있다. 이 금고는 조선 후기에 제작된 대형 금고인 동시에 만든 시기가 명확한 중요한 자료이다.","a":"범어사 대웅전 청동북","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659349.jpg"},{"q":"이 유물은 광산 김씨인 후조당 김부필(1577∼1644)이 나라에서 시호를 내릴 때 받은 교지와 「퇴계유묵」, 『향병일기』, 『전가보첩』 등 4종 6점이다. 김부필은 퇴계 이황의 문인으로, 학문이 뛰어났던 인물이다. 그가 죽은 후 순조 2년(1802)에 오위도총부도총관에 증직되었고, ‘문순(文純)’이란 시호를 받았다. 그 밖에 광산 김씨의 유물로 문집, 서책 등 수백 점이 숭원각에 보호, 관리되고 있다.","a":"후조당유물","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640357.jpg"},{"q":"조선 후기의 문신인 서곡(西谷) ○○○의 묘이다. 인조 14년(1636) 별시문과에 병과로 합격하였으며, 병자호란이 일어나자 소현세자가 볼모로 중국 심양(지금의 북경)에 갈 때 따라 갔으며 귀국해서는 여러 벼슬을 역임하였다. 효종 2년(1651) 교리로서 술에 취하여 경연에 나갔다가 탄핵을 받아 파직하였으며 그후 현종 1년(1660) 대사간이 되었고, 이듬해 진위겸 진향부사로 중국 청나라에 다녀와 평양도 관찰사가 되었다. 1672년 한성부판윤으로 다시 동지부사가 되어 청나라에 다녀왔다.","a":"효간공 이정영 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636276.jpg"},{"q":"○○○로 가는 오솔길 양쪽에 서 있는 한 쌍의 돌장승이다. 사찰 입구에 두는 장승은 절의 경계를 표시하는 역할과 더불어 잡귀의 출입을 막고, 풍수지리적으로 허한 곳의 기운을 불어넣는 등의 기능을 하게 되는데, 이곳의 장승은 사찰의 경계표시·수문장의 역할과 함께 마을 사람들에 의해 그들의 수호신이 되고 있다. 왼쪽에 있는 남장승은 높이 220㎝ 둘레 70㎝의 크기로, 상투를 얹은 듯한 둥근 머리에 관모를 쓰고 있다.","a":"창녕 관룡사 석장승","c":"시도민속문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659038.jpg"},{"q":"조선 중기의 선비인 김선(1568∼1642) 선생의 초상화이다. 김선의 호는 시서거사로, 선조 38년(1605) 사마시에 급제하였으나 광해군의 어지러운 정치를 한탄하며 관료로 진출하지 않고, 초가집을 지어 은거생활을 하였다. 초상화는 오른쪽을 바라보며 의자에 앉아 있는 전신상으로, 원본을 후대에 그대로 옮겨 그린 것으로 추정된다. 오른손은 무릎에 올려놓고 왼손에는 부채를 들고 있으며, 머리에는 대나무로 만든 두건을 쓰고 있다. 얼굴은 마마를 앓은 자국까지 세밀하게 표현하였으며, 옷은 유학자의 기품을 느끼게 하는 학창의를 입고 있다.","a":"시서영정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662107.jpg"},{"q":"○○○는 조선 후기 병인양요(1866)와 신미양요(1871)를 승리로 이끈 흥선대원군이 서양세력을 배척할 것을 온 백성에게 경고하고자 서울과 전국 교통 요충지에 세우도록 한 비이다. 이 ○○○는 원래 땅에 묻히었다가 후에 산 기슭으로 자리를 옮겨 이곳에 남게 되었다. 길쭉한 직사각형으로 각 면이 많이 파손된 모습이다. 앞면에는 ‘서양 오랑캐가 침입하는데 싸우지 않으면 화친하는 것이요, 화친을 주장하는 것은 나라를 팔아먹는 것이다’라는 글을 새겨 대원군의 강력한 쇄국의지를 적고 있다.","a":"옥천 척화비","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649153.jpg"},{"q":"척화비란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국의 중요 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 비는 널찍한 사각받침돌 위에 비몸을 세운 모습으로, 원래는 순흥초등학교 내에 있었으나, 1990년에 이곳으로 옮겨 왔다. 고종 8년(1871) 전국에 동시에 세워진 비로, 대원군이 러시아 공사관으로 납치되고 세계 각국들과의 교류가 이루어지면서 대부분의 척화비는 철거되었으나, 이처럼 몇 기의 비들이 곳곳에 남아 옛 우리민족의 자주의식을 다시금 일깨워주고 있다.","a":"순흥척화비","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662940.jpg"},{"q":"○○○의 뒷모실 마을 뒷쪽에 남북으로 활처럼 휘어져 뻗어내린 구릉 정상부에 위치한 무덤들이다. 모두 15기의 무덤이 분포하고 있는데, 9호 무덤의 봉분 형태가 피라미드형으로 봉분 자락에 도랑을 둘렀다. 봉분 안에는 널무덤(토광묘) 3기와 독무덤(옹관묘) 4기가 확인되었는데, 독무덤은 이음식, 합개식, 단옹식이 사용되고 있다. 유물은 토기류, 철조각, 옥종류가 수습되었고, 봉분 바닥에서는 무덤이 만들어지기 전에 지어진, 원삼국시대의 주거지 4기가 확인되었다. 유물과 무덤 축조방법으로 보아, 이 무덤은 4세기 전반에서 후반사이에 형성된 것으로 생각된다.","a":"영암신연리고분군","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662093.jpg"},{"q":"이 불화는 1887년 상궁들의 시주로 19세기말 서울, 경기지역의 대표적 화승인 보암 긍법(普庵 亘法)을 비롯하여 금운 순민(錦雲 洵玟), 봉규(奉奎), 종현(宗現) 등이 그린 ○○○로 팔상의 각 장면 중에서 주요한 장면만을 부각시켜 그린 그림이다. 각 相의 내용은 효과적으로 전달되고 있으며 전체적으로 구성이 안정되어 있고 청색의 사용을 자제함으로서 격조를 느끼게 한다. 따라서 19세기 후반 서울·경기지역 화승의 새로운 도상과 양식을 대표하는 작품이다.","a":"경국사 팔상도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594863.jpg"},{"q":"한양 조씨 옥천 조덕린(1658∼1737) 선생의 옛 집으로 살림채인 정침과 글 읽는 별당인 초당, 가묘인 사당으로 구성된 17세기 말 양반 주택의 대표적인 예이다. 살람채는 안동지방을 중심으로 분포되어 있는 ㅁ자집의 평면구성을 하고 있다. 앞면 5칸의 가운데에 대문을 달고 왼쪽에 안사랑방을 두고 있다. 오른쪽에는 마구간을 고친 온돌방이 있고 부엌·고방이 있다. 살림채의 몸채는 양 옆에 꺾여서 위치하는 부분보다 더 높은 곳에 자리하고 있으며, 전면에는 안마당을 향하여 개방된 6칸 대청이 있다.","a":"주곡동옥천종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658603.jpg"},{"q":"○○○○○은 화강암 재질로 높이 2.5m정도이다. 기단부는 후대 보수과정에서 자연석과 콘크리트를 이용해 지대석을 마련한 후 안상이 새겨진 하층기단석 4매를 놓았다. 상층기단석은 1매로 우주와 탱주를 조각하였으나 위쪽의 갑석은 결실되었다. 탑신은 1매 돌로 이루어져 있으며, 1총ㆍ 3층 탑신에는 우주가 없으나, 2층 탑신에는 우주가 있다. 옥개석은 1층ㆍ2층ㆍ3총ㆍ4층 모두 층받침이 없고 추녀 및 전각의 반전이 심하다. 상륜부의 노반과 보주는 하나의 돌로 만들었으며, 보주에는 연꽃 봉오리 모양을 조각하였다.","a":"의령 수도사 석탑 및 승탑군","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664492.jpg"},{"q":"○○은 고인돌과 함께 청동기 시대 거석문화의 일종으로 자연석이나 자연석을 일부 다듬어 세워놓고 신앙의 대상으로 삼은 것이다. ○○은 다양한 기능과 의미를 가지고 있다. 고인돌과 함께 세워진 ○○은 무덤 공간임을 알리려는 묘표석(墓表石)으로서의 기능을 하며, 마을 입구에 세워진 ○○은 벽사 또는 수구막이 역할을 하는 마을 수호의 기능을 가지고 있다. 또한 논밭이나 이를 내려다보이는 얕은 구릉에 세운 ○○은 풍요를 기원하는 의미를 가지고 있다. 이외에도 경계와 이정표의 기능을 가지고 있다.","a":"여주 석우리 선돌","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2023041310122400.jpg"},{"q":"○○○○○은 대웅전 법당에 봉안되어 있는 ○○○○상으로 높이 35cm, 어깨너비 16cm, 머리높이 17cm(보관 포함), 무릎너비 23cm이며, 표면에 개금이 되어 있는 상태로 전체적으로 보존 상태가 양호하며 눈썹, 눈의 표현, 콧수염, 턱수염과 입술에 채색하여 세부표현을 하였다. ○○○○은 고개를 약간 숙이고 등을 곧게 편 상태로 양손을 무릎 위에 얹고 결가부좌하고 있으며, 옷은 편삼위에 대의를 살짝 걸친 형식이다. ○○○○은 방형의 얼굴에 눈을 가늘게 뜨고 아래로 내려다 보고 있다. 코는 오똑한 편이며, 인중과 윗입술을 도드라지게 표현한 것이 주목할 만하다.","a":"울산인성암석조보살좌상","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659807.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○○○ 가마터는 조선시대 15세기부터 16세기에 걸쳐 ○○○○와 백자를 만들던 곳으로 6곳의 가마터가 확인되었다. 가마의 구조는 굴가마이며, 출토된 유물로는 인화무늬와 귀갑무늬의 ○○○○가 가장 많고 무문 및 상감분청조각과 백자조각도 출토되었다. 특히 ○○○○ 조각에는 ‘경산장흥고’· ‘경산맥석’· ‘부’등의 글자가 찍혀 출토되었는데, 이중 ‘경산장흥고’의 출토로 보아 관청에서 사용되었던 도자기도 제작하여 공급하였음을 알 수 있다.","a":"경산산전동분청사기요지","c":"시도기념물","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654451.jpg"},{"q":"과천시 보광사 경내에 위치한 높이 1.7m 크기의 ○○○○상이다. 머리에는 중절모 형태의 둥근 보개(寶蓋 ; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)를 쓰고 있다. 머리와 신체는 선각으로 표현하였다. 얕은 선각은 선의 흐름이 불안정하고 새김이 분명하지 않으며 신체의 굴곡이나 양감은 전혀 표현되지 않았다. 선각으로 빈약하게 표현된 짧은 목에는 삼도(三道 ; 불상의 목에 표현된 세 줄의 주름으로 지혜를 상징)를 나타내었다.","a":"문원리사지석조보살입상","c":"문화유산자료","nc":"","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660102.jpg"},{"q":"◦ 통일신라 말기 뛰어나 학자인 고운(孤雲) 최치원(崔致遠, 857~?)이 선유(仙遊)한 곳으로 전해지는 유적으로 최치원은 신라 6두품 출신의 유학자로 당에 유학한 후 돌아와 신분 제약으로 자신의 뜻을 실현하기 어려워지자 관직에 미련을 버리고 전국을 유람하였는데, 경치가 아름다운 이곳에서도 머물면서 병풍처럼 둘러진 암벽에 한시(漢詩)를 새겼다고 전하나 지금은 마모되어 알아 볼 수 없음. ◦ 1955년 남포방조제 건설 전에는 맥도(麥島, 보리섬)로 불린 섬이었으나 지금은 육지가 되었음.","a":"최고운유적","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661132.jpg"},{"q":"강원특별자치도 화천군 간동면 ○○○ 절터에 있는 불상으로, 현재 머리와 목 부분을 잃어버린 상태이다. 상체와 하체는 딴 돌로 만들어져 분리될 수 있다. 상체는 떡 벌어진 어깨와 발달된 가슴으로 당당한 모습이다. 얇은 옷을 몸에 밀착시켜서 잘록한 허리가 더욱 강조되었다. 양 어깨에 두른 옷에는 U자형의 옷주름이 새겨져 있다. 도식적인 옷주름 처리로 사실성이 결여되고 조각수법의 미숙으로 생동감이 떨어지고 있다. 오른쪽 어깨와 손목 부분이 깨졌는데, 다소 부자연스럽게 표현된 두 손은 정확한 모양을 알 수 없다.","a":"화천성불사지석불입상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"화천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638152.jpg"},{"q":"임진왜란 때 젊은 나이로 전사한 배인길(1571∼1592)과 그 소식을 듣고 자결한 그의 부인인 월성 이씨의 충열을 기리기 위해 나라에서 내린 한 쌍의 정려문이다. 배인길은 어려서부터 학문과 무예를 익혔으며 22세 때 임진왜란이 일어나자 당시 예안 현감인 신지제의 휘하에 들어가 용궁전투에 참전했는데 전투 중 전사하였다. 정려(旌閭)란 나라에서 충신·효자·열녀를 표창하여 그들이 살던 마을에 세워 주던 문으로 배인길은 충신으로서, 그의 부인은 열녀로서 하사 받은 것이다.","a":"쌍절려","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663265.jpg"},{"q":"이 가마는 1863년(철종14)에 개설된 우리나라 특유의 칸 가마로서 ○○○ 가마라 불리며 몇 년 전까지만 해도 사기를 생산하였던 곳이다. 이 곳에는 가미뿐만 아니라 작업장, 디딜방아, 땅투멍, 쾡(사토를 정제하기 위한 시설), 살림잡이 완벽하게 갖추어진 국내 최고의 가마시설이다. 길이는 17.35m, 외형은 봉통(아궁이), 요리칸(첫째칸)에 이어 조금식 규모가 큰 여섯 개의 칸으로 구성되어 있는데 요리칸으로부터 끝목칸에 이르기까지 단계적으로 위쪽에 12º의 경사로 이어져 있다.","a":"문경망댕이사기요","c":"시도민속문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658901.jpg"},{"q":"향교는 성현의 위패를 모시고 제사를 지내며, 지방 백성의 교육을 담당하기 위해서 국가에서 세운 교육기관이다. 고려 인종 5년(1127)에 화개산 북쪽에 지었으나, 조선 영조 17년(1741)에 조호신이 현재의 위치로 옮겼으며 1966년에 수리하였다. 고려 충렬왕 12년(1286)에 안향이 원나라에 갔다가 돌아오는 길에 공자상을 들여와 모셨다고 전하며, 이후 서울의 각 읍에 조상이나 성현의 위패를 모시는 문묘를 설치했다고 한다. 현재 남아있는 건물은 교육공간인 명륜당과 동재·서재가 있고, 제사공간을 형성하는 대성전과 동무·서무가 있다.","a":"교동향교","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637060.jpg"},{"q":"이 마애불상은 경주시와 청도군의 경계에 있는 ○○○ 9부 능선에 위치하고 있다. 불상은 남쪽으로 면한 편평한 바위 면에 인공을 가하지 않은 상태에서 선각으로 조각하였다. 법의는 통견이고 수인은 선정인을 결한 채 결가부좌를 하고 있다. 안정감 있는 체구에 큰 육계를 표현하였으며 목에는 삼도가 뚜렷하다. 어깨는 약간의 곡선을 그리고 있으나 당당한 편이며 가슴 부분에 띠 매듭이 있다. 불상의 전체 높이는 154cm이다. 전체적인 분위기 등으로 보아 조선시대 마애불로 보여지며 이목구비가 뚜렷하고 완전하여 경주와 청도지역의 마애불을 연구하는 데 귀중한 자료가 되고 있다.","a":"청도장육산마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641173.jpg"},{"q":"○○○성 수구문지 주변에 있다. 임진왜란과 병자호란 등 거듭된 외침이 일어나자 조정에서는 도성 외곽방어를 위해 천연의 요새인 ○○○에 산성을 축성해야 한다는 의견이 대두되었다. 거듭된 논의 속에 1711년(숙종37) ○○○성 축성을 결정하여 그해 4월부터 9월까지 공사가 진행되었다. 축성공사는 훈련도감, 금위영, 어영청 등 삼군문의 병사들이 주도적으로 추진했지만, 이외에도 전국 사찰의 많은 승려가 동원되었다. 축성 후 산성 방어와 관리를 위해 성내에 승군이 주둔할 수 있는 11개의 사찰이 건립되었다.","a":"고양북한산서암사지","c":"문화유산자료","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660274.jpg"},{"q":"홀이란 신하가 관복을 입고 손에 가지는 판(板)을 말한다. 원래 임금 앞에서 명령을 받거나 물어 볼 것이 있으면 그 위에 써서 기록화 하였던 것인데 후세에 의례적으로 되었다. 신라가 당나라 관복을 입은 뒤 부터 한말에 이르기까지 관직에 있는 자의 필수품이었다. 1∼4품까지는 상아로 만들었고 5품이하는 나무로 제작하였다. 청백색 옥으로 된 이 홀은 조선 중종 8년(1513)에 최산두에게 하사된 것으로‘일인유경보명유신(一人有慶寶命維新)’이란 글이 음각되어 있다. 최산두는 조선 전기의 문신으로 중종 8년(1513년) 문과에 급제하여, 이조정랑·장령·사인에 올랐다.","a":"옥홀","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639869.jpg"},{"q":"조선 영조 18년(1742)에 주조된 것으로, 머리부분이 둥글고 아래로 가면서 살짝 벌어지는 형태의 종이다. 종을 거는 고리는 2마리의 용으로 되어 있으며, 몸통은 가운데 2줄의 띠를 둘러 2부분으로 나누고 있다. 위쪽 어깨부분에는 범자를 새겨 둘렀으며, 아래에는 4군데에 유곽을 배치하고 그 사이에 보살입상을 두었다. 몸통 아랫부분에 명문이 새겨 있으며, 입구에서 조금 올라간 부분에는 꽃무늬와 덩굴무늬로 띠를 둘렀다.","a":"희방사동종","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640748.jpg"},{"q":"조선 영조 26년(1750)경에 유정원(1702∼1761)이 지어 학문을 연마하고 후학을 가르치던 정자이다. 지금은 그 후손들이 선생의 덕행을 기리며 자손들을 가르치는 곳으로 쓰고 있다. 유정원은 영조 때의 문신으로 홍문관수찬·사간원교리 등을 거쳐 대사간에 이르렀다. 영조의 총애와 채제공의 추천으로 장헌세자에게 강의하기도 하였다. 한편 지방관으로 있을 때에는 백성들에게 선정을 베풀어 정약용의『목민심서』에서 그 치적을 다루기도 하였다.『역해참고』등 많은 책을 남겼다. 앞면 3칸·옆면 2칸의 규모이며, 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"안동삼산정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640604.jpg"},{"q":"임진왜란 때 활약한 장윤 장군의 업적을 추모하기 위해 세운 것이다. 장군은 무과에 급제하고 사천현감을 지냈으며 선조 25년(1592) 임진왜란이 일어나자 의병을 이끌고 함양, 개령 등지에서 큰 공을 세우며 싸우다가 아쉽게 진주싸움에서 전사하였다. 인조 27년(1649) 지금 있는 자리에 지은 것으로 앞면 1칸·옆면 1칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"장윤정려","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654205.jpg"},{"q":"조선시대에 중앙의 관리가 파견되거나 외국에서 사신이 올 때 잠시 머물 수 있도록 시설해 놓은 곳이다. 정당은 1983년에 수리하였는데 이때 발견된 문서에 의하면 효종 6년(1655)에 새로 지어지고, 순조 3년(1803)에 고쳤으며 ○○○○로 기록되어 있어 종래의 ○○객사 동헌이 아님을 알 수 있다. 배치형식은 정당을 중심으로 좌우에 방이 있으며, 앞쪽에는 중문과 외문 그리고 행랑이 있는 것이 보통이다. 이곳에는 정당과 외문만이 남아있다.","a":"보은 회인 인산객사","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638577.jpg"},{"q":"판수가 8만여 개에 달하고 8만 4천 번뇌에 해당하는 8만 4천 법문을 실었다고 하여 8만대장경이라고 부른다. 월정사에 있는 ○○○○○은 해인사의 고려대장경 경판에서 직접 찍어온 것이다. 조선 고종 2년(1865)에 찍어내어 월정사에서 보관하고 있다. 크기는 가로 84.6㎝, 세로 24㎝이고 한지에 인쇄하였다. 판의 끝에는 경전의 이름과 권수의 간행 차례가 기록되어 있다. 천자문 순서대로 새겨 놓았는데 총 1,511부 6,802권 81,137판으로 되어있다. 고려 때는 물론이고 조선초에도 인쇄되었으나 전부 남아있는 것은 몇 개 전하여지지 않는다.","a":"팔만대장경","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637989.jpg"},{"q":"六友堂은 조선 숙종 때 학자인 성재(省齋) 안후정(安后靜, 1659~1702)이 거처하던 堂으로 그의 장남인 六友堂 안여택(安汝宅, 임술생 1682년)을 비롯한 6형제의 우애를 돈독히 하고 학업에 정진하던 곳이라 한다. 조선후기에 현 위치로 이건했고, 한국전쟁 이후에는 대청 2칸 중 좌측 마루 칸을 온돌방으로 꾸며 사용해 오다가 2010년 가을에 옛 모습대로 복원 수리했다.","a":"영천 육우당","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663741.jpg"},{"q":"《○○○○○》는 1443년(세종 25)에 서장관(書狀官)으로 일본에 다녀온 신숙주(申叔舟 : 1417~1475)가 1471년(성종 2) 왕명을 받아 그가 직접 관찰한 일본의 정치·외교관계·사회·풍속·지리 등을 종합적으로 정리, 기록한 책으로 15세기의 한일관계와 일본 사회 연구에 귀중한 자료이다. 이와 같은 사료적 가치 때문에 1933년 조선사편수회에서 영인 간행하였고, 1974년에도 민족문화추진회(오늘날 한국고전번역원)에서 《해행총재(海行摠載)》를 간행하면서 ○○○○○를 영인 수록하였다.","a":"해동제국기","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636546.jpg"},{"q":"당진군 고대면 당진포리 말봉산 아래 부근에 있으며 돌과 흙을 섞어 쌓은 네모진 성곽이다. 넓은 계곡을 둘러싸며 주위의 산능선을 따라 성벽을 만들었으며 둘레는 약 500m, 높이는 약 2m이다. 이 성은 조선시대 각 도의 여러 진에 배치되었던 종4품의 무관직인 만호가 지휘하는 병선이 있던 곳으로 군량과 무기를 보관하였고 유사시에는 수군이 모이는 장소로 사용하였다. 특히 ○○○○○은 성문을 보호하기 위해 성문 앞에 쌓은 작은 성인 옹성의 형태가 나타나 있고, 윗부분에 설치된 덮개돌이 처음으로 확인되는 등 중요한 가치를 지니고 있는 진성이다.","a":"당진포진성","c":"문화유산자료","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661532.jpg"},{"q":"○○○○○상은 1629년(인조 7)에 수종(守宗) 화상에 의해 조성된 목조 불상으로 현재는 개금되었다. 현재 대웅전에 봉안되어 있으며, 중앙의 ○○○○불을 중심으로 오른쪽에 보현보살이, 왼쪽에 문수보살이 양쪽에서 협시하고 있다. 불상의 높이는 모두 114㎝ 가량으로 대형 불상에 속한다. 중심불인 ○○○○불은 나무 대좌에 결가부좌하고 있으며 수인은 항마촉지인을 맺고 있다. 모리는 나발에 육계가 낮게 표현되어 있다. ○○○○불의 얼굴은 네모나고 눈과 입이 온화한 조선 시대 불상의 전형적인 얼굴을 하고 있다.","a":"은적사석가여래삼존상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639674.jpg"},{"q":"‘○○○○’는 관악산 남동쪽 계곡부의 최상단에 있다. 위쪽에는 연주대가 있고 아래쪽에는 연주암이 있다. ○○○는 급경사 지역에 구역별로 석축을 쌓고 평탄지를 조성하여 건물을 건립한 전형적인 산지 가람의 형태를 보이고 있다. 「연주암지」에 의하면 ○○○는 677년(신라 문무왕 17) 의상조사가 창건했다고 기록되어 있다. 1411년(조선 태종 11) 양녕대군과 효령대군이 세자 직위를 충녕대군에게 물려준 후 관악산에 올라 마음을 달랬다고 한다. 효령대군이 이곳에서 2년간 수양을 하며, ○○○를 현 위치로 옮겨 지으면서 40칸의 가람을 건설하였다.","a":"과천관악사지","c":"시도기념물","nc":"","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647232.jpg"},{"q":"龍華寺는 1925년에 노천에 있던 석불을 발견하여 그 장소에 창건되었으며 대한불교 태고종 소속 사찰이다. 龍華寺 石造 如來立像은 묻혀 있던 다리 부분을 드러내고 대좌를 새로 조성하여 그 위에 봉안하고 있다. 얼굴부분은 마모가 심하나 다른 부분은 보존이 양호한 편이며 조각수법이 우수한 상이다. 하나의 돌덩어리에 주형(舟形)의 광배를 만들고 그 앞에 불상을 양각하였다. 광배의 뒷면은 특별한 장식이나 조각 없이 거칠고 둥글게 다듬어 놓기만 한 상태이다. 광배의 두광과 신광의 가장자리, 불상의 머리 부분이 약간 파손되었다.","a":"충주 용화사 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638953.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398) 서정리에 처음 지었으며, 숙종 39년(1713)에 덕성리로 옮겨 짓는 작업을 시작하여 숙종 42년(1716)에 완공하였다. 그 뒤 헌종 9년(1843)과 1923년 두 차례 보수를 하였다. 현재 남아 있는 건물로는 대성전·명륜당·동재·천화루·신문(내삼문) 등이다. 제사를 지내는 공간인 대성전은 6칸의 규모이며, 안쪽에는 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 있다.","a":"청하향교","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663151.jpg"},{"q":"서산 정씨 시조인 정신보의 학문과 덕행을 기리기 위해 세운 서원이다. 정신보는 원래 중국 송나라 사람으로 나라가 망하자, 고려로 망명한 후 서산에 정착하여 살았다. 숙종 20년(1694)에 세운 후 흥선대원군의 서원철폐령으로 고종 8년(1871)에 해체되었다가 1910년 유양목 등 유림이 복원하였다. 경내에는 선현의 제사를 지내는 사당과 기숙사인 동재·서재, 출입문 등이 있다. 사당은 정신보와 추가로 모신 8분의 유학자(정인경·유방택·윤황·유백유·유박순·유윤·김적·김위재)를 포함하여 총 9명의 위패를 모시고 있다.","a":"송곡서원","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661255.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. ○○○ 탑골마을에 서 있는 이 부도는 주위에 별다른 절터의 흔적을 찾을 수 없어 원래의 자리인지 다른 곳에서 옮겨온 것인지는 알 수가 없다. 맨 아래의 바닥돌은 보이지 않고, 그 위의 기단(基壇)부터 모습을 드러내고 있다. 1층으로 마련된 기단은 네 모서리마다 기둥모양을 본떠 새겼다. 윗돌을 괴어주는 가장자리에는 얕게 연꽃을 조각하여 장식하였다. 2층을 이루는 탑신(塔身)은 몸돌과 지붕돌이 각각 하나의 돌로 이루어져 있다. 몸돌은 기단에서처럼 모서리마다 기둥모양을 조각해 두었다.","a":"부여 현내리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639032.jpg"},{"q":"불상 좌대는 15개의 못으로 돌아가며 고정해 당시 좌대의 고정기법을 확인할 수 있다. 또한 좌대 밑면에는 주서로 제작연대 및 원래의 봉안사찰, 시주자, 제작자 등을 기록해 두었는데 시주자나 화원의 이름 중 일부가 박락되어 있다. 높이 30cm의 소형 ○○상이며, 방형의 얼굴에 민머리를 한 지장보살상이다. 신체에 비해 머리가 큰 조선후기 불상의 특징을 따르고 있으며, 전체적으로 균형 잡힌 비례를 보이지만 어깨가 다소 빈약하고 무릎이 높은 편이며, 상의 규모에 비해 두 손이 크게 조성되었다.","a":"합천 해인사 희랑대 목조 지장보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643123.jpg"},{"q":"조선 후기 동학농민군이 관군과 싸웠던 ○○○이다. 고종 31년(1894) 교조신원운동의 실패와 전라도 고부군수 조병갑의 포악한 정치가 원인이 되어, 동학접주인 전봉준이 나라 일을 돕고 백성을 편안하게 하게 하자는 내용으로 동학농민운동을 일으켰다. 당시 홍천 지방에서도 농민 운동이 크게 일어나 농민군의 일부가 관아를 공격하고자 산에서 내려와 장야촌까지 진군하였으나, 관군 총사령관 맹영재와 싸워 동학군 30여 명이 전사하였다.","a":"홍천풍암리동학혁명군전적지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647833.jpg"},{"q":"소나무 숲이 울창한 야산을 뒤로 하고 있는 이 집은 경주 이씨의 종가로 약 200년 전에 지어진 것으로 보인다. 강원특별자치도의 전형적인 온돌 중심의 겹집에 마루가 도입된 민가이다. 앞면 4칸·옆면 2칸의 본채를 기본으로, 왼쪽 앞으로 외양간을 1칸·뒷쪽으로 방과 창고를 1칸씩 덧붙여 T자 모양을 이루고 있다. 본채는 지붕 옆 모습이 여덟 팔(八)자 모양의 화려한 팔작지붕집으로, 오른쪽 3칸은 방을 겹쳐서 배치하였고 왼쪽 1칸은 부엌을 두었다. 부엌과 연결된 외양간의 윗부분을 수납공간으로 활용하며, 부엌과 연결된 방으로의 출입은 밖에서만 할 수 있도록 되어있다.","a":"양양이두형가옥","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638093.jpg"},{"q":"야은 길재의 충절을 기리기 위해 세운 서원이다. 길재(1353∼1419)는 정몽주·이색과 함께 고려 후기에 절의를 지킨 ‘고려삼은(三隱)’으로 불리는 학자이다. 그는 과거에 합격하여 벼슬길에 올랐으나 고려가 망하는 것을 알고 두 왕조를 섬길 수 없다하여 관직을 버리고 고향에 은거하였다. 조선이 건국되고 세자 이방원(태종)이 관직에 임명하였으나 거절하고 학문과 후학양성에만 전념했다. ○○○○은 선조 3년(1570)에 금오산 자락에 세웠으며 선조 8년(1575) 임금으로부터 이름을 받아 사액서원이 되었다.","a":"금오서원","c":"시도기념물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654493.jpg"},{"q":"○○○은 영천이씨 하연공파 이중량(자 공간, 호 하연, 연산 10년(1504)～ 선조 15년(1582))의 종택이고, 그의 父는 농암 이현보이다. 이 건물은 인량마을의 좌측의 뒤편에 남향으로 자리잡고 있다. 배치는 사당과 우측에 ‘ㅁ’자형 본체 일렬로 나열되어 있다. 규모는 정면 5칸 측면 5칸반이고, 중문간 좌측에 정면 3칸 측면 3칸의 사랑채가 위치하고 있다. ○○○의 주요 특징은 본체 대청의 배면 창호에 가운데설주 홈 자국과 몸체 우측 익랑의 문얼굴에서도 고식의 특징이 잘 남아 있어 조선중기의 건물 구성요소들이 잘 갖추고 있다.","a":"영덕 삼벽당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018101609312000.JPG"},{"q":"고려 말~조선 초의 문신이자 조선의 개국 공신인 ○○○ 선생의 묘역이다. 이성계(李成桂)의 조선 개국을 도와 개국원종공신(開國原從功臣)이 되었다. ○○○의 묘는 전주 최씨 가족 묘역 안에 위치하는데, 맨 위로부터 ○○○, 아들 최사강(崔士康), 8세손 최노첨(崔魯瞻) 묘역이 있고, 주변 능선에도 아들인 최사위(崔士威), 최사규(崔士規) 묘역들이 위치하고 있다. ○○○ 묘역은 부인 고성이씨(固城李氏)와 함께 매장된 쌍분(雙墳 ; 두개의 봉분)의 형태이고, 최근에 상락군부인 김씨(上洛郡夫人金氏) 묘를 합장하였다고 한다.","a":"죽정최유경묘역","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660245.jpg"},{"q":"고려의 개국공신인 신숭겸의 무덤 남쪽에 있는 2기의 무덤이다. 내부는 크고 작은 깬돌을 포개서 만든 돌방무덤(석실묘)이고, 외부의 봉토는 거의 유실되었다. 천장은 3∼4단의 벽을 쌓아 올리면서 모서리를 죽이고 하나의 큰 판돌을 올려 마무리한 모줄임식천장(말각조정천장)이다. ○○○ 무덤은 ○○○ 무덤의 후기 양식이 지방화 된 형태로, 춘천 지방이 신라가 북상하기 이전인 6세기 중엽에는 ○○○ 영역이었음을 보여주는 중요한 유적이다.","a":"방동리고구려고분","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660531.jpg"},{"q":"○○○는 1926년 신상·신항·신건 등 3명이 협력해서 세운 사당이다. 고려의 개국공신인 신숭겸과 그의 후손이자 고려 후기 학자인 신현, 성리학자인 이색, 그리고 벼슬을 탐하지 않고 학문에 전념했던 선비 원천석에게 제사를 지내는 곳이다. 사당 안에는 신숭겸의 영정을 모시고 있고, 해마다 3월에 평산 신씨 문중과 지방의 유학자들이 제사를 지낸다.","a":"사천 경백사","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664425.jpg"},{"q":"○○○ 대웅전에 보관되어 있는 ○○○○ 및 ○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. ○○○○는 세마포(細麻布)에 종이를 여러 겹으로 배접한 바탕 위에 중앙의 아미타불을 중심으로 좌우협시보살만을 배치한 아미타삼존도이다. 남색 하늘 바탕에 갈색과 녹색 구름을 그렸고, 부처와 보살상을 홍색과 녹색 위주로 그려 다소 무거운 느낌을 주지만 세련된 필치를 보이고 있다. 그림의 아랫부분에 적힌 화기(畵記)에 따르면 이 ○○○○는 조선 영조 26년(1750)에 화원(畵員) 보총(普摠)·처일(處一) 등에 의해 조성되었다고 한다.","a":"은해사극락보전후불탱화및삼장탱화","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641090.jpg"},{"q":"○○은 왕실에 왕자나 공주가 태어났을 때 그 태를 모시는 곳으로, 이곳은 조선 ○○대왕의 태를 모시고 있었다. 대개는 태항아리 안에만 두는 것이 보통이나, 왕세자나 왕세손 등 왕위를 이어받을 사람의 태는 따로 돌방을 만들어 그 안에 넣어두게 한다. 이 ○○은 8각의 낮은 받침돌 위로 둥근 돌방을 올리고 8각 지붕돌을 얹은 모습으로, ○○이 왕위에 오르자 그 옆에 ○○비를 세워 놓았다. 영조 2년(1726) 왕의 명을 받아 ○○ 주위에 8각형 돌난간을 두르고 비석을 세웠으며, 순호군 16명을 두고 3년마다 제사를 올렸다.","a":"충주 경종 태실","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638401.jpg"},{"q":"청양 ○○○ 가옥는 안채·사랑채(큰 사랑채)·별채(작은 사랑채)·행랑채·곳간 등으로 구성된 조선 후기에서 1900년 초에 건축된 고택이다. 그 중 정면 5칸·측면 3칸에 전면으로 한칸 덧달아 낸 사랑채(큰사랑채)는 ○○○의 고조부가 지었다. 그리고 정면 9칸·측면 3칸의 안채와 정면 5칸·측면 3칸에 4면으로 반칸씩의 퇴를 돌린 별채(작은 사랑채)는 ○○○의 부친인 윤갑선이 1937년에 지은 것으로 알려지고 있다. 특히 2층으로 건립한 별채는 우리나라 전통양식과 일본식이 절충된 건축기법을 보여주는 특이한 건물이다.","a":"청양윤남석가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658272.jpg"},{"q":"고려시대 문인이자 유학자인 안향(1243∼1306)의 시문집『회헌실기』를 간행하기 위한 목판으로, 영조 42년(1766) 죽계서원에서 간행한 초간본 목판 55매와 고종 22년(1845)에 간행한 중간본 목판 32매 등 총 87매이다. 안향은 원종 1년(1260) 문과에 급제하여 교서랑, 감찰어사, 좌승지 등의 벼슬을 지냈다. 그는 여러 차례에 걸쳐 원나라를 다녀오면서 주자학의 학풍을 보고, 주자 관련 서적을 베껴오고, 주자학을 우리나라에 보급하기 위하여 많은 노력을 하였다. 안향은 우리나라 최초의 주자학자라고 할 수 있다.","a":"곡성 도동묘 회헌실기목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018050814105600.jpg"},{"q":"○○의 주인공은 ○○○○ 거제 현령 하계지(河繼支)의 아내이며, 지평 운수당 하윤(河潤)의 어머니입니다. ○○는 조선 중기에 축조된 것으로 비문의 찬자는 강백진(康伯珍, 1449-1504)입니다. 좌대와 비신과 가첨석이 하나의 돌로 되어 있는 것이 특징이며, 부인의 ○○로서는 유례가 드물게 그 크기가 크고 원형이 비교적 잘 보존되어 있습니다. ○○○ 또한 희귀한 형태를 띠고 있으므로 ○○와 ○○○을 경상남도 유형문화유산으로 지정하고자 합니다.","a":"진주 가봉리 숙부인 상산박씨 묘비 및 석인상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023063021402100.JPG"},{"q":"밀양 박씨의 옛집으로 대대로 진사와 효자가 태어났으며 조선시대 사대부 가옥의 형태를 잘 갖추고 있다. 이 집에서 효자 박효근이 출생하였고, 그의 아들 박한회와 손자가 진사를 지냈다. 조선 후기에 지어져 일제시대에 대규모로 고쳐 지은 이 가옥은 안채와 사랑채 2동, 곡간채 2동, 대문간채로 구성되어 있으며 담장이 잘 보존되어 있다. 대문에는 효자정려 현판이 붙어 있다. 앞면 5칸·옆면 2칸의 안채는 부엌, 방, 대청, 갓방으로 구성되어 있다. 안채를 중심으로 동쪽에 담장을 둘러 별당처럼 안사랑채를 배치하였고 중문간채를 바깥사랑채로 이용하였다.","a":"고성 박진사 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664703.jpg"},{"q":"성북동 산뜸 마을 동북쪽 산중턱에 있는 봉덕사(옛이름 봉소사) 안에 서 있는 ○○○○상이다. 신체에 비하여 너무 큰 머리에는 높은 보관(寶冠)을 쓰고 있는데, 보관의 양 옆에는 장신구를 매달았던 듯한 구멍이 있으며, 귀에는 귀걸이를 길게 내려 뜨리고 화려한 장엄구를 달았다. 천의(天衣)는 왼쪽 어깨를 감싸 흘러내리고 있으며, 오른손은 곧게 아래로 내려 손바닥이 앞(밖)을 향하도록 하고, 왼손은 가슴께로 올리고 있는데 무엇인가를 잡고있는 듯 하나 마멸이 심하여 알 수 없다. 양 손목에는 팔찌를 끼고 있다.","a":"석조보살입상","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637183.jpg"},{"q":"○○○는 원나라 승려인 원명이 세웠다는 기록과, 신라 성덕왕 24년(725)에 서역 금지국의 승려인 정명이 세우고 남송 임천사의 승려 원명이 고쳐 세웠다는 기록이 있지만 지은 시기를 정확하게 밝히기는 어렵다. ○○○의 부속 암자인 ○○○은 원나라 승려인 원명이 지었다고 한다. 현재 ○○○ 내에는 법당, 요사채, 축성각이 있다. 법당 내부에는 목조아미타불삼존불이 있고 그 앞에 숙종 7년(1681)에 만든 석등이 있으며 ○○○ 입구에는 조선 후기에 만든 부도 5기가 있다.","a":"법천사 목우암","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662020.jpg"},{"q":"홍산초등학교 북쪽에 있는 표고 90m의 산 꼭대기에 만들어진 산성으로, 성 안에 있는 체육공원의 진입로에 의해 성벽의 서쪽부분이 일부분 잘려나갔다. 잘려진 면으로 보아 성벽의 기단에만 돌을 가지런히 깔고, 그 내부와 윗부분은 모두 흙을 쌓아올린 듯 한데, 현재 성벽의 윤곽은 뚜렷하지 않다. 성안에서는 민무늬토기조각, 삿무늬 토기조각, 백제 토기조각, 기와조각 등 여러 시대에 걸치는 유물들이 발견되고 있는데, 백제 토기들을 통해 볼 때 본격적으로 성의 기능을 한 때는 백제 사비천도 이후일 가능성이 높다.","a":"홍산태봉산성","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051414092400.jpg"},{"q":"○○○ 장군이 태어난 곳이다. 평민출신의 의병장으로는 가장 먼저 군사를 모아 막강한 의병세력으로 성장하여 1896∼1908년 영덕, 영양, 울진 등의 여러 전투에서 일본군을 섬멸하여 독립의병사에 길이 남을 혁혁한 전공을 세웠다. 원래 있던 생가는 일본 관헌들이 우리 민족의 독립의지를 꺾기 위한 정략적 차원에서 불에 태워 없앴고, 지금 있는 집은 1995년 복원한 것이다. 앞면 4칸·옆면 1칸 규모의 一자형 건물로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"신돌석장군생가지","c":"시도기념물","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654542.jpg"},{"q":"김용사는 운달조사가 신라 진평왕 10년(588)에 세웠다고 전하나, 사적기에 따르면 세운 시기에 대한 기록이 없다. 조선 인조 21년(1643) 화재로 소실되었다가 인조 27년(1649) 새로 복원하여 현재까지 이어진다. ○○○은 17세기에 지은 것으로 보이는데 앞면 3칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. ○○○ 건축 양식상 특이한 것은 건물의 기단 위를 평평하게 다듬지 않고 기둥을 세워 높이가 일정하지 않다.","a":"문경 김룡사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641264.jpg"},{"q":"효자인 ○○○ 선생의 부모에 대한 효행을 곤양, 하동지역의 선비 30명이 모여 표창하고 이를 기록한 내용과 돌아온 답서(答書:답장)들이다. ○○○ 선생은 조선 순조∼고종 때의 사람으로, 그의 나이 12∼13세 때 아버지인 추민중의 병이 위독하자 허벅지 살을 베어 먹였고, 모친 황씨가 병이 심할 때에는 단지(斷指:부모나 남편의 위급한 병을 낫게 하려고 피를 내어 먹이기 위하여 손가락 끝을 자르던 일)를 할 정도로 효성이 지극하였다.","a":"추성원효행상서문","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664451.jpg"},{"q":"이 영정은 ○○○○○선사의 8분 좌안면 바닥가부좌상으로, 패턴화된 의자형상을 배경삼아 왼손엔 주장자를 오른손엔 염주를 쥔 채 돗자리위에 앉아 있다. 한편 이 작품은 화면 향좌측 ‘선교양종대각등계국일도대선사주관○○○○○대선사지진(禪敎兩宗大覺登階國一都大禪師主管性月堂弘震大禪師之眞)’의 화제와 배면의 묵서화기로 1859년 조성 봉안되었음을 알 수 있다. 화면크기는 가로78.6cm, 세로 120.5cm이다.","a":"성월당 홍진 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643000.JPG"},{"q":"경상북도 김천시 봉산면 ○○○ 길가에 서 있는 이 석불은 무릎 아랫부분은 땅에 묻혀 있어 전체 형태를 확인할 수 없다. 머리에는 상투 모양의 머리묶음이 솟아 있고, 긴 머리카락이 어깨 위에까지 드리워져 있다. 파손이 심한 둥근 얼굴은 살이 올라 통통한 편이며, 양 어깨를 감싼 부드러운 옷은 길게 드리워져 있다. 마을에서는 지혜의 보살인 문수보살이라 하는데, 불공을 드리면 득남한다는 소문이 있어 근래에까지 촛불을 켜고 기도하는 사람이 있다고 한다. 조성양식이 특이하고 조각기법이 우수한 불상으로 고려 전기에 만들어진 것으로 추정된다.","a":"금릉태화리석조보살입상","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663057.jpg"},{"q":"조선 제 14대 임금인 선조(재위 1567∼1608)의 태함(태를 묻는 돌로 만든 함)을 만든 후 이를 기념하기 위해 세운 비이다. 형태는 거북받침돌 위에 비몸을 세우고 머릿돌을 얹은 모습이다. 앞면에는 ‘○○○○○’이라고 새겨 모셔 놓은 태의 주인공을 밝히고 있고, 뒷면에는 비를 세운 시기를 적어 놓았다. 선조 3년(1570)에 처음 건립되었으나, 세월이 지나면서 글씨가 많이 닳아 있어 영조 23년(1747)에 다시 세워 놓은 비이다.","a":"선조대왕태실비","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661087.jpg"},{"q":"조선 초기 개국공신이자 청백리의 한 사람인 하정(夏亭) 유관(柳寬, 1346∼1433) 선생의 묘이다. 묘역은 부인 광주 안씨(廣州安氏)와 함께 매장된 쌍분(雙墳; 두개의 봉분)의 형태이다. 봉분은 아래 부분에 사각형의 둘레석을 조성하였는데 고려말~조선 초기의 특징이다. 봉분의 옆에는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)의 옛 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)가 있다. 처음 묘역을 조성할 당시의 옛 석물로는 석인 1쌍이 있다.","a":"유관선생묘","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646136.jpg"},{"q":"경상북도 영주시 순흥면 ○○○에 있는 불상으로, 머리가 없어지고 손은 손상을 입은 상태이다. 넓은 어깨와 양감있는 신체에서는 강건함과 탄력성이 느껴진다. 오른손은 아래로 내려 손바닥이 정면을 향하게 하고 왼손은 팔이 잘려나갔다. 양 어깨를 가리며 입은 옷은 배까지 U자형의 주름을 만들며 흐르다가 양 다리에서는 2개의 동심타원형으로 이어진다. 이런 표현은 영주석교○○○○○ 등 통일신라시대 작품에서 흔히 볼 수 있는 특징이다. 왼팔을 돌아 내려간 옷자락은 입체감과 유연함이 있어 훌륭한 조각솜씨를 나타내고 있다.","a":"영주읍내리석불입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640483.jpg"},{"q":"척화비란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하고자 서울 및 전국의 중요 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 아주 낮고 자그마한 받침돌 위로 비몸을 세우고, 반달 모양의 머릿돌을 올린 모습으로, 비몸 앞면에 비문을 새겨두었다. 고종 8년(1871) 전국에 동시에 세운 비로, 한·일합방이 되면서 일제에 의해 대부분의 척화비들은 철거되거나 훼손되었는데, 이 비는 본래의 모습으로 넘어져 있어 바로 세워 놓았다.","a":"함양척화비","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664557.jpg"},{"q":"화순 ○○○○○은 도곡면 죽청리1구 하죽청 마을 중앙부에 소재한 가옥으로 조선시대 후기(1775년경)에 지은 ＇ㄷ＇자형 집이다. 화순 도곡면 죽청리는 옛부터 ＂비봉포란(飛鳳包卵)＂의 형국이라 하여 명당으로 알려져 오고 있으며, 마을 앞으로는 지석강이 흐르고 있어 마을 터는 배산임수의 터자리임을 알 수 있다. 원래 이 가옥은 허장자(부자)라는 사람과 양씨가 안고랑(현 죽청2구 마을)에서 살았었는데, 그 집을 광산이씨가 옮겨 온 것이라 한다.","a":"화순이경휴가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658418.jpg"},{"q":"○○○터 입구에서 400∼500m 지점에 자리하고 있는 2기의 돌장승으로, 사찰내의 살생과 수렵을 금하게 하고, 사찰의 재산이나 경계를 표시하는 구실을 하였던 것으로 보인다. 자연석인 화강암을 잘 다듬지 않은 채 얼굴만을 조각하였고, 몸체에는 각각 ‘당장군’,‘주장군’이라 새겨 놓았다. 당장군은 높이 247㎝, 둘레 175㎝이고, 주장군은 높이 345㎝, 둘레 210㎝로 되어있다.","a":"쌍계사지장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658373.jpg"},{"q":"1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습의 석탑이다. 기단과 탑신부의 각 층 몸돌에는 기둥모양을 새겼고, 특히 탑신의 1층 몸돌 네 면에는 약사여래, 아미타여래, 대일여래, 석가여래상 등의 불상을 조각하였다. 지붕돌은 밑면에 4단의 받침을 두었고, 윗면의 경사가 비교적 급하다.","a":"괴산 삼방리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638680.jpg"},{"q":"1874년 제작된 이 작품은 조선후기 불화에서 근대불화로 전환되는 과도기적인 작품이다. 모두 11존으로 구성되어 있으며 ○○○불을 중심으로 관음보살과 대세지보살이 좌우에 배치되어 있다. 문수보살과 보현동자가 그 앞에 배치되어 반원형 구도를 이루고 있으며, 뒤로는 6명의 나한들이 그려져 있다. 전면의 5존이 조선후기불화의 전통을 따르고 있는데 반해 나한상 6위는 근대불화의 성격을 엿볼 수 있다.","a":"안적사아미타극락회상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659378.jpg"},{"q":"경상북도 김천시 어모면 ○○○ 문암사 극락전에 모셔져 있는 아○○○○○이다. 원래는 마을 뒤에 방치되어 있던 것을 도현(道玄) 스님이 사찰을 세워 극락전에 안치하였다. 하나의 돌에 불상과 광배(光背)를 함께 조각하였는데, 전체적으로 불상이 기울어져 있고 아래부분은 시멘트에 묻혀 있어 형태를 알 수 없다. 손모양은 오른손은 아랫배에 내려져 있고, 왼손은 별도의 돌로 끼우게 되었으나 지금은 없어졌다. 전체적으로 많이 닳아 세부 표현을 자세히 확인할 수 없으나 통일신라 시대에 만들어진 것으로 추정된다.","a":"금릉옥률리석조아미타여래입상","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663121.jpg"},{"q":"차령산맥과 덕숭산이 바라보이고 넓은 평야가 눈아래 있으며 야트막한 산으로 감싸있는 마을에 있는 이 건물은 1919년에 지은 것으로 ‘위례장’이라고도 부른다. 건물 구조는 ㄱ자형 안채와 ㅡ자형 사랑채로 전체 구성은 ㄷ자형을 이루고 있으며 면천 관아 건물을 부재로 사용하였다고 한다. ㄱ자형 안채는 중앙 대청마루를 중심으로 안방과 윗방 왼쪽에는 건넌방을 두었으며 안방 전면에는 2칸 부엌이 있다. 一자형 사랑채의 평면은 오른쪽부터 툇마루·사랑대청·사랑방·중방·광이 있다.","a":"당진한갑동가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661453.jpg"},{"q":"○○○○○은 성종 21년(1490)에 쌓은 성으로서 조선시대 전기 경상우수영 성으로 사용하였으며 ○○ 7진 중의 하나이다. 이 지역은 한산도를 중앙에 두고 통영과 ○○로 갈라지는 두 갈래 바닷길 중 ○○로 향하는 길목에 위치하여 전략적으로 매우 중요한 곳으로, 세종 7년(1425)부터 선조24년(1601)까지 경상우수영 및 삼도수군통제영으로 이용되어 역사적인 의미가 큰 곳이다. 선조 16년(1593) 임진왜란 당시 이순신 장군이 삼도수군통제사에 제수된 후 한산도에 삼도수군통제영 본영을 구축하고 이곳에는 기존보다 큰 규모로 연장 개축했다는 기록이 있다.","a":"거제 가배량진성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655507.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○○○는 일운면 와현리 및 구조라리에 있는 해발 303m의 망산 옆에 위치한 ○○○로서 지세포성과는 약 5㎞이내에 자리잡고 있다. 현재의 상태를 보면 산 정상부의 지면을 조정한 후 2단으로 석축하여 올린 것처럼 되어 있으나 아래의 석축은 방호벽으로 쌓은 것으로 보이고, 그 위의 석축은 봉화부가 붕괴된 상태로 추정된다.","a":"거제 와현봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657118.jpg"},{"q":"조선 중종 때 학자 이굉이 중종 25년(1530)경에 세운 정자이다. 이굉은 성종 11년(1480) 문과에 급제하였으며 1500년 집의를 거쳐 개성부 유수가 되었다. 연산군 10년(1504)에는 갑자사화로 관직을 삭탈당하였으나 1506년 중종반정으로 다시 기용되었다. 그 뒤 벼슬을 그만두고 안동에 내려와 이 집을 짓고 학문과 자연을 즐겼다. 당시 안동 선비들과 숙식자가 많아져 건물을 늘려 짓고, 학문을 익히고 연구하는 기관으로 조성하게 되었다. 1945년 화재로 불타버린 것을 1946년에 고쳐 세웠다.","a":"반구정재사","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662974.jpg"},{"q":"이 비는 완공된 이섭교를 기념하기 위하여 세운 비석이다. 이섭교는 지금은 없어졌으나, 1694년(숙종 20)에 지금의 동래구 낙민동, 안락동에서 연산1동으로 건너갈 때 건너야 하는 온천천에 놓여 있던 3개의 무지개 모양의 홍예(虹霓)를 아치식으로 연결한 돌다리였다.","a":"이섭교비","c":"시도기념물","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2666161.jpg"},{"q":"○○○ 장군의 전공을 기록해 놓은 비로, 일명 ‘진주전성각적비(晉州全城却敵碑)’라고도 불리우며, 현재 진주성내에 비각을 마련하여 모시고 있다. ○○○ 장군은 조선 중기의 무신으로, 임진왜란 당시 진주목사로 있으면서 임진왜란의 3대첩 중 하나인 진주성 싸움을 승리로 이끌었다. 비문에는 1천명도 안되는 병력으로 10만의 군대를 물리쳤다고 하나, 다른 기록에는 3,800여명의 병력이 왜군 2만여명을 맞아 치열한 전투 끝에 물리치고 진주성을 지킨 것으로 되어 있다.","a":"김시민 전공비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641327.jpg"},{"q":"1604년(선조 37) 오리 ○○○이 아내 영일정씨(迎日鄭氏)의 죽음을 애도하는 만시(輓詩)이다. 이 만시는 만장(輓章)에 쓴 것으로, 장사를 지낸 후 내용은 베껴 보관하고 태우는 것이 관례이나 ○○○이 손수 쓴 것이라 특별한 의미가 있다고 생각하여 보존해온 것으로 보인다. 이것은 따로 제목은 없었으나 ○○○의 문집 『오리집(梧里集)』 보유편에 「도망(悼亡)」이라는 제목으로 수록되어 있다.","a":"이원익도망시","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637802.jpg"},{"q":"조선 숙종 때의 문신이자 학자인 노봉 민정중(1628∼1692)의 시문집을 새긴 목판이다. 정조 8년(1784)에 판을 새겼으며, 298매가 남아 있다. 민정중은 송시열의 문인으로, 효종 즉위년(1649)에 문과에 장원으로 급제하여 성균관전적, 예조좌랑, 홍문관수찬와 각 도의 암행어사의 벼슬을 지냈다. 그후 성균관대사성, 이조참판, 우의정, 좌의정 등을 지내고 1689년 기사환국으로 남인이 집권하자 노론의 여러 사람들과 함께 벼슬을 빼앗기고 벽동에 유배되어 그곳에서 죽었다. 그가 죽은 후 그의 위패가 여러 서원에 모셔졌으며, 시호는 ‘문충’이다.","a":"장흥연곡서원노봉선생문집목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814481200.jpg"},{"q":"석계 이시명(1590∼1674)이 네 아들과 함께 생활하던 곳이다. 이시명은 조선 후기 학자로 소과에 합격하였으나 국정이 혼란스러워 벼슬길을 포기하고 은거하면서 후진양성에 주력하였다. 이곳은 네 아들과 은거생활을 하며 지은 석계 초당이 있던 곳으로, 순조 31년(1831)에 후손들이 지금의 서당을 지었으며 고종 28년(1891)에 고쳐 지어 오늘에 이르고 있다. 서당고에는 『석계선생운집』, 『항재선생운집』, 『영천집』등 목판을 소장하고 있다.","a":"석천서당","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662518.jpg"},{"q":"연곡 면사무소의 서남쪽 산봉우리에 있는 신라의 무덤이다. 뚜껑돌의 일부가 파손되었지만 비교적 보존상태가 좋은 편이다. 무덤의 구조는 정확한 학술조사가 없어 확실히 알 수 없으나, 주변에 남아있는 무덤 유적과 비교해 볼 때 4면을 돌로 벽을 쌓고 뚜껑돌을 덮은 돌방무덤(석실분)으로 생각된다. 주변에서는 굽다리접시(고배), 둥근바닥긴목항아리(원저장경호), 둥근바닥항아리(원저단경호) 등의 전형적인 신라 토기 조각이 수습되었다.","a":"연곡고분","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660428.jpg"},{"q":"‘가평 ○○○○○’은 현등사 삼층석탑 아래 별도의 공간에 있다. 현등사는 고려 희종 때 보조국사가 이곳을 지나다가 석등 불빛을 보고 폐허로 있던 절터에 사찰을 중창했는데, 이때 땅의 기운을 진정시키고자 탑을 세웠다고 전한다. 이러한 연유로 인해 ○○○으로 불렸고, 보조국사의 이름을 따 보조국사탑(普照國師塔)으로 부르기도 한다. ○○○은 원래 3층 석탑이었을 것으로 보이나, 기단(基壇) 일부와 탑신(塔身)의 1층 부재가 없어져 본래의 모습과 달라졌다. 가장 하단에 있는 지대석에는 2단의 괴임대가 마련되었고, 네 귀퉁이의 합각(合角)이 뚜렷하다.","a":"가평하판리지진탑","c":"문화유산자료","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2236385.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안 8분면 바닥가부좌상으로, 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 등받이와 팔걸이가 있는 의자를 배치하고 왼손엔 주장자를, 오른손엔 염주를 쥐고 측면을 바라보며 앉아 있는 모습이다. 의자에는 연부에 연화당초문양이 그려진 녹색 법피를 드리우고 있다. 화면 향좌측엔 주지묵서의 ‘선교양종대각등계팔도총섭○○○○○지진(禪敎兩宗大覺登階八道總攝東溟堂萬羽之眞)'화제가, 향우측엔 주지묵서의 영찬(影贊)이 있다. 화면 크기는 가로 78.5cm, 세로 120.2cm이다.","a":"동명당 만우 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643012.JPG"},{"q":"증심사는 철감선사 도윤이 신라 헌안왕 4년(860)에 세운 절로 송광사에 딸린 절이다. 증심사 입구에서 약사 계곡을 따라 새인봉 쪽으로 오르다보면 비교적 규모를 갖춘 ○○○이 모습을 드러낸다. ○○○은 증심사의 부속 암자로 철감선사 도윤이 증심사를 세우기 직전인 850년경 ‘인왕사(人王寺) ’라는 이름으로 지었고, 고려 충렬왕 32년(1306)년 절을 고쳐 세우면서 ‘○○○ ’으로 이름을 바꾸었다. 한국전쟁으로 소실된 것을 1974∼1984년에 복원하여 오늘에 이르고 있다. 경내의 건물로는 대웅전, 운림당, 운림선원, 강원(講院) 등이 있다.","a":"약사암","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659594.jpg"},{"q":"용방이란 문과를 달리 이르는 말로 이 책은 조선시대 문과에 합격한 사람의 이름을 적은 명부이다. 책에 나온 급제자로는 조선조 태종 14년(1414) 갑오방에 급제한 고득종으로부터 철종 14년(1863) 계해방에 급제한 한석윤까지 총 56인이 기록되어 있다. 큰 글자로 쓴 이름자 밑에는 작은 글씨로 본인의 자(字)와 생년간지가 쓰여 있으며, 다시 그 밑에 급제 당시의 왕의 시호와 후손의 이름이 쓰여져 있다.","a":"용방록","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643284.jpg"},{"q":"장흥 ○○○○○은 대좌부분이 떨어져나갔지만 불신과 대좌가 같은 개체임이 금속성분 분석 결과 확인된 것이다. 불상의 외모상에서 나타난 양식의 특징 또한 7세기경 삼국시대의 전통적인 양식을 계승한 것으로 계란형의 얼굴과 사발형의 육계, 행인형의 눈두덩, 길게 내려온 U자형 대의주름, 7~8세기경 유행한 시무외, 여원인의 수인 등이 모두 고졸한 양식임을 알 수 있다. 더구나 금동불상 대좌 하단의 평면이 7각인 점도 주목된다.","a":"장흥탑산사지금동여래입상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020031017225200.jpg"},{"q":"『○○○○』으로 현재까지 알려진 것 중 가장 오래된 것은 조선 제8대 예종 원년(1469)에 갑인자(甲寅字)로 찍어낸 것이다. 이 갑인자본은 지금 전해지지 않는다. 그 다음으로 오래된 것이 을해자활자본(乙亥字活字本)으로 찍어낸 이 방목이다. 이 책과 동일한 『○○○○○』은 현재 옥산서원(玉山書院)에 소장되어 있는데 보물 제524호로 지정되어 있고, 그 해에 발행한 『○○○○문무잡과방목(正德癸酉文武雜科榜目)』은 강릉의 심교만 씨가 소장하고 있는데 역시 보물 제603호로 지정되어 있다.","a":"정덕계유 사마방목","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642414.jpg"},{"q":"시인이며 국문학자인 조지훈(1920∼1968) 선생이 태어난 곳이다. 조지훈은 경상북도 영양 출신으로 본명은 동탁(東卓)이다. 선생은 박목월·박두진과 공동으로 간행한 청록집의 시편들에서 주로 민족사의 맥락과 고전미 세계에 대한 찬양과 선(禪)세계를 노래하였는데, 유교 도덕주의의 격조높은 자연 인식을 보인다는 점에서 시문학사적 의의가 있다고 평가 받고 있다. 가옥은 몸체와 관리사로 나뉘어 있으며 몸체는 앞면 7칸·옆면 7칸 규모에 ㅁ자형 평면을 갖추고 있다.","a":"조지훈생가","c":"시도기념물","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654528.jpg"},{"q":"본 작품은 1896년에 조성된 세로 206.5cm, 가로 199.5cm로 비교적 큰 작품으로, 동호(東昊)·진철(震徹)이 제작에 관여하였음을 화기를 통해 알 수 있다. 현존 상태가 비교적 양호하지 못하나 19세기 ○○○○도상 연구에 그 자료적 가치가 있다.","a":"통도사취운암지장시왕탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665242.jpg"},{"q":"조선 후기의 무신인 ○○○ 선생의 옛 가옥에 남아있는 유물들로, 교지·정적·지도·초상화 등 총 4종 12점이다. ○○○은 영조 46년(1770) 무과에 급제하여 20여 년간 나라를 위하는 일념으로 정성을 다해 공직 생활을 하였으며, 압록강 연변일대와 영남해안 일대의 세밀한 전략지도를 만들어 전쟁에 대비하기도 하였다. 선생의 초상화는 정조 19년(1795) 그가 궁중에 들어갔을 때 왕이 궁중의 화공에게 명하여 그리게 한 것이다.","a":"수사공강응환가전유물","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639575.jpg"},{"q":"진성 이씨 시조 이석의 묘소를 돌보고 제사를 지내기 위해 세운 것으로, 임진왜란 때 화재로 없어진 것을 영조16년(1740)에 새로 지은 것이다. 앞면 5칸·옆면 5칸 규모의 건물로 ㅁ자형으로 되어 있으며 전면 아래층은 출입구를 두고, 위층은 비가 올 때 제사지내는 곳으로 활용할 수 있게 만들었다. 오른편 건물은 노년층들이 사용하는 상방이 있고 왼편 건물은 장년층이 사용하는 중방이 배치되어 공간을 기능에 따라 적절히 배치하였다.","a":"청송 기곡재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658933.jpg"},{"q":"조선 중기 문신인 정희 선생을 중앙에 모시고 좌우에 그의 아들 정초·손자 정수충과 정오도·민제장의 위패를 모시고 있는 사당이다. 처음에는 사경과 예법에 뛰어나고 청렴결백한 정수충의 영정을 모신 영당이였으나, 정조 8년(1784) 그의 위패를 함께 모시면서 사당의 격을 갖추었다. 정조 20년(1796)에는 ‘이인좌의 난’을 평정하는데 공을 세운 민제장을, 순조 6년(1809)에는 정몽주의 제자로 충절을 지킨 그의 할아버지인 정희와 세종 때 학문과 예술, 과학, 기술 등에 업적을 남기고 청렴했던 그의 아버지인 정초의 위패를 함께 모셨다.","a":"화담사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645761.jpg"},{"q":"이 불상은 ○○○에 봉안되어 있는 고려 후기의 ○○○○이다. 현재 상의 전체크기는 143cm 이지만 원래는 지금의 광배보다 긴 주형거신광배(舟形擧身光背)에 얕은 부조로 ○○○을 새긴 상이었을 것으로 추정된다. 이중 원으로 이루어진 두광(頭光)과 신광(身光)에는 초화문(草花紋)이 새겨져 있어 장식성을 느낄 수 있다. 머리 위에 동그랗게 새겨진 육계는 작은 편이며, 거의 원형에 가까운 둥근 머리에는 짧은 귀가 표현되었고 역시 아주 동그란 얼굴에 이목구비가 얕게 새겨져 있다.","a":"환희사 석불입상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593348.png"},{"q":"충청북도 ○○시 상당구 용정동에 있는 이 불상은 돌기둥을 이용하여 얼굴과 상체를 조각하여 석장승 같은 모습을 하고 있다. 이마에는 큼직한 원형의 백호(白毫)를 도드라지게 새겼고, 눈썹은 길고 커다랗게 표현하였다. 반달 모양을 한 입은 눈과 함께 얼굴 전체에서 미소를 띠게 한다. 손은 모아서 턱 밑에 괴고 있는데, 양 팔을 수평으로 처리하여 미숙한 조각수법을 보여주고 있다. 하체는 조각을 하지 않은 상태이며 중간부분에 순치(順治) 9년(효종 3년, 1652) 11월 16일에 만들었다는 글씨를 써 놓았다.","a":"청주 순치명 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638628.jpg"},{"q":"○○○○○은 조선중기의 다포계 건축이나 정면의 화려한 용두장식 등 여러 장식요소가 다분히 혼합되어 있는 등 조선후기의 건축양식을 잘 보여주고 있다. 그리고 중정식 가람배치의 전형을 보여 주며, 그 중심의 위치에 서서 주변 경관에 적극적으로 조화되는 이른바 산사의 모범적인 사례로 등장한다.","a":"해남 대흥사 대웅보전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640218.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○○○는 북제주 애월읍 하귀리 하귀초등학교 안에 북동방향으로 있으며, 덮개돌의 규모는 길이 2.43m, 너비 1.71m이다. 덮개돌은 5개의 납작한 받침돌이 주위를 돌아가며 받치고 있다.","a":"하귀지석묘 2호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657683.jpg"},{"q":"고려 때 장군인 강민첨(？∼1021)의 영정을 모시고 제사지내고 있는 사당이다. 장군은 목종 때 문과에 급제하고, 현종 3년(1012) 여진족이 쳐들어오자 영일, 청하 등지에서 이들을 격퇴하였다. 또한 현종 9년(1018) 거란의 소배압이 10만 대군을 이끌고 쳐들어오자 강감찬 장군의 부장으로 출전하여 적군을 대파하는데 큰 공을 세웠다. 이러한 공로로 현종 10년(1019) 응양상장군주국이 되고 이후 추성치리익대공신에 추대되었다. 이 사당의 경내에는 1910년 후세들이 세운 신도비가 있다.","a":"하동 두방재","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664002.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 효종(재위 1649∼1659) 때 세워진 것으로 그 뒤 한국전쟁 때 불탔으나 다시 지어 오늘에 이르고 있다. 건물은 출입문인 외삼문, 공부하는 곳인 명륜당과 동·서재, 사당인 대성전과 동·서무가 일렬로 서 있으며, 명륜당이 앞에 있고 대성전이 뒤에 있는 전형적인 전학후묘의 형태를 이루고 있다. 특이한 것은 대성전의 좌우에 동·서무가 나란히 서 있는데, 이것은 급경사지라는 지형의 제약 때문으로 보인다.","a":"함안향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641859.jpg"},{"q":"조선 전기의 문신인 ○○○ 선생의 묘 앞에 자리하고 있는 비이다. 국당 ○○○ 선생은 어려서부터 학문으로 이름이 높아 고려 우왕 13년(1386) 13세에 진사가 되었고, 17세인 공양왕 2년(1390)에 생원이 되었다. 이색의 추천으로 여흥부·춘천부의 교수로 벼슬을 시작하여 세종 5년(1423) 창평현감을 역임하였다. 조선 세종 7년(1424)에는 상을 당하여 3년간 묘곁을 지켰는데 그에 대한 표창으로 정려각이 세워지기도 하였다. 세조의 왕위찬탈에 반대하는 단종복위운동에 가담하였는데, 이후 공주 동학사 숙모전 초혼각에 생육신과 함께 배향되었다.","a":"영동 박흥생 묘비","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650216.jpg"},{"q":"○○○의 오백전 앞에 자리하고 있는 석탑이다. 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 형태로, 통일신라 석탑의 전형적인 양식을 따르고 있다. 아래층 기단은 각 면에 가늘고 긴 안상(眼象)이 정교하게 조각하였으며, 위층 기단에는 면의 모서리와 가운데에 기둥모양의 조각을 새겼다. 탑신부는 몸돌과 지붕돌이 각 한 돌씩이다. 층마다 몸돌의 모서리에 기둥모양의 조각을 두었으며, 몸돌이 위로 오를수록 알맞게 줄어들어 안정감이 있다. 지붕돌은 밑면의 받침이 각 4단씩으로, 통일신라 후기∼ 고려 전기 즈음에 주로 나타나는 양식이며, 네 귀퉁이가 살짝 치켜올라가 경쾌하다.","a":"증심사삼층석탑","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637136.jpg"},{"q":"○○○○○은 조선시대 수군들이 전투를 위하여 해안 벽에 쌓은 성곽이다. 세종30년(1448)에 세종실록 권121 최초로 ○○○○가 등장하며 당시 군함 제작에 쓰일 소나무 재배지였다는 기록이 있다. 또한 사량진이던 지명을 세조 1년(1455)에 ○○○○로 바꾸었다. 포(浦)를 수호하는 수군만호영의 소재지였기 때문이다. '○○○○성은 현의 서쪽 47리에 있으며, 성종 22년(1491)에 쌓았다. 둘레는 835척(250m)이다. ○○○○성에는 조선시대에 규모가 작은 지역의 수장인 종9품 권관이 파견되었다'는 기록이 대동지지에 전한다.","a":"고성 소을비포진성","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655760.jpg"},{"q":"조선 중기의 무신인 은암(隱庵) ○○○ 장군의 ○○이다. 선조 16년(1583) 무과에 급제한 후 훈련원의 벼슬을 거쳐 선전관이 되었으며, 임진왜란 때에는 장기현감으로 의병을 일으켜 큰 공을 세웠다. 그후 밀양목사와 경상좌도 수군절도사를 맡았으며, 정유재란 때에는 성주목사로서 왜적을 격퇴하였다. 인조 2년(1624) 이괄(李适)의 난이 일어났을 때에는 평안도 병마절도사 겸 부원수가 되어 반란군을 대파하였다. 충청북도 ○○시 금가면 오석리에 위치한 그의 묘는 부인 전주 이씨와 합장한 것으로 화강암으로 봉분의 아래부분을 둘렀다.","a":"충주 이수일 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649413.jpg"},{"q":"현 소유자의 조부가 1800년대 말기에 매우 정성 들여 지은 집이다. 중문을 중심으로 왼쪽에 사랑채, 오른쪽에 마구간 그리고 중문을 들어선 정면에 있는 ㄷ자형 안채가 모여 ㅁ자형 구조를 만들고 있는 집이다. 안채는 중앙 대청을 중심으로 왼쪽에 도장방이 있고 오른쪽에 안방이 있다. 그리고 그 앞으로 정지와 광, 상방과 작은 정지가 놓여 각각 마구간과 사랑채로 연결되어 있다. 사랑채는 사랑마루와 사랑방으로 되어 있는데, 사랑마루는 왼쪽으로 1칸이 돌출되어 있다. 그리고 3면을 판벽을 시설하여 마루방으로 꾸몄다. 사랑마루와 사랑방 앞에는 퇴칸을 두고 난간을 둘렀다.","a":"영주수도리김위진가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663211.jpg"},{"q":"청간천 하구 언덕에 위치한 조선시대의 정자로 관동팔경의 하나이다. 처음 지은 연대는 알 수 없으나, 중종 15년(1520)에 군수 최청이 고쳐 세웠다는 기록으로 보아 그 이전에 세워진 것으로 생각된다. 고종 21년(1884) 갑신정변 때 불타 없어졌다가, 1928년에 다시 지은 것이다. 앞면 3칸·옆면 2칸의 규모이며, 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕의 누각형식 정자이다. 추녀 밑에 걸린 ‘○○○’ 현판은 1953년 이승만 대통령이 쓴 것이다.","a":"청간정","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637935.jpg"},{"q":"옛날 경상감영의 정문으로, 조선 선조 34년(1601)에 세웠다. ○○○의 원래 이름은 ‘폐문루(閉門樓)’로 새벽 5시에 문을 열고 밤 10시에 문을 닫는 풍악을 울렸다고 한다. 이름을 바꾼 것은 감사가 이 건물 위에서 세속을 살핀다고 하여 붙인 것이다. 앞면 3칸·옆면 2칸 규모의 2층 누각이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양이다. 건물 4면에는 난간을 설치했으며, 뒤편으로는 계단을 만들어 오르내릴 수 있도록 하였다.","a":"관풍루","c":"문화유산자료","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659451.jpg"},{"q":"○○○은 안동권씨의 재실로써 1900년에 조성된 정자인데, 위양지에 조성된 섬의 중앙에 정자를 설치하고 배로 출입하도록 한 특별한 구성은, 중앙에 정자의 문화가 많이 남아있지 않은 경남지방 및 조선 후기의 조원의 사례로서 대표적인 모범이 될 만한 구성이다.","a":"밀양 완재정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023053016522600.jpg"},{"q":"1700년대에 지은 이 집은 영조 4년(1728) 이인좌의 난을 평정하는데 공을 세운 국담 주재성 이래 주씨 가문의 종가(宗家)이다. 정문인 대문과 중문, 사랑채인 감은재, 안채, 사당인 부조묘를 갖추고 있어서 종가의 면모를 보여줄 뿐 아니라 하환정, 풍욕루, 국담 등의 화려한 별당과 연못을 갖춘 대규모 주택이다. 사랑채는 국담의 장남 주도복의 서재로 문집과 책판이 보관되어 있고 대청 북쪽벽에는 초상화를 모셔 두었던 영정각이 남아 있다.","a":"함안 무기리 주씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659047.jpg"},{"q":"계족산성에서 북쪽으로 약 1.3km 떨어진 곳에 있는 이 산성은 남북방향의 봉우리 두 개를 중심으로 말안장 모양의 평면형으로 축조되었다. 성은 둘레가 300m이고, 테뫼식 석축산성으로서 내탁외축<內托外築>하였는데, 성벽의 대부분이 무너져 내렸다. 남벽의 일부에서 높이 1.2m의 성벽이 남아 있고, 이곳에서의 성벽 축조는 계족산성의 성돌과 유사한 편암계<片岩系>의 돌을 가지고 쌓았는데, 성벽을 약간씩 안쪽으로 물려서 쌓았으나 축조방법은 조잡하다. 북벽의 통과지점은 능선의 경사도가 완만하기 때문에 석루<石壘>를 높게 쌓았다.","a":"이현동산성","c":"시도기념물","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645825.jpg"},{"q":"○○○○○은 충청북도 ○○시 옥산면 환희리에 위치한 조선시대의 재실이다. 건립연대를 정확히 알 수 없으나 본래 조선시대 선정조사禪定祖師가 주재하였던 사찰로 추정하고 있다. 1914년 밀양박씨 문중에서 중수하여 재실로 축조하면서 영모재永慕齋라 불리었는데 건물 앞에는 ○○○水泉庵이라는 편액이 걸려 있다. ○○○은 옥산 덕촌리에서 환희리로 넘어가는 고개마루의 오른쪽 산 능선상의 평지에 자리잡고 있으며, 건물 앞에 흐르는 천수천을 향하고 있다.","a":"청주 수천암","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660841.jpg"},{"q":"경상남도 사천시 곤명면 ○○○ 뒷산에 있으며, 산 정상 아래쪽 테를 맨 모양으로 둘러쌓은 성곽으로 대부분 흙으로 쌓은 산성이다. 산성의 둘레는 약 2㎞이고 넓이는 약 8000평인데, 지금은 둘레 100m, 너비 1.5m 가량의 흔적만 남아 있을 뿐 성지는 대부분 과수원으로 개간되어 있다. 이곳에서 금동제마상 1개, 철제장검 1개, 민무늬토기조각, 기와조각 등 많은 유물이 출토되었다. 특히 기와조각에는 ‘삼정(三井)’이라고 새긴 글자를 통해 신라 때 기와로 보고 있다.","a":"사천금성리토성지","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656197.jpg"},{"q":"○○○○은 삼국시대에 초축(初築)된 것으로 판단되며, 내역(來歷), 문화적 영역으로 보아 울산권에 속한다. 이곳은 울산이나 경주로 통하는 중요한 길목으로 산성의 군사적 목적은 충분하였을 것으로 보인다. 현재 성벽은 많이 무너져 있지만 곳곳에 쌓은 상태로 남아 있고, 3개의 고지(高地)에 장대(將臺), 암문(暗門), 통로 등의 시설과 창고와 연못의 위치 확인도 가능하다. 특히 이곳은 신라의 24개의 주요 제장(祭場)이었던 소사(小祀)와 관련된 곳으로도 의미가 있다.","a":"양산우불산성","c":"시도기념물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657397.jpg"},{"q":"이 정자는 문종<文宗> 원년(1451)에 배환<裵桓>공이 처음 건립하였다고 전한다. 조선<朝鮮> 순조<純祖> 13년(1813)에 중건<重建>하였으나 그 후 퇴락하여 고종<高宗> 18년(1881)과 1955년에 다시 중수하였다. 안동지역에 있는 일반적인 정자의 형태를 잘 유지하고 있으나 누상주<樓上柱>에 비해서 누하주<樓下柱>가 짧은 것이 특징이며 이는 마지막 중수때에 의도적<意圖的>으로 변형했다고 생각된다.","a":"낙암정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662809.jpg"},{"q":"전라남도 순천시 승주읍에 위치한 ○○○에서 대각암(大覺庵)으로 올라가는 중간의 바위면에 새긴 불상으로, 약 7m 높이의 바위면에 옴폭 들어가게 새겼다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위에는 상투 모양의 머리묶음이 솟아 있다. 눈·코·입이 균형 잡힌 얼굴은 원만하며 얼굴에 비해 귀가 크게 새겨져 법주사 ○○○○의상(보물 제216호)의 귀와 비슷하다. 가슴에는 만(卍)자가 새겨졌고 옷은 왼쪽 어깨에만 걸쳐 입고 있다. 왼팔에 걸친 옷자락과 가슴을 덮고 있는 옷자락은 아래로 길게 흘러내려 몸 전체를 덮고 있다.","a":"선암사마애여래입상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662131.jpg"},{"q":"명부란 사람이 죽어서 머물러야 하는 곳이고 ○○○은 죽은 자의 천도를 위해 마련된 공간이다. 이 곳 ○○○의 중심에는 지장보살좌상을 중심으로 입상의 무독귀왕과 도명존자가 삼존으로 모셔져 있고 그 좌우로 椅子像인 10구의 ○○○과 녹사1구, 판관 1구, 사자 2구, 동자상 10구 등 총 28구가 배열되어 있다. 복장 연기문에 따르면 이들은 ○○ 화악산 천주사에 봉안되었던 불상이였는데 언제인지는 모르나 ○○로 옮겨져 봉안되어 있다. 재료는 불석재이며 1678년(숙종4년)에 제작된 것으로 조선조 불석제 불상 중 연대가 올라가는 귀한 작품이라 할 수 있다.","a":"청도 덕사 명부전 석조지장삼존상 및 시왕상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641195.jpg"},{"q":"이 문서들은 고봉 ○○○ 가계의 재산분배문서 3점, 전적 3점, 명문 6점, 시권 3점, 상소문 1점, 호구단자 1점, 관문 1점이다. ○○○ 선생은 호남성리학을 주도하였으며, 퇴계 이황과 함께 우리나라 성리학의 쌍벽을 이루는 대가이다. 이황과 8년동안 사단칠정(四端七情)에 관해 편지교환을 했던 일화가 유명하며, 조선시대 성리학을 독자적인 학문으로 발전시키는데 커다란 이바지를 했다. 이 가운데 재산분배문서는 자녀들에게 재산을 상속한 문서이며, 전적 3점은 ○○○이 선조 5년(1572)에『도산기』를 손수 옮겨 묵으로 적은 것이다.","a":"기대승종가소장문적","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637161.jpg"},{"q":"이 책은 조선 현종초 안동 김씨의 후손인 김성근이 병자호란(1636)때에 순절한 문중의 명현들의 자료를 수집하여 편찬한 것이다. 내용을 보면 김상용을 비롯한 명현들의 편지글, 시론, 경애사 등의 방대한 자료를 원(元), 형(亨), 이(利), 정(貞)의 연대순으로 분류하였다. 원은 18장으로 김상용, 김상헌 등 19인, 형은 19장으로 김창집, 김성최 등 16인, 이는 23장으로 김시걸, 김용겸 등 26인, 정은 14장으로 김이원, 김응순 등 20인 등 총 4책 74장으로 기록되어 있다.","a":"화산세가필적","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659725.jpg"},{"q":"조선 후기의 자기를 굽던 가마터로 ○○○ 북쪽에 위치하고 있다. 이곳은 예전부터 가마터가 있었다고 전해져 왔던 곳이다. 도자기를 만들기 위해 흙을 채취했던 흔적과 갑발, 가마의 일부, 백자 조각 등이 확인된다. 도자기 조각은 완, 접시, 사발 등 기종이 다양하며 이 조각들로 미루어 볼 때 조선 후기에 도자기를 굽던 가마터로 추정된다. 이 지역의 도자사 연구에 귀중한 자료이다.","a":"사천사촌리도요지","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657004.jpg"},{"q":"『○○○○○』은 법어(法語), 즉 부처님의 말씀이나 가르침을 적어놓은 것으로 승려들의 수행에 있어 길잡이 구실을 하며, 우리나라에서는 조선시대에 널리 유통되었다. 1책의 목판본이다. 간행 기록에 의하면 선조 12년(1579) 지리산 신흥사에서 간행된 것이다.『○○○○○』은 현재 한글로 풀이한 언해본 3종이 보물로 지정되어 있는데 동국대학교소장본, 이겸로의 소장본, 세종대왕기념사업회 소장본이 그것이다. 이 책은 잘 알려지지 않은 한문본으로, 언해본들과 비교해 볼 때 내용구성이 차이가 있어 별도의 사료적 가치 뿐만 아니라 불교사 연구에 귀중한 자료로 평가된다.","a":"범어사 몽산화상법어약록","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636674.jpg"},{"q":"독립 운동가로 활약하던 고헌 ○○○이 태어나고 자란 집이다. ○○○은 비밀 결사대인 대한광복회를 조직하고 총사령으로서 광복을 위해 활약한 분이다. 대문채와 사랑채, 안채 등 여러 부속 건물을 ㅂ자형으로 배치하였다. 사랑채는 마루와 방을 갖추고 있으며 뒤의 중문을 지나면 ㄱ자형 안채가 있다. 남녀의 공간을 작은 문으로 간단히 구획하여 각각의 공간에 독립성을 확보하고 있다.","a":"박상진의사생가","c":"문화유산자료","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659781.jpg"},{"q":"이 책판은 조선 중기의 문신인 동계 ○○의 시문을 모아 간행한 것이다. ○○는 39세 때 가을 증광시에 급제하여 벼슬에 나아가기 시작하였으며, 내외직을 두루 역임하였다. 이 책판은 순조 9년(1809)에 간행하였고, 전부 8권으로 되어 있으며 서문은 임재 정종노가 썼고, 발문은 김굉이 썼다. 권1∼2에는 시, 권3에는 만(挽), 시보다 산문성이 강한 글인 부 그리고 권4에는 교서, 소, 답사, 계사, 권5에는 서, 권6에는 잡서, 침, 책문, 표전, 전문, 권7에는 축문, 제문, 묘비에 적는 글인 묘갈, 명지, 행장, 권8에는 부록, 년보가 들어가 있다.","a":"권도 동계문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641998.jpg"},{"q":"고려 초기에 세워진 석등으로 추정되며 사적 제317호로 지정된 중원 미륵리사지 내에 위치한다. 미륵리 ○○○○은 크게 기단부·화사석·옥개석 등으로 구성되어 있다. 기단부의 지대석은 일부 파손되기는 하였으나 원래는 평면 사각형의 판석형 석재가 마련되었음을 알 수 있다. 하대석은 투박한 복판 연화문이 장식되어 있다. 연화문은 대형으로 새겨져 있지만 치석 수법이 정연하지 못하고 다소 불균형적인 모습을 보이고 있다. 하대석 상면에는 사각형의 홈을 마련하여 간주석을 끼워 고정하도록 했다. 간주석은 평면 사각의 석주형으로 마련되었다.","a":"충주 미륵대원지 사각석등","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638960.jpg"},{"q":"○○○는 1930년대 상효동 산85-1번지에 있던 쌍계암을 서홍동으로 이건하였다가 다시 이곳으로 옮겨 창건된 사찰이다. ○○○ 소장 ○○○○○은 1702년에 전라남도 순천 북령 동리산 대흥사(순천 북령 동리산 대흥사)에서 조성 봉안되었던 불상으로서 후일 쌍계암에 봉안되었다가 이곳으로 옮겨왔다. 이 불상은 과거칠불 중 제3불인 비사부불(毗舍浮佛)이며 국내에서는 처음으로 발견된 것이다. 불상의 재질은 경주불석(慶州佛石)이며 전체높이 61.5cm, 전체너비 44.5cm, 어깨너비 28.0cm, 무릎너비 42.0cm이다.","a":"정방사소장석조여래좌상및복장유물일괄","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643329.jpg"},{"q":"일재 이항·건재 김천일을 비롯하여 김점·김복억·김승적·소산복을 기리고 있는 서원이다. 이항(1499∼1576)은 조선 중기 문신으로 성리학에 조예가 깊은 학자이다. 김천일(1537∼1593)은 임진왜란 때 의병을 일으켜 왜군을 무찌른 장수이다. 이 서원은 선조 10년(1577)에 이항과 김천일을 추모하기 위해 세웠고 숙종 11년(1685) 임금으로부터 ‘남고’라는 이름을 받아 사액서원으로 승격되었다.","a":"남고서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661692.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 세종(재위 1418∼1450) 때 세워진 후 선조 25년(1592) 임진왜란으로 불타자 ○○향교와 합하였다가 광해군 3년(1611)에 다시 지었다. 그 후 여러 차례의 수리가 있었다. 현재 대성전·명륜당·내삼문 등이 남아있다. 공부하는 공간인 명륜당을 앞에 두고 제사하는 공간인 대성전을 뒤에 오도록 한 전학후묘의 배치를 보이고 있다. 대성전에는 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 있다.","a":"보은 회인향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638536.jpg"},{"q":"◦ 이 불상의 얼굴모양은 타원형인데 마멸이 심하여 원래의 모습을 알기 어려움. ◦ 머리는 소발이며, 정수리 부분의 육계 표현은 뚜렷하지 않음. 왼쪽 귀는 없어지고 코는 시멘트 때움 되어 전체적인 인상이 일그러졌지만 비교적 우아하고 세련되게 처리한 흔적이 보임. ◦ 목에는 삼도가 두렷하며, 오른손을 내리고 왼손을 들어 배에 대고 있는 형태이며 손은 결실 되었음. ◦ 입고 있는 법의는 양어깨를 모두 덮은 통견식이며, 어깨에서 배까지 U자형의 옷 무늬를 표현하고, 양팔 등에는 계단식 옷 무늬를 표현하고 있음.","a":"보령성주사지석불입상","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661536.jpg"},{"q":"이곳의 성은 대운산(해발 742m) 동쪽 지맥의 한 봉우리(270m)와 그 아래의 능선과 계곡을 성내로 포용하며 쌓은 포곡식 산성이다. 체성은 북쪽은 훼손이 심하지만 남동쪽은 양호한 상태호 남아 있다. 성벽은 자연석을 손질해서 급경사 지역은 내탁(바깥쪽은 석벽으로, 안쪽은 잡석과 흙으로 채워 쌓는 방법)하고, 경사가 완만한 지역은 협축(성벽의 안팎을 모두 수직에 가까운 석벽으로 쌓는방법)하여 쌓았으며, 규모는 길이 약 1km, 높이 100~220cm 정도이다.","a":"운화리성지","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659799.jpg"},{"q":"전라남도 보성군 복내면 ○○○에 있는 불상으로 전체 높이 2.22m, 광배 너비 1.36m이다. 자연석을 배(舟)모양으로 다듬고 그 위에 불상을 새겼다. 둥글고 큰 얼굴은 엄숙하면서도 토속적인 인상을 풍기고 있으며, 머리 뒤에는 연꽃무늬가 새겨진 둥근 머리광배가 있다. 옷은 왼쪽 어깨에만 걸치고 있으며, 가슴에서 왼쪽 어깨로 올라간 주름은 간략하면서 느슨하다. 큼직한 두손은 무릎 아래로 내려 손바닥이 왼손은 밖을, 오른손은 안을 향한 독특한 모습이다. 지방화된 토속적인 불상 양식의 한 단면을 보여주는 작품이다.","a":"보성반석리석불좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639984.jpg"},{"q":"창평면은 담양군의 남동부에 위치하는데 증암천의 한 지류가 동쪽으로 올라오면서 형성된 분지성 지형을 이루고 있다. 창평면의 남반부는 해발 300∼450m의 산으로 둥글게 둘러싸고 있고 북반부는 해발 200m내외의 산지가 분포하고 있는데 증암천은 동쪽에 좁게 열린 협곡을 흘러 고서면으로 이어지고 있다. 창평면의 중심부에는 하천을 따라 비교적 젊은 충적지가 형성되어 있는데 고분은 하천에서 100m 정도 떨어진 창평고등학교 동쪽의 논에 있다.","a":"담양창평리고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662253.jpg"},{"q":"1938년경 세운 2층 양옥 형태의 집이다. 개화기 때 상류층 ○○으로서 질 좋은 부재를 사용하였다. 벽체는 돌을 벽돌식으로 모양을 내어 쌓았고 지붕은 프랑스 기와를 이용한 것이라고 하는데 뾰족지붕이다. 출입문은 윗부분을 무지개 모양의 아치형으로 꾸몄고, 건물 여러 군데에 격자무늬 창을 냈다. 60여년의 세월이 지났어도 현대 건축물에 뒤지지 않는 세련미를 보이고 있다.","a":"가회동 이준구 가옥","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659296.jpg"},{"q":"○○군 여항면 주동리, 내곡리 일원에 위치한 ○○○○○는 ○○의 진산인 여항산 동쪽에 마주한 ○○, 일명 봉화산(해발 675.5m) 정상부에 위치해 있다. 조선 전기에 축조되어 후기까지 경상도 방면의 직봉(直烽) 2로 중 간봉(間烽) 2로로서 기능을 수행하였으며, 진해의 가을포봉수를 받아 의령의 가막산봉수에 연결되었다. 함주지에 의하면 연대 1, 연굴 5, 화덕 1, 망덕 1개의 봉수시설이 있었다고 기록하고 있으나 현재 연대1, 건물터 2곳만 확인되고 있다.","a":"함안 파산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656782.jpg"},{"q":"○○○○은 1592년(선조 25) 임진왜란 때에 의병을 일으켜 자인전투, 영천성 전투등에 참여하여 전공을 세우고 경주성 전투에 참여하였다가 순국했던 영천지역의 의병들을 제향하고 있는 서원으로서 이곳에 배향된 인물은 모두 영천 지역 출신의 중견관료 및 사림으로 인근 지역의 농민들을 이끌고 왜군의 격파에 노력 하였으나 모두 일시에 순국 했다. 조선 숙종 31년(1705)에 사당을 건립하고 정조 21년(1797)에 강당을 건립하였으며 대원군의 훼철령으로 훼철되었으나 1916년 유림이 십충현(十忠賢)을 복향하고 매년 제향을 올리고 있다.","a":"고천서원","c":"시도기념물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654657.jpg"},{"q":"부도란 승려의 무덤을 상징하는 것으로, 시신을 화장한 후 그 유골이나 사리를 그 안에 모셔두는 것이다. 문수사 내에 자리하고 있는 이 2기의 부도는 절내에 마련된 두 군데의 부도밭 중 서쪽에 있는 부도밭에 놓여 있다. 이 곳에는 6기의 부도들이 나란히 자리잡고 있는데, 앞에서 보아 두번째와 세번째에 해당하는 것이 이들이다. 둘 다 같은 양식으로 각 부분이 8각의 평면으로 구성되어 있어서, 세부분으로 이루어진 기단(基壇) 위로, 탑신(塔身)을 올린 후 머리장식을 얹어 마무리하였다. 조선시대에 세운 것으로, 제법 균형미가 느껴지며 만든 솜씨도 섬세하다.","a":"문수사부도","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639629.jpg"},{"q":"조선 중종 38년(1543)에 당시 전라도 관찰사였던 규암 송인수가 왕명을 받들어 지지당 송흠을 위하여 관수정 건너편에 지은 정자이다. 병자호란과 화재를 당하여 폐허가 되었다가 철종 7년(1856)에 송인수의 10대손인 송겸수가 영광군수로 부임하여 고쳐 지었다. 건물은 앞면 2칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 바닥에 마루를 깔아 대청으로만 구성되어 있으며 사방을 낮은 평난간을 돌렸는데, 땅의 위치가 높아 누마루의 높이가 상대적으로 낮다. ○○○은 용암천 위의 경치가 아름다운 경승지에 자리잡고 있다.","a":"장성 기영정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662037.jpg"},{"q":"이 ○○○○은 원래 전라감영에서 서적을 간행할 때 사용하였던 것으로 전라감영 내에 보존․관리되고 있었으나 1899년 당시 전라관찰사이었던 조한국의 명으로 전라감영 내에 분산되어 있던 책판을 모아 ○○○○에 보존하게 되었다. 1920년대에 책고를 지어 관리해 오다가 1987년 전주시에서 장판각을 건립하고 목재로 서가를 만들어 오늘에 이르고 있다. 장판각에 소장된 ○○○○은 총 5,059개에 9,830면이 서각되어 있으며, 서각되지 않은 면수는 288면이다.","a":"전주향교소장완영책판","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639778.jpg"},{"q":"두레는 한국 농촌사회에 있어서의 전통적인 공동노동 가운데 하나로, 농촌에서 주로 모내기나 김매기 때와 같이 1년 중 가장 바쁜 이앙기를 중심으로 단기간 내에 대규모의 노동력을 집약적으로 투입해야 할 때 주로 행해졌다. 농기는 두레 풍물패의 상징으로서 두레패들이 두레 노동시에 세워 두던 깃발로 공동노동이 끝날 때까지 세워 두었다.","a":"농기일괄","c":"문화유산자료","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659323.jpg"},{"q":"조선시대 서산군의 관아로 객관, 동헌, 누정 등으로 되어 있었는데, 지금은 ○○○과 ○○○만이 남아있다. 조선 고종 4년(1867)에 당시 서산군수 오병선이 다시 지은 것이다. 1978년부터 1979년까지 2년 동안 동헌을 서산시청 서쪽으로 옮겨지었고, ○○○도 보수를 하였다. ○○○은 서산군 관아의 정문으로, 현재 서산시청 입구에 있다. 앞면 3칸·옆면 2칸규모의 2층 문루 건물이며, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 1층은 돌기둥 모양의 주춧돌 위에 네모기둥을 올렸으며, 기둥 사이에 각각 대문을 달아 출입하게 하였다.","a":"서산관아문및외동헌","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639065.jpg"},{"q":"이 목판은 삼국시대 이후부터 조선 전기까지의 우리나라 명현들의 시를 뽑아 평가하고 해석을 붙인 것이다. 조선 성종 4년(1473) 김종직이 편찬작업에 착수하여 2년 후에 완성하였고, 중종 26년(1531) 공주에서 이미 출간된 책을 바탕으로 체제만 달리하여 다시 간행하였다. 구성을 보면 원집이 7권 1책, 속집이 7권 1책 등 총 2책 14권으로 되어 있다. 안동 김씨 가문에서 대대로 전해내려오던 것으로, 김수인 등의 인기(도장)가 찍혀 있다.","a":"청구풍아","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659719.jpg"},{"q":"○○○은 남자 성기 모양의 자연암석이나 조각하여 세운 것을 이르는 것으로, 복을 빌거나, 다산·풍농·풍어를 기원하는 민간신앙의 대상이 되고 있다. ○○○○○은 높이 165㎝, 둘레 145㎝의 화강암으로, 포경선을 자세히 표현해 놓았고, 아래 부분에 연꽃무늬를 새겨 놓았다. 전해오는 전설에 따르면 옛날 500여 년전 태촌마을에 한 걸인이 살았는데, 신분때문에 결혼 뿐만 아니라 성생활도 할 수 없어 이를 비관하며 ○○○을 세웠다고 한다.","a":"창덕리남근석","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658302.jpg"},{"q":"고려말에서 조선초기에 네모 모양으로 축조된 이 분묘가 제주지역 묘제사 연구에 귀중한 학술적 가치를 지니고 있으며, 1992년 제주대박물관이 발굴조사할 당시 도자기편 및 문인석 등 일부 석물이 발굴됐고 이후 봉분이 복원됐다.","a":"거로 능동산방묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658001.jpg"},{"q":"읍동마을 당산나무 밑에 놓여 있는 ○○○ 석등으로, 주위에는 밭이 펼쳐 있고 뒤로는 상라산이 병풍처럼 배경을 이루고 있다. 절터의 흔적은 찾아볼 수 없으나 주위에서 토기나 기와조각들이 발견되고 있어, 지금도 불교신도들이 이곳에 찾아와 불공을 드리고 있다. 석탑은 땅 위로 기단(基壇)의 맨 윗돌만 드러나 그 아래는 모두 묻혀 있으며, 위로는 3층의 탑신(塔身)이 쌓여 있다. 탑신의 세 몸돌은 모두 위아래와 서로 틀이 딱 맞지 않아 원래의 것이 아니었을 것으로 보이는데, 네 모서리마다 기둥 모양의 조각이 보인다.","a":"신안흑산진리무심사지삼층석탑과석등","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662214.jpg"},{"q":"좁은 터에 안채, 행랑채, 별당을 따로 만든 한옥 살림집이며 1920년대 이후 개량한옥으로서 보기 드문 예가 되는 집이다. 대문을 들어서면 다시 대문채가 있고 안쪽에 있는 대문을 들어서야 안채가 있다. 대문간 행랑채는 일반적인 一자형 평면과 다르게 휘어지게 지었으며 대문의 남쪽으로 방 2칸과 광 2칸을 두었다. 현재 광 1칸은 방으로 개조하였다. 안채는 지붕 옆면의 선이 여덟 팔(八)자 모양과 비슷한 팔작지붕이며 창호는 대부분 현대식으로 바꾸었다. 대문채와 별당채는 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕으로 꾸몄다.","a":"용강동정구중가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658057.jpg"},{"q":"이 책은 조선 후기 건봉사의 축전(竺典)이 엮은 한글로 된 불교가사를 모아놓은 것으로, 「권왕가」, 「자책가」, 「서왕가」 등 3편이 수록되어 있다. 내용은 대체로 몽매한 중생들을 깨우쳐 불심을 일으키고자 하는 내용이다. 「권왕가」는 서방정토에 왕생하는 방법을, 「자책가」는 불법을 모르고 덧없이 세월을 보낸 것을 자책하는 내용을, 「서왕가」는 출가수도하여 서방정토에 왕생할 뜻을 나타내고 있다. 이 ○○의 판수는 모두 22판이나 7, 8판이 소실되고 현재 20판이 남아있으며, 책은 1권 1책으로 구성되어 있다.","a":"범어사 권왕문 책판","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636663.jpg"},{"q":"○○○는 수덕사에 딸린 절로 백제 승려 의각이 세운 절이다. 절 경내에 있는 극락전에서 70여m 떨어진 곳에 있는 ○○○은 자연석 기단 위에 세운 법당이다. 앞면 4칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕을 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 건물의 앞면에는 모두 여닫이문을 달았고, 주춧돌은 잘 다듬지 않은 자연석을 사용하였다. 건물 안쪽에는 현재 1,515기의 불상을 모시고 있는데, 작은 불상은 거의 석고상이고, 큰 불상은 석재로 만든 것도 있다.","a":"향천사천불전","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661170.jpg"},{"q":"○○○○은 태안군의 진산 백화산 정상부에 돌로 쌓은 성으로 주변 지역을 한눈에 감시할 수 있고 외적의 침입을 방어하기에 유리한 위치에 입지하고 있다. ○○○○은 성벽의 축성기법과 출토유물을 통해 보았을 때 백제 시대 후기에 처음 축조한 것으로 보이며, 고려 시대까지 성벽을 보수하면서 산성으로서의 기능을 하다가 조선 시대 이후 봉수대로 활용된 것으로 추정된다. 군부대 내 성벽 실측조사가 이루어지지 않아 명확한 성벽의 둘레는 알 수 없으나 최근 조사 결과 성벽의 전체 둘레는1,017m로 추정된다.","a":"백화산성","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661262.jpg"},{"q":"평택시 안중읍 용성리의 해발 102.2m인 ○○○에 있다. ○○○은 산세가 비파악기를 닮았다고 붙여진 이름이다. 이곳은 동쪽으로 차령산맥, 남쪽으로 아산만 일대, 서쪽과 북쪽으로는 서해안 일대가 조망되는 전략적 요충지다. 산성은 ○○○의 정상부와 용성리 뒷골의 평지를 포함하는 삼태기 모양의 평산성이다. 성벽의 둘레는 1,622m로 인근의 성곽 중에서는 가장 규모가 크다. 발굴조사 결과 성벽은 판축공법으로 쌓은 토성으로 확인되었다. 성벽의 기초를 정지하고 일정한 간격으로 기단석열을 배치한 후 점질토와 사질토를 교대로 쌓는 판축공법으로 중심토루를 먼저 구축했다.","a":"평택비파산성지","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647325.jpg"},{"q":"오랜 세월 방치되어 있던 것을 마을 주민들이 1914년 보호각을 세우고 보광전이라 이름지어 옮겨 놓은 것이다. 전하는 말에 의하면 고려말 죽산 부원군이었던 김원발이 마을에서 분쟁이 자주 일어나자 지리적 영향이라 믿고 부처님의 자비로 막아 보려는 의도에서 불상을 만들었다고 한다. 풍만한 둥근 얼굴에 눈은 반쯤 감겨 있고 코는 떨어져 나간 것을 보수하였다. 목에는 3줄의 주름인 삼도(三道)가 돌려졌는데 현재는 시멘트로 붙여놓았다. 옷은 왼쪽 어깨에만 걸치고 있으며, 화려한 옷주름은 무릎까지 덮여 있다.","a":"예천향석리석조여래좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662686.jpg"},{"q":"경상남도 ○○시 천선동 ○○○ 용화전 안에 모셔져 있는 전체 높이 148㎝의 보살상으로, 불신과 광배(光背), 대좌(臺座)를 화강암으로 만들었다. 관음보살은 이름을 외우기만 해도 중생의 어려운 일을 구제해 준다고 해서 가장 널리 믿어지고 있다. 민머리 위에 화려하게 장식한 관(冠)을 쓰고 있으며, 얼굴은 원만하고 목에는 목걸이가 새겨져 있다. 둥근 어깨와 굵은 곡선으로 새긴 U자형의 옷주름은 부드러운 느낌을 주고 있으나 상체에 비해 하체가 짧아 균형감을 상실하였다. 전체적인 조각기법으로 보아 고려시대에 만든 것으로 보인다.","a":"창원 성주사 석조관음보살입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642274.jpg"},{"q":"1950년경에 ○○○ 절골의 석불암 앞산에서 발견된 불상이다. ○○도에서 이런 큰 불상이 나온 것은 드문 일인데, 1170년에 고려 의종이 ○○도에 폐왕성(廢王成)을 쌓고 3년간 머물면서 만들었다는 설이 전해진다. 어깨는 넓게 표현했지만 하체를 왜소하게 나타내고 있어 어딘지 불안정해 보인다. 오른쪽 어깨를 드러내고 입은 옷은 비교적 얇은 편인데 밀집된 옷주름을 보이고 있다. 손모양은 오른손을 무릎 위로 올리고 손가락이 아래로 향한 항마촉지인(降魔觸地印)으로 석가모니불임을 알려준다. 불상이 앉아 있는 대좌(臺座)는 연꽃무늬가 새겨진 원추형의 상대와 하대만 남아 있다.","a":"거제 오량리 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022711304301.jpg"},{"q":"전라남도 담양군 금성면에 위치한 이 석불은 금성산성 남쪽 높이 약 20m쯤 되는 암벽 바로 밑에 석탑과 같이 보존되어 있다. 이 석불은 사각형의 돌기둥 앞뒷면을 약간 다듬어 머리 부분을 조각하고, 신체에는 손과 형식화된 옷주름을 표현했다. 머리는 민머리이며 얼굴은 둥글넓적하다. 양 어깨를 감싼 옷은 간략하게 표현하였으며, 양 팔을 걸쳐 내려온 한가닥의 옷자락이 특징적이다. 가슴 아래에 장식된 띠매듭은 사실적으로 표현되었는데 이는 통일신라시대부터 이어진 양식이다.","a":"연동사지지장보살입상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662193.jpg"},{"q":"경상남도 합천군 해발 90m의 매봉산 정상울 둘러 쌓은 대야성은 흙과 돌을 이용하여 쌓은 성이다. 이 곳은 삼국시대 때 백제와 신라 서부지방의 접경지대로, 신라 진흥왕 25년(565)에 신라가 백제의 침공을 막기 위해 쌓았다 한다. 선덕여왕 11년(642) 백제 윤충의 공격으로 함락된 적이 있었는데, 이 때 신라 대야성 도독 김품석과 부인(김춘추의 딸)이 죽자 김춘추는 백제를 멸망시킬 결심을 한 곳이다. 또한, 경명왕 4년(920)에는 후백제 견훤에게 함락되기도 하였다. 성벽의 길이는 300m 정도인데 대부분 훼손되어 원형이 남아있지 않다.","a":"합천대야성","c":"시도기념물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655709.jpg"},{"q":"○○○조선 중기 문신. 자는 여수(汝受), 호는 아계(鵝溪). 본관은 한산(韓山). 1561년(명종 16) 식년문과에 급제, 이듬해 홍문관정자가 되었다. 그 뒤 부수찬·병조좌랑 등을 거쳐 사헌부집의·동부승지·대사성 등을 지냈다. 1578년(선조 11) 대사간으로 서인 윤두수(尹斗壽)·윤근수(尹根壽) 등을 탄핵하여 파직시켰다. 대사헌·우찬성·병조판서 등을 거쳐 1588년 우의정이 되었는데, 이때 동인이 남인·북인으로 갈라지자 북인의 영수로 정권을 잡았다.","a":"아계이산해영정","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639324.jpg"},{"q":"화성면 기덕리는 평택 임씨 집성촌으로 주변에는 재실이 있으며 지정건물과 맞대어 임석○○○이 위치하고 있음. 건립년대는 정확하지 않으나 1900년대 초 ○○○○ 지었다고 전해지며 그의 호가 ‘삼전’으로 삼전고택이라고도 불리움. 안채, 사랑채, 곳간채 등 건물구조, 양식은 물론 담장 등 전통양식이 비교적 원형유지⋅관리가 잘 되고 있어 도 민속자료로 지정","a":"청양임찬주가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658278.jpg"},{"q":"초기 내포지역 천주교 전파의 거점이었던 ○○○은 충청도 지역교회 창설의 요람으로 ‘충청도의 사도’라고 불린 ○○○의 ○○○가 있다. ○○○은 스스로 충청지방 천주교 신자들의 지도자임을 자인하고 내포지역에서 포교활동을 하였다 1795년 체포되어 정약종 등과 함께 사형선고를 받아 공주 황새바위에서 참수형을 당하는 등 초기 천주교 전파의 대표적 유적지로 알려져 있다.","a":"예산여사울이존창생가터","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653225.jpg"},{"q":"현재 판전의 후불탱화로 봉안되어 있는 ○○○○○화로, 1886년 칠성도, 산신도와 함께 조성되었으나 칠성도는 1942년에 북극보전을 지으면서 그곳으로 이안하였고 산신도는 남아있지 않다. 등운 수은(騰雲 修隱)이 화주가 되어 상궁 8인의 시주로 조성하였으며, 영명 영기(影明 影機)의 주도 하에 경선 응석(慶船 應釋)이 출초를 하고 동호 진철(東昊 震徹), 연하 계창(蓮荷 啓昌), 종현 현조(宗現 賢調), 혜능 창인(惠能 彰仁) 등이 함께 제작하였다.","a":"봉은사 비로자나불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636420.jpg"},{"q":"고려 후기 공민왕 때의 문신이었던 신사천( ? ∼1382) 선생과 그 두 딸의 충효와 절의를 기리고자 세워놓은 2기의 비이다. 『고려사절요』에 따르면, 봉익대부전공판서를 지내던 신사천은 벼슬을 버리고 고향으로 돌아와 머물던 중, 왜적이 여러 차례 침략하자 이에 맞서 싸워 큰 공을 세우고, 우왕 8년(1382)에 순절하였다. 그의 큰딸은 랑장 김우현의 처가 되어 남편과 함께 왜적과 싸우다 목숨을 잃었으며, 작은딸 역시 16세 처녀의 몸으로 왜적과 싸우다 순절하였다.","a":"창녕 열효신씨 정려비","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664273.jpg"},{"q":"영종첨절제사를 지낸 ○○○ 선생의 공덕을 기리고 있는 비이다. 조선 고종 12년(1875) 8월 강화도에 침입하여 초지진을 공격하고 돌아가던 일본 군함 운양호가 도중에 영종진을 공격하며 뭍에 올라와 진을 점령하고 관아에 불을 질렀다. 이에 조정에서는 인천부를 방어영으로 승격시키는 동시에 강화유수부에 속해 있던 영종진을 인천방어영에 속하게 하였으며, 10월에는 홍문관 제학 ○○○을 영종첨절제사로 임명하여 관아를 복원하였다.","a":"양주성 선정비","c":"문화유산자료","nc":"","r":"인천광역시","s":"영종구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019073010291900.jpg"},{"q":"이곳은 한글학자 외솔 ○○○○○의 ○○○이다. 생가는 이미 없어졌으나, 2008년 복원하여 현재에 이른다. 선생은 여기에서 태어나 병영초등학교를 졸업하였고, 1910년 상경하여 한성고등학교(漢城高等學校, 뒤에 경성고등보통학교로 개칭)에 입학하였다. 이때 주시경(周時經 : 1876〜1914)선생이 운영하던 조선어강습소에 다니며 우리말과 글을 지키고 가르치는 일이 광복의 길임을 깨닫고 이 일에 평생을 바칠 것을 결심하였다. 이후 일본 히로시마고등사범학교 문과에서 수학하고, 1922년 4월 일본 교토제국대학(京都帝國大學)에 입학하여 교육학을 전공하였다.","a":"외솔최현배선생생가터","c":"시도기념물","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645917.jpg"},{"q":"도천리 길성마을 산자락에 남서향으로 자리하고 있는 건물로 현 소유주의 고조부인 김병집이 터를 잡고 증조부인 김우규(1849∼1926)가 1924년에 지었다고 한다. ㅁ자형 정침과 사랑 전면에 ㄱ자형 부속사가 자리잡고 있으며 부엌 왼쪽으로 헛간이 있다. 구성은 경상북도 북부지방의 양반집이나 부농의 건축에서 많이 사용되는 ㅁ자형 평면으로 사랑 부분과 정침 부분 및 부엌과 연결되는 수장 부분 등 3공간으로 나뉘어 있다. 사랑은 모두 6칸으로 이루어져 있으며 온돌방 2칸과 마루방 2칸을 전면에 두고 오른쪽 날개쪽으로 꺾어 서실 2칸을 마련하였다.","a":"김갑동가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663194.jpg"},{"q":"일제에 의해 강제로 체결된 을사조약과 한일합방을 통탄해하며 자결한 송병선(1836∼1905)과 송병순(1839∼1912) 형제의 위패와 영정을 모시고 제사 드리는 사당이다. 송병선은 우암 송시열 선생의 9대 손으로 학문이 뛰어나 천거되었으나 관직에 나가지 않았다. 19세기말 외세가 물밀듯이 들어와 나라의 앞날이 어려워지자 『근사속록』을 간행하였다. 또한 1905년 불법적인 을사조약이 체결되었을 때는 고종에게 조약 파기와 을사 5적을 처단할 것을 진언하기도 하였다. 다시 고종을 만나려다가 일본 헌병들에게 체포되었는데 상소문을 올리고 음독 자결하였다.","a":"문충사","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659695.jpg"},{"q":"이 사경은 68절면에 1절면 6행 17자로 이루어진 1첩의 절첩본(折帖本) 형식으로 되어 있으며, 보존 상태는 양호하다. 앞의 32절면은 감지에 은니(銀泥)로 쓴 사경이지만, 뒷부분 36절면은 감지에 금니(金泥)로 사성되어 있다. 즉 앞 시대에 먼저 감지에 은니로 제작된 후 뒷부분이 없어진 채로 전해오다가, 영조 4년인 1728년에 없어진 뒷부분의 내용을 보강하여 감지금니 사경으로 새롭게 꾸민 것으로 추정된다.","a":"대방광불화엄경 권40","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636727.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 11년(1411)에 처음 지었으며, 최근인 1981년에 전면 복원하였다. 지금 남아 있는 건물로는 제사 공간인 대성전, 교육 기능을 수행하는 강당인 명륜당, 학생들의 기숙사인 동재·서재, 내삼문, 외삼문 등이다.대성전의 안쪽에는 공자를 중심으로 그의 제자들과 중국과 우리나라의 성현의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생들을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"양천향교 터","c":"시도기념물","nc":"","r":"서울특별시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102410005600.jpg"},{"q":"이곳은 절 이름과 유래가 전해지지 않은 백제의 절터이다. 부여읍 구아리에 있는 ○○○터에서 출토된 적이 있는 ‘천왕(天王)’이란 글자를 새긴 기와가 이곳에서도 나와 두 유적을 구분하기 위해 ○○○○터라고 부른다. 이 절터는 상하로 단이 이루어졌는데, 하층기단은 기와를 이용하여 만든 와적기단으로 기단 규모가 동·서 18.04m, 남·북 14.72m이다. 상층기단은 하층의 와적기단을 파괴한 위에 서 있으며 파괴가 심한 편이다. 와적기단의 남쪽에는 석축시설이 있고 그 안에 구덩이에서 연꽃무늬 와당, 백제토기, 치미 등 백제의 유물들이 많이 나왔다.","a":"동남리전천왕사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652773.jpg"},{"q":"이 유물은 조선시대의 학자 추사 ○○○와 관련된 것으로, 「○○○」, 「○○○○」, 「○○○○」의 3점이다. 추사 ○○○는 북학파의 일인자인 박제가의 제자이다. 청나라 고증학의 영향을 받아 금석학을 연구하였으며, 뛰어난 예술가로 추사체를 만들었고 문인화의 대가였다. 「○○○」와 「○○○○」은 종가에서 전해온 것이며, 「○○○○」은 벽에 써붙인 글로 고택기념관에 보관하고 있다.","a":"김정희선생유물<혼서지.생원시권.농상지실>","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639075.jpg"},{"q":"논산 관촉동 ○○○○○입상(현 행정구역 기준)은 관촉사 입구의 대정운사(大正雲寺)라는 고려시대 절터에 있던 불상이다. 불상은 전체적으로 신체에 비해 머리가 매우 크게 강조된 독특한 비례를 보인다. 머리 윗부분은 관(冠)을 쓴 듯 높이 솟아 있고, 그 위에 다시 큰 육계(肉髻, 상투 모양의 머리)가 있다. 이는 관촉사 석조미륵보살입상(국보)과 유사한 양식을 보여준다. 얼굴은 사각형에 가까운 넓적한 형태로 양감이 풍부하며, 눈은 은행알 모양, 코는 깊은 윤곽선으로 표시되어 있으며, 얼굴에 비해 작은 입과 턱의 U자형의 선이 특이하다.","a":"은진관촉리비로자나석불입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639146.jpg"},{"q":"언덕 위에 자리한 천주교 성당으로, 서양 중세 때 유행하던 고딕건축 양식 건물이다. 평면이 약간 변형된 라틴식 십자가형으로, 외관이 붉은 벽돌로 되어있다. 중앙 현관의 꼭대기에는 높은 종탑이 있고, 현관 출입구와 창의 윗부분은 끝이 뾰쪽한 아치로 장식되어 있다. 내부는 중앙에 여러사람이 앉을 수 있는 긴 의자를 놓고 그 양쪽에 복도를 둔 형식이다. 중앙의 넓은 공간과 복도 사이에는 6개의 돌기둥이 있는데 단면이 6각형을 이루고 있다. 1934년에 착공하여 1936년에 완공한 것으로, 전통적인 목조건물에서 현대 건축으로 넘어가는 과정을 엿볼 수 있다.","a":"공주중동성당","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653032.jpg"},{"q":"경상남도 ○○군 웅양면 한기리에 있는 성곽으로 성벽은 계곡을 포함한 산 정상부를 둘러 쌓은 포곡식 산성이다. 성벽은 자연석을 이용하여 쌓았는데, 길이는 1500m, 높이는 2m 정도이며 현재 성안은 경작지로 이용되고 있다. 언제 성을 쌓았는지는 정확히 알 수 없으나, 삼국시대 백제가 신라의 침입을 막기 위하여 처음 쌓았다고 전해지며, 임진왜란 때 왜적의 침입을 막기 위하여 다시 쌓았다고 한다. 정유재란 때 이일(李鎰) 장군이 가등청정의 군사와 치열하게 싸움을 벌인 곳이기도 하다.","a":"거창 하성","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664032.jpg"},{"q":"○○○ 선생이 6세까지 살던 생가지로, ○○○ 생애비가 있는 곳이다. 원래는 ○○○ 생가를 비롯하여 8∼9호의 민가가 작은 마을을 이루고 있었으나, 화재로 모두 없어졌다. ○○○은 조선시대 말엽의 정치가로 ‘위로부터의 개혁’을 외치며 개화사상을 주장하였다. 고종 21년(1884)에 갑신정변을 일으켰으나 3일만에 실패하여 일본으로 망명하였다. 1894년에는 한·중·일 삼국의 제휴라는 삼화주의를 주장, 청나라의 실력자 리홍장을 만나러 상해를 방문하던 중 수구파 자객 홍종우에게 암살 당했다.","a":"김옥균선생유허","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651856.jpg"},{"q":"○○○는 월출산에 있는 절로 통일신라말 도선이 지었다고 하나 확실하지는 않다. 다만, ○○○ 입구에 고려 선종 7년(1090)에 만들어진 국장생이 있는 것으로 보아 그 이전에 세웠고 11세기 후반에 번성한 것으로 추측된다. 그 뒤 세조 3년∼10년(1457∼1464)에 수미왕사가 크게 다시 세웠으며, 여러 차례 수리·복원하여 현재 모습에 이르고 있다. 현존하는 건물로는 대웅전, 명부전, 미륵전, 요사채 등이 있으며 그외 ○○○해탈문(국보), ○○○석조여래좌상(보물), ○○○소조동자상(보물), 도선수미비, 오층석탑, 수미왕사비 등 많은 문화유산들이 있다.","a":"도갑사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662018.jpg"},{"q":"○○○○○과 ○○○○○의 묘역에 건립한 ○○○이다. ‘○○○’과 ‘○○○’은 사후에 하사받은 시호이며 ○○○과 ○○○는 부자(父子) 관계이다. ○○○의 본관은 나주(羅州)이고 호(號)는 월봉(月峯)이다. 명종 즉위 후 대윤파(大尹派)를 제거하는 데에 공을 세워 보익공신(保翼功臣) 3등에 봉해졌다. 아들인 ○○○는 이조좌랑, 병조판서 등을 지냈다. 묘역 입구에 마련된 비각 안에 2기의 ○○○가 나란히 세워져 있다. 원래는 고양시 행신지구에 있었으나 도시 개발로 인해 1988년 10월에 현재 위치로 이전한 것이다.","a":"공안공정옥형·충정공정응두신도비","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660145.jpg"},{"q":"조선 헌종(재위1834∼1849)의 후궁인 경빈 김씨가 자신의 거처인 순화궁에서 궁체로 쓴 두권의 책으로, 이 둘을 가리켜 『순화궁첩초』라고도 한다. 사절복식자장요람의 표지는 남색으로 용무늬가 있고, 국기복식소선은 녹색에 구름무늬가 있다. 책의 내용은 조선조 역대 왕과 왕비의 기일과 왕릉 및 국가 기일에 입는 의복에 대한 것을 기록하였다. 조선은 국초부터 유교를 숭상하고 조상숭배를 으뜸으로 하였으므로 궁실의 왕비로서 조상의 기일과 복식에 큰 관심을 가졌던 것으로 보인다. 이 두 책은 특히 복식사 연구에 귀중한 자료가 된다.","a":"국기복색소선 및 사절복색자장요람","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636282.jpg"},{"q":"유송(劉宋)시대(A.D.420~478) 서성(西城)의 강량야사(畺良耶舍)가 번역한 것으로 ○○○○이 머물고 있는 극락세계로 가는 길을 보여 주는 가장 널리 알려진 경전에 속한다. 특히 이 경은 『불설○○○경(佛設無量壽經)』, 『불설아미타경(佛說阿彌陀經)』과 함께 정토삼부경(淨土三部經)*으로 꼽힐 만큼 정토사상을 대표하는 경전이다. 명(明)의 석도부(釋道孚)가 간행한 것으로 명(明)의 인종(仁宗)이 즉위하여 그의 선황(先皇) 태종(太宗)의 명복을 빌기 위하여 1451년에 간행되었지만 조선에서 간행하게 된 이유는 알 수 없다.","a":"어제관무량수불경","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638886.jpg"},{"q":"1) ｢會盟錄｣ 크기는 108.5×81cm이고, 유리가 없는 액자 형태로 보관되고 있다. 태종이 즉위한 뒤 조선왕조 개창에 공이 있는 開國功臣과 제1, 2차 왕자의 난에서 공이 있는 定社·佐命功臣들을 모아, 여러 神에게 제례를 지내고 공신들과 그 후손들을 잘 보살펴주겠다는 서약을 한 문서로, 한 장의 목판본 문서로 되어 있다. 상단에 왕의 祝文이 새겨져 있고(“維歲次甲申(1404)十一月己亥朔十六日甲寅 朝鮮國王臣李 謹率開國·定社·佐命功臣等 敢昭告于皇天上帝·宗廟·社稷·山川百神之靈 伏以國之有君---”), 하단에는 이 행사에 참여한 공신의 명단이 새겨져 있다.","a":"함양 하륜부조묘 고문서 일괄","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643111.jpg"},{"q":"번암(樊巖) ○○○은 본관이 평강(平康)으로 정조 재위 시 명재상이다. 정조의 특명으로 사노비(私奴婢)의 폐를 교정하는 절목을 마련했다. 이 사노비절목은 사노비의 수효를 감소시켜 1801년에 사노비 혁파를 가능하게 하였다. 1790년부터 3년간 좌의정 독상(獨相)으로서 정사를 오로지 하고, 수원성역(水原城役)을 담당하다가 1798년 사직했다. ○○○ 선생의 묘는 홀로 안장되어 있다. 두 부인 묘소는 안성시에 위치하고 있다. 봉분 옆에 묘표가 건립되어 있으며, 봉분 앞에는 혼유석, 석상, 향로석, 망주석과 석양(石羊)이 설치되어 있다.","a":"채제공선생묘","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645955.jpg"},{"q":"제작 연대가 분명하고 만든 스님의 이름까지 알 수 있는, 조선 시대 후기의 대표적인 중형 나무 불상 가운데 하나이다. 이 ○○○의 본존 부처는 앉은 자세에서 오른손을 곧게 펴서 무릎 아래로 내린 이른바 항마촉지인(降魔觸地印)이라는 석가모니불 특유의 손갖춤(수인)을 하고 있어 ○○○○○로 불려 왔다.","a":"안성칠장사대웅전목조석가삼존불좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637785.jpg"},{"q":"이 일기는 파평 윤씨 충헌공파 문중에서 소장하고 있는 사료로, 25책 125권이다. 조선 경종 1년∼2년(1721∼1722) 경종의 왕위계승문제를 둘러싸고 노론과 소론 사이에 일어난 당쟁의 옥사를 기록한 것으로 필사본이다.","a":"신임일기","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661503.jpg"},{"q":"임진왜란 당시 금산전투에서 칠백의사와 함께 전사한 노씨 3의사(義士)로 불리는 노응환(盧應晥), 노응탁(盧應晫), 노응호(盧應皓) 3형제가 출생한 곳이다. 노응환․노응탁 형제는 중봉 조헌의 문인으로 1592년 임진왜란이 일어나자 스승을 따라 청주성 전투와 금산 전투에 참가하였다가 금산에서 순절하였다. 순조 31년(1831) 증직(贈職)과 함께 명정(銘旌)을 받아 이곳에 정려를 건립하였다. 노응호는 19세의 나이로 두 형을 따라 청주성 전투에 참전하였다가 조헌의 명으로 호서지역의 군량을 모으기 위해 진영을 떠나게 되었다.","a":"공주귀산리만경노씨삼의사생가지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651954.jpg"},{"q":"○○○○○ 안에 있는 이방·호방·예방·병방·형방·공방 6방의 건물 중 이방청으로 조선 중기의 관청 건물이다. 조선 효종 5년(1654)에 유수 정세규가 세웠고, 정조 7년(1783)에 유수 김노진이 건물 내부를 고쳐 괘홀당이라고 불렀다. 나무로 된 1층의 기와집으로 ㄷ자형이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 여러 차례 고쳐서 옛날 관청의 모습을 잘 알 수는 없으나, 조선시대 지방의 이방청을 알 수 있는 귀중한 자료이다.","a":"강화유수부 이아","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637055.jpg"},{"q":"조선시대 관아의 하나로 강화지방의 중심업무를 보던 ○○이다. 영조 45년(1769)에 유수 황경원이 현윤관이라 이름을 붙였으며, 여러 차례 보수해서 본래의 모습을 찾아볼 수 없다. 앞면 8칸·옆면 3칸의 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. ‘명위헌(明威軒)’과 ‘이관당(以寬堂)’이라는 현판은 당시의 명필이자 학자인 백하 윤순(1680∼1714)이 썼다.","a":"강화유수부 동헌","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637053.jpg"},{"q":"1900년대에 지은 것으로 추정되는 집이다. 사랑채 비슷한 별채와 안채, 행랑채로 이루어져 있다. 안채는 동북쪽에 있으며 행랑채는 북쪽에 있다. 누마루에는 ‘일관정’이라는 현판이 붙어있다. 안채는 조선 후기의 상인인 ○○○이 지은 별장이라고 전하는데 당시 규모가 큰 상인들의 생활상을 살펴볼 수 있는 집이다. 특히 가옥주변의 조경은 한국의 멋이 물씬 풍기는 아름다운 경관을 가지고 있다.","a":"성북동이종석별장","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658045.jpg"},{"q":"범종은 법당 왼쪽의 범종각에 보관되어 있는 종이다. 원래는 무안 원갑사의 종이었으나 폐사되자, 함평의 용천사를 거쳐 한국 전쟁의 혼란을 피해 1967년 현 위치에 옮겨진 것이라 한다. 형태를 보면, 종을 매다는 고리인 용뉴는 2마리의 용이 서로 반대 방향을 향하고 있고, 용의 다리와 종을 연결하여 무게를 지탱하고 있다. 몸통 윗부분은 2줄의 띠를 두르고 그 안에 8자의 범자를 새겼다. 그 아래에는 사각형의 유곽이 있고, 안에 돌출된 9개의 유두가 배치되어 있다. 유곽과 유곽 사이에는 보살입상을 양각하였다.","a":"함평보광사범종","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640105.jpg"},{"q":"거창에서 금천으로 가는 국도의 오른쪽 능선에 있는 5기의 무덤들이다. 현재 2기의 무덤에 대해 복원 및 정화사업이 이루어져 거대한 봉분의 외형을 갖추고 있으나 나머지 3기는 파괴된 상태로 남아 있다. 그리고 무덤의 주변에 흩어져 있는 각종 경질토기들은 이들 무덤이외에도 많은 무덤이 있었음을 말해준다. 정식 발굴조사가 이루어지지 않아 정확한 연대는 알 수 없으나 수습된 토기조각들과 대형봉분의 존재로 보아 가야 후기에 속하는 것으로 추정된다.","a":"거창개봉고분","c":"시도기념물","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654986.jpg"},{"q":"○○○ 수안골에 있는 ○○○○○으로 19세기 말에 지은 것이다. ○○○○○은 지붕의 용마루 끝에 구멍을 내어 집안에서 생기는 연기를 빼내고 빛을 받아들이는 가옥이다. 앞면 3칸·옆면 2칸 규모에 외양간이 1칸 덧붙었다. 방은 모두 심을 넣은 흙벽이고, 봉당과 부엌·외양간은 널벽으로 지었다. 앞면 가운데 칸에 두짝의 널대문을 달고 앞칸에 흙바닥 출입구인 봉당을, 뒷칸에 마루를 갖춘 경북지방 ○○○○○의 골격을 갖추었다. 여기에 마루 뒷쪽을 막아서 좁은 도장방을 설치한 형식은 강원특별자치도 남부지방 ○○○○○의 요소가 섞인 것이다.","a":"분천리까치구멍집","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658828.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라 성덕왕 23년(723)에 삼법이 지었으며, 문성왕 2년(840)에 진감국사가 다시 지었다. 원래 이름은 옥천사였으나 정강왕(재위 886∼887) 때 ○○○로 이름을 바꾸었다. 임진왜란 때 불타 없어진 것을 벽암이 조선 인조 10년(1632)에 다시 지어 오늘에 이르고 있다. ○○○○○은 숙종 13년(1687)에 성안대사가 지었고, 숙종 36년(1710)에 신민대사가 수리하여 오늘에 이르고 있는 건물이다. 앞면 5칸·옆면 2칸으로 지붕은 옆면이 사람 인(人)자 모양인 맞배지붕이다. ○○○은 지장전, 업경전이라고도 한다.","a":"하동 쌍계사 명부전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641630.jpg"},{"q":"이 민가는 조선시대 후기 건물로 낭성면 ○○○의 신방호(申邦浩)씨가 살던 가옥을 원래의 모습 그대로 이전 복원한 집으로 전형적인 중부지방의 초가이다. 가옥의 구조는 ‘一’자집 형태의 안채와 대문이 있는 광채가 있다. 상량문이 없어 정확한 건립연대는 파악할 수 없으나, 조선후기 건물로 추정된다. 현재의 건축은 1992년 문의 문화유산단지를 조성하면서 1994년 ○○○에서 이건(移建)하였으며, 당시 소유자인 신병호씨의 증언대로 5대조가 대대로 살아온 집이라고 하면 최소 200여 년 전 정도였을 것으로 추정할 수 있다.","a":"청주 관정리 고가","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660784.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. ○○○○이 『반야심경』에 주석을 단 것으로, 흔히 ‘마하반야바라밀다심경해’로 알려져 있다. 중생의 헛된 생각을 바로 잡아 불생불멸의 경지에 이르도록 하여 중생으로 하여금 본심본성을 보이기 위한 경전이다. 책의 뒷부분에는 1411년 전라남도 고창의 문수사에서 판을 새겼다는 기록이 나오는데, 이 판본이 국내에 만들어진 유일한 것으로 알려져 있다.","a":"보림사사천왕상복장대전화상주심경","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813515500.jpg"},{"q":"○○○은 약 700평의 대지에 대문채, 사랑채, 안채, 가묘, 고방채와 기타 3동의 부속채로 구성되어 있다. ○○○ 사랑채는 정면 5칸 측면 1칸에 전후퇴가 있고 우측부터 큰 사랑방 ＋작은 사랑방 ＋ 안마루 ＋ 중문간 ＋ 중 사랑방으로 짜여 전퇴에는 툇마루, 후퇴에는 벽장 등의 수장 공간이 부설되어 있다. 작은 사랑방과 안마루 사이에는 세 짝의 세살문을 달았으며 안마루 뒷벽은 판벽으로 하여 수장시설을 부가하였다. 큰 사랑방에도 중방위에 벽장을 시설하였으며 배면에 안채로 통하는 외짝 여닫이문을 달았다.","a":"김해 시례리 염수당","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665963.jpg"},{"q":"이 고분은 1972년에 진종남, 진규 두 사람이 고분에서 출토된 유물을 신고하면서 알려진 유적이다. 이 고분에서 수습되어 신고된 유물은 총 41점으로 고려청자 9점, 고려백자 16점, 송백자 9점, 토기 1점, 벼루 1점, 청동기 3점, 철제품 2점 등이다. 또한 2016년 발굴조사로 수정제 구슬 1점이 더 출토되었다. 이러한 유물은 일반적인 계층보다 상층계층에서 사용되는 유물들로 피장자의 신분이 높았음을 알 수 있다.","a":"동해 삼화동 고려고분","c":"시도기념물","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019050214294800.jpg"},{"q":"경남 함양군에 있는 ○○○○은 해발 508m 정도의 ○○○ 정상을 둘러 쌓은 테뫼식 산성이다. 자연석을 이용하여 성벽을 쌓아 올렸는데 현재 훼손이 심하여 확실히 알 수 없지만 조선시대 이전에 만든 것으로 추정한다. 인근에 있는 사근산성과 황석산성 등을 고려한다면 삼국시대나 고려시대에 이 지역 주민들의 방어용으로 쌓은 것으로 보여 산성 연구에 중요한 자료가 된다. 이 산성은 현재 거의 붕괴된 상태이며 부분적으로 흔적이 남아 있다. 그 중 양호한 상태의 남벽은 자연석을 이용하여 쌓았으며 남아 있는 성벽은 높이 2m, 길이 50m이다.","a":"함양마안산성","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656125.jpg"},{"q":"율곡은 조선 중기의 대학자로서 서인, 노론의 학파에서 宗主로 삼는 인물이다. ○○○○는 이런 인물이 사서의 각 구절 해석에 대해 구체적으로 어떤 입장을 취하고 있었는가를 알 수 있는 중요한 자료이다. 그중에서도 특히‘紅圈 黑圈 등 그가 주자 및 여타 학자들이 분석하던 내용에 대한 의문을 제기하거나 동감하는 여러 가지의 표시를 하고 있는 소주권평 부분이 주목된다. 원본이었던 필사본이 현재 남아 있는지 알 수는 없지만, 이를 간행하는 매개가 되었던 이 책판은 매우 중요한 자료라고 볼 수 있다.","a":"사서석의 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666456.jpg"},{"q":"○○○○○은 조선 명종(재위 1545∼1567) 때 공조좌랑을 지낸 김경우가 관직에서 물러나 은거하기 위해 지었다는 ○○○이라는 정자 주위의 숲을 가리킨다. ○○○에 올라서면 옥녀봉이 눈에 뜨이고, 황룡강과 탁 트인 들판이 보인다. 정자 주위를 60여 그루의 배롱나무가 둘러싸고 있으며, 소나무가 숲을 이루고 있어 여름이면 경치가 더 아름답다. 정자에는 하서 김인후, 고봉 기대승 등 명현들의 시가 현판에 새겨있다.","a":"장성 요월정 원림","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654193.jpg"},{"q":"충청남도 홍성군 결성면 금곡리에 있는 신금성은 해발 40∼60m의 평지에 가까운 낮은 구릉에 쌓은 성으로, 안쪽의 내성과 바깥쪽의 외성으로 구분되는 2중성이다. 전체 성벽의 길이는 645m, 높이는 2∼3m이다. 성벽은 북·서·남쪽이 가장 잘 남아있는데, 북쪽과 남쪽에는 문터가 있었을 것으로 추정된다. 성안에서는 토기류 등 많은 유물이 출토되었다. 평탄한 구릉에 쌓여져 평지성에 가까운 이 성은 방어용보다는 지역 집단을 통치하기 위하여 만들어진 것으로 보이며, 지방 소재지의 일종으로 읍성의 형태를 보여주는 중요한 유적으로 여겨진다.","a":"홍성신금성","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653065.jpg"},{"q":"○○○는 927년(태조 10) 동수전투에서 전사한 ○○○ 장군의 공적을 기리기 위해 1832년(순조 32)에 건립된 석비로 고려의 삼국 통일과정에서 왕건군과 견훤군 사이에 일어났던 동수전투의 흔적을 이해하는데 상당한 가치가 있다.","a":"신숭겸영각유허비","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659512.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안8분면 바닥가부좌상이다. 인물의 뒤편에는 등받이역할을 하는 의자를 배치한 후 가장자리에 연화당초문계열문양이 그려진 법피를 걸쳐 장식하였다. 그리고 인물 옆으로는 서책을 쌓아올렸는데 맨 위편의 책은 펼쳐져 있으며 그 위로 안경이 묘사되어 있다. 화면 향우측과 좌측에는 각각 주지묵서의 화제와 영찬이 있으며 배면에는 묵서화기가 있다. 이로써 이 작품이 1859년 화사 의운당 자우(畵師 意雲堂 慈友)가 조성하였음을 알 수 있다. 화면크기는 가로 78.8cm, 세로 120.0cm이다.","a":"성곡당 신민 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643002.JPG"},{"q":"조선 전기의 왕족인 정도공 ○○○의 묘소이다. 그는 세종의 12남이며 어머니는 혜빈 양씨이다. 세종 23년(1441) 왕이 왕비와 함께 온수현(溫水縣) 가마곡(加磨谷)에 행차하였을 때 궁궐의 수비를 관장한 공으로 ○○○에 봉해졌다. 1455년 세조가 즉위하자 금성대군·영풍군·혜빈 양씨와 함께 역모를 꾀하다가 금산에 유배되었다. 그 뒤 토지와 노비를 몰수 당하고 다시 함양으로 옮겨져 유배생활을 하다가 세조 3년(1457)에 생을 마감하였다.","a":"세종왕자한남군묘역","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656025.jpg"},{"q":"○○○ 대웅전 앞마당에 자리하고 있는 고려시대의 석탑이다. 기단(基壇)을 1층으로 마련하여 전체의 무게를 버티게 하고 그 위로 6층의 탑신(塔身)을 올려 놓았다. 기단의 네 면과 탑신부의 각 몸돌은 모서리마다 기둥모양을 새겼다. 얇아 보이는 지붕돌은 밑면에 5단씩의 받침을 두었고, 처마는 양끝에서 가볍게 들려있어 경쾌한 멋이 흐른다. 꼭대기에는 머리장식이 대체로 잘 남아 있다. 전체적으로 탑신의 2층 몸돌부터 급격히 줄어들고, 3층 지붕돌 역시 2층에 비해 폭이 좁아져 비례감이 조금 떨어진다.","a":"선운사육층석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639401.jpg"},{"q":"임진왜란 때 많은 공을 세운 농포 정문부(1565∼1624)가 가족들의 피난처로 사용하던 곳이다. 전쟁 후 고향인 진주로 돌아가면서 손녀 사위인 사위당 이강에게 주었는데, 현 소유주의 6대조가 사들여 오늘에 이르고 있다. 거북 모양의 땅 위에 거북 모양으로 건물을 배치하였다. 거북의 앞발에 해당하는 곳에 별당과 방앗간을 두었고, 머리 부분에 속하는 앞면에는 누에를 치던 잠실을 두었다. 꼬리 부분에는 화장실을 배치하였다.","a":"포항 오덕리 애은당 고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658771.jpg"},{"q":"○○○은 조선시대 관아에서 음악과 연희를 담당하던 기관으로 음악 강습을 하고 관아의 행사에서 공적 역할을 수행했던 기관이다. ○○○○○은 1939년에 설립되었는데 조선시대 전라좌수영 소속 취방(吹房)의 후신으로 보이며, ○○지역 문화예술사의 전개와 긴밀하게 연결된 조직으로 전승되었다. ○○○자료는 선대 구성원을 기록한 무진년(1928년)선생안 등 선생안 2점, ○○○수혜서(樂工廳樹惠序)(1939년), 무진년○○○동반일동현판[희사기념] 등 현판 4점으로 ○○○ 자료로서는 매우 희귀하고 학술적 가치가 있다.","a":"여수 악공청 관련자료일괄","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658433.jpg"},{"q":"숙종 10년(1684)에 서재(서당)을 운영하기 위하여 창립한 학계의 운영에 관한 비석으로 1714년에 건립한 철비이다. 앞면에 학계참여 인명(11명)과 학문격려를 하는 글이 있다. 당초 이 학계는 박윤순의 아들 6형제가 중심이 되어 시작한 뒤 먼 인척들 5명이 참가했던 것으로 보인다. 뒷면에는 학계에서 구입한 재산 목록(토지)을 기록하였다. 이를 통해 학계창립 이후 1714년까지 30년간 25필지 1.7결의 재산을 모은 것을 알 수 있다.","a":"진도칠전리학계철비와 노암재","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654360.jpg"},{"q":"남사마을 중앙에 자리잡은 가장 큰 집으로 안채와 외양간채, 사랑채가 안채를 중심으로 ㅁ자형 평면을 갖추고 있으며 1930년대 지은 집이다. 안채는 앞면 6칸·옆면 3칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 뒤쪽 툇마루의 폭이 커서 각 방 뒤편으로 물품을 보관하기 위한 벽장을 두었다. 부엌과 건넌방 뒤에는 따로 방을 만들었다. 동향한 아래채는 앞면 4칸·옆면 2칸으로 지붕은 앞에서 볼 때 사다리꼴을 한 우진각지붕으로 꾸몄다. 남쪽에 개방된 대청이 있고 이어 온돌방을 두었다.","a":"산청남사리최씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664094.jpg"},{"q":"석굴이 있는 미륵사터 경내에서 동쪽으로 200m쯤 떨어진 곳에 자리한 고려시대 3층 석탑이다. 이곳이 원래의 터로 추정되는데 절터와 멀리 떨어진 곳에 왜 탑을 세웠는지는 알 수 없다. 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 머리장식을 얹은 모습이다. 위 ·아래층 기단과 탑신의 몸돌에는 기둥 모양을 조각하였다. 탑신은 1층 몸돌에 비하여 2층 몸돌의 높이가 많이 줄어들었고, 지붕돌은 밑면의 받침이 4단씩이다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만 남아 있다.","a":"충주 미륵대원지 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638447.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 고려 충선왕 5년(1313)에 처음 세운 후 조선 태종 11년(1411)에 화재로 없어진 것을 태종 13년(1413)에 다시 지었다. 그 후 여러 차례의 수리가 있었으며, 인조(재위 1623∼1649) 때에는 크게 늘려지어 웅장한 규모를 갖추게 되었다. 화부산 아래 경사진 곳에 위치하여 위쪽에는 제향공간인 대성전(보물)을, 아래쪽에는 강학공간인 명륜당을 배치한 전학후묘의 형태를 이루고 있다.","a":"강릉향교","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638106.jpg"},{"q":"이 불상은 조선 후기 석조불상의 재료인 불석(佛石, 제오라이트)으로 조성되었는데, 이 석재는 흰색에 무른 재질이다. 전체 불상의 높이가 81.5㎝에 이르는 제법 큰 규모이며, 최근에 개금하여 상태가 매우 양호하다. 불상의 밑바닥에는 복장공이 마련되어 있었는데, 개금 수리를 위한 사전조사에서 복장주머니[腹藏囊], 육자대명왕진언(六字大明王眞言) 2매, 다라니(陀羅尼) 2매, 오방도(五方圖) 등이 발견되었다. 2010년 3월 11일에 경상남도 유형문화유산으로 지정되었고, ○○○에서 관리해오고 있다.","a":"양산 법천사 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110514372000.JPG"},{"q":"이 그림은 조선 인조대(仁祖代)에 약 70세 이상의 고령 관리들의 사적인 계원 모임을 그린 것이다. 상단에 회화식 전서로 제목을 쓰고, 그림 아래로 장유(張維)의 기문(記文), 좌우로는 비단에 덧대어 쓴 이경직(李景稷)의 서문이 있으며, 서문과 기문 아래에는 이경석(李景奭)이 기록한 계원들의 관직, 성명, 자(字), 호(號), 생년월일, 본관과 함께 참석한 자제들의 관직, 성명 등이 기록된 좌목(座目)으로 구성되어 있다.","a":"남지기로회도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636742.jpg"},{"q":"조선 후기의 실학자이며 과학사상가인 담헌(湛軒) ○○○ 선생의 묘소이다. 청나라에 사신으로 가는 작은 아버지 홍억을 수행하여 여러 학자들과 친교를 맺었으며, 서양 선교사들을 찾아가 서양문물을 보고 접했다. 이덕무·박지원·박제가 등과 어울려 북학파를 형성하였는데, 북학파의 선구자로 특히 천문학에 관심을 기울여 지전설을 주장했으며, 저서로는『담헌서』가 있다. 묘소는 천안시 수신면 장산리에서 속창리로 통하는 도로변에 위치하고 있는데, 묘의 앞에는 상석·망주석·비석이 서 있다.","a":"홍대용선생묘","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652860.jpg"},{"q":"○○○는 영광 김씨들이 중심이 되어 후손들의 교육과 인재양성을 위해 조선 순조 4년(1824)에 지은 건물이다. 사당인 용강사, 강당인 ○○○, 내삼문, 외삼문, 관리사, 창고 등으로 이루어져 있다. 전체적인 모습은 가장 윗부분에 용강사가 있고 아래로 ○○○가 있으며 ○○○ 앞으로 관리사와 창고가 대칭으로 자리잡고 있다. 고종 19년(1882)에 사림들이 지은 용강사는 나옹 김광범·우수당 김성범·죽옹 김정서·우수 김상범·학남 김정의 위패를 모시고 있다. 앞면 3칸·옆면 1칸 크기로 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다.","a":"월산재","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662006.jpg"},{"q":"고려시대의 문신인 ○○○ 조충(1171∼1220)의 묘지석이다. 묘지석은 죽은 사람의 인적사항이나 묘소의 위치 등을 기록하여 무덤에 묻어놓는 것이다. 이 지석의 재료는 청석으로, 표면을 거칠게 다듬어 앞면에만 글을 새겼다. 앞면의 가장자리에는 덩굴무늬를 두른 후 그 안쪽에 테두리선을 그었다. 전체가 네 조각으로 갈라지고, 패인 곳이 많아 그 내용을 정확하게 알아보기 어려우나, 조상들에 대한 소개, 그의 생애, 인품과 일화, 가족관계 등을 적고 있는 것으로 보인다. 조충 선생이 세상을 뜬 고종 7년(1220)에 만든 것이다.","a":"문정공조충지석","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638140.jpg"},{"q":"현재 서당이 있던 자리는 원래 한강 정구가 선조 24년(1591)에 조그만 글방을 지어 성리학을 가르치던 곳이다. 200년이 지난 정조 20년(1796)에 제자들이 집을 짓고 ○○○○이라 하였다. 정구는 조선 중기 문신이며 학자이다. 그는 관직보다는 학문에 전념하였고, 광해군 즉위 후에는 지방 학문을 융성시키고 민중을 교화하기 위해 중앙직보다 지방직을 맡았다. ○○○○은 오천마을의 안쪽 산기슭에 남향하여 자리잡고 있다. 서당의 정면에는 최근 복원한 일각문이 있고, 입구의 좌측에는 정구의 유허비가 서 있다. 건물은 견실한 구조로 규모는 앞면 5칸·옆면 2칸이다.","a":"사창서당","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662821.jpg"},{"q":"○○○에 보존되어 있는 아미타○○○○○화인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색하여 그린 이 탱화는, 중앙의 높은 대좌에 아미타여래가 앉아있고, 대좌 전면에 협시보살상이 위치하며, 그 좌우측에 사천왕이 2구씩 각각 배치되어 있다. 그리고 본존 좌우측에는 두광을 갖춘 8대보살과 권속들이 배치되어 있다. 화면의 아래쪽 부분에 먹으로 쓴 화기(畵記)가 있으나, 박락으로 인해 부분적으로나 확인이 가능하다. 조선후기(18세기) 불화로서는 뛰어난 수작으로, 조선시대 불교회화사 연구에 중요한 학술적 자료로 평가된다.","a":"양산 통도사 극락회상탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642348.jpg"},{"q":"ㅁ자형 평면을 갖춘 집으로 북쪽 5칸·남쪽 4칸·동쪽 3칸으로 구분되어 있다. 1978년 대청마루를 개조할 때 나온 기와의 기록에 따르면 조선 중종 6년(1511)에 지었다고 한다. 이곳은 한말까지 이언방(伊彦坊)이라는 관청이 있었던 곳이다. 동대라고도 불리는 이 건물은 이언방의 사무실로 지은 듯하며, 남원부사의 별장이었다고 하여 동헌이라고 부르기도 한다. 풍수설에 따르면 남원 48방의 명당을 손꼽을 때 그 첫째가 이언이라고 할만큼 이름난 곳이다. 아래채는 본래 초가였으나 근래에 기와를 얹었다.","a":"윤영채가옥","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661745.jpg"},{"q":"경상북도 안동시 북후면 장기리 자연암벽에 새겨진 불상으로, 이중으로 된 연꽃무늬 대좌(臺座) 위에 앉아 있다. 마애○○○○을 중심으로 양옆에 보살이 있는 삼존불(三尊佛)로 추정된다. 얼굴에는 미소를 띠고 있으며, 목에는 3줄로 새겨진 삼도(三道)가 뚜렷하다. 오른쪽 어깨를 드러내고 왼쪽 어깨를 감싼 옷을 입었고 앞가슴에는 치마의 띠매듭이 보인다. 오른손은 오른쪽 무릎 위에 올리고 왼손은 아랫배 부분에서 작은 약그릇을 받쳐들고 있다. 마애불에서는 드물게 삼존불 형식으로 만든 것으로 이런 유형의 불상을 연구하는데 중요한 자료가 된다.","a":"옥산사마애약사여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640636.jpg"},{"q":"○○○○은 1650년경 창건된 ○○○원이 창건 200여년 후 퇴락됨에 따라 1856년 당초 서원 터에서 500여 미터 떨어진 북쪽 산기슭에 지금의 ○○○○을 건축하고 淸敏公 盧抃素(노변소), 晩翠公 參奉 盧沈, 節孝公 進士 盧弘彦 3인을 合享하다가 대원군의 서원 훼철시 피해를 입었다. ○○○○의 현 배치형태는 튼□자 형으로, 남북축선 상에 대문채와 강당을 두고, 그 정면 좌우에 관리사와 영사정이 자리 잡고 있다.","a":"창녕 소곡서당","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665531.jpg"},{"q":"『○○○○○』은 조선시대 대표적인 여류시인 허○○○이 남긴 210여수의 작품을 모은 시문집으로, 이를 동생인 『홍길동전』의 작가 허균이 목판으로 간행하였다. 허○○○의 본명은 초희(楚姬)이며, ○○○은 호이다. 아버지인 허엽과 형제인 허성, 허봉, 허균은 ‘초당오문장(楚堂五文章)’이라는 이름이 붙을 정도로 문장가의 가문이었다.","a":"난설헌시집목판초간본","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638182.jpg"},{"q":"○○○○○은 현재 ○○○ 미타전에 봉안된 불상으로, 조성원문에 의하면 원래 충청남도 아산 축봉사에서 13세기에 조성된 아미타불상이다. 이 불상과 함께 발견된 복장유물은 조성 및 개금기 3점을 비롯해 모두 41건 58점에 달한다. 그 중 조성 및 개금기 3건과 대방광불화엄경 사경 7건, 대방광불화엄경 인본 15건 등 총 25건은 불상과 함께 국가지정문화유산으로 지정 신청하였고, 나머지 16건은 절첩본인경(折帖本印經) 1건, 선장본인경(線裝本印經) 4건, 목판인경(木版印經) 2건, 다라니인본(陀羅尼印本) 8건, 기타 복장물 1건 등으로 서울시 유형문화유산으로 지정하였다.","a":"개운사 목 아미타불좌상 복장일괄","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2595159.jpg"},{"q":"오천 정씨 집안의 묘와 강의공 정세아의 무덤가에 세운 비를 보호하기 위하여 지은 집과 비각이다. 조선 인조 15년(1637)에 진주목사 정호인이 처음 지었다고 한다. 지금의 건물은 후에 다시 지은 것으로 보이며, 영천댐 건설로 인하여 1976년 지금의 위치로 옮겨 지어졌다. 강의공 정세아는 임진왜란(1592) 때 의병대장에 추천되어 많은 공을 세웠다. 그러나 그 공으로서 상을 바라지 않고 관직을 떠나 시골에서 제자를 기르며 학문을 닦은 덕망이 높은 선비였다. 경내에는 ○○○, 신도비각 등이 있는데 모두 단순하고 소박하게 지은 건물이다.","a":"하천재<부비각>","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640368.jpg"},{"q":"공산성(公山城) 내의 ○○○에 있는 조선시대의 범종이다. ○○○는 19세기에 편찬된 『공산지(公山誌)』에 따르면 백제시대에 창건되었다고 하나 절 주변에 흩어져 있는 석탑 재료가 고려 초기의 유물이므로 그때 창건되었을 것으로 추정된다. 또 일설에는 조선 세조 4년(1458) 세조의 명으로 창건되었다고도 한다. ○○○ 범종의 종신부(鐘身部)에는 주종기(鑄鐘記)가 있어 종의 제작연대와 만든 장소, 장인을 알 수 있다.","a":"공주영은사청동범종","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639275.jpg"},{"q":"○○○는 통일신라 진성여왕 7년(893)에 도선국사가 남원고을 터의 기가 강하여 이를 누르기 위해 세운 것으로 전한다. 원래 절의 이름을 ‘대곡암’이라 하였으나 조선 철종 때 ‘○○○’로 바꾸었다. 절 경내에 있는 건물로는 ○○○, 칠성각, 선방, 요사 등이 있으며, ○○○은 철종 때 보수한 것이다. ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 안에는 아미타불을 모셨으며, 신장탱화, 후불탱화, 지장탱화를 모시고 있다.","a":"대복사극락전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661663.jpg"},{"q":"남양홍씨 문중의 ○○와 홍호 부자의 무덤으로 고려시대 만들어졌다. 무덤은 돌이 쌓은 높이가 50㎝로서, 앞면 5개·옆면 7개의 돌이 세워졌다. 묘비, 제단, 문인상은 1726년에 설치된 것으로, 특히 앞의 제단은 연꽃과 연꽃잎이 섬세하게 조각되어 있다. ○○ 계원리 고려 무덤은 서기 970년 경에 세워진 무덤으로 전국의 고려 무덤 중 가장 오래된 무덤이다.","a":"진주 홍의 묘역","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664367.jpg"},{"q":"조선시대 관아의 누각건물로 19세기 초에 지어진 것으로 보인다. 원래 ○○현 객사 누각인 한벽루 옆에 나란히 세워졌던 2층 누각이었는데, 충주댐 공사로 인하여 지금의 위치로 옮겨지었다. 앞면 3칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양의 화려한 팔작지붕집이다. 1단의 기단 위에 세웠는데, 1층은 둥근 기둥을 세우고 그 사이를 흙벽으로 막아 창고로 사용한 듯하다. 2층은 앞면만 둥근 기둥을 세우고 나머지는 네모 기둥을 세웠으며 난간을 둘렀다. 동남쪽으로 3단의 나무계단을 설치하여 오르내릴 수 있게 하였다.","a":"제천 청풍 응청각","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638527.jpg"},{"q":"일반적으로 모전석탑은 통일신라시대 이래로 만들어 졌다. 전체적인 형태가 남아 있지 않아 모전석탑인 석단인지 정확히 알 수가 없고, 또한 조성된 정확한 연대도 알 수 없으나 고려시대 전기의 것으로 추정된다. 금수산 자락의 산 중턱의 ○○사지에서 서남향 약 50m지점의 암반 위에 화강암재로 조성된 모전석탑으로 추정되는 1기의 석탑 형태의 방형 석단이 있다. 1960년대 학계에 모전석탑으로 알려져 희소성과 중요성은 인정되어 왔으나 본격적인 학술조사가 진행되지 못한채 원형이 크게 훼손되어 방치된 상태이다.","a":"제천 교리 방단적석유구","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638729.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 연대는 알 수 없으나 고려시대로 보인다. 조선 성종 13년(1482)에 지금 있는 자리로 옮겨 지었으며 이후 여러 차례 수리하였다. 건물 배치는 뒤쪽에 ○○○과 내삼문, 앞쪽에 명륜당을 일직선상으로 하고 좌·우에 동재와 서재 등을 배치한 전학후묘의 형식이다. ○○○은 앞면 3칸·옆면 3칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 중국과 우리나라 유학자의 위패를 모시고 있다.","a":"해남향교대성전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662014.jpg"},{"q":"○○○은 조선 명종(재위 1545∼1567) 때 미모가 뛰어난 ○○부사의 외동딸 윤동옥의 정절을 기리기 위해 지은 사당이다. 윤동옥은 유모의 꾀임에 빠져 영남루에 달구경을 갔다가 통인 주기에게 정조를 강요당하게 되자, 스스로 목숨을 끊어 정절을 지켰다고 한다. 이 지방 사람들은 아랑의 넋을 위로하고 뭇여성의 본보기로 삼고자 해마다 4월 16일에 제사를 지내고 있다.","a":"밀양 아랑각","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663845.jpg"},{"q":"정면 7칸, 측면 1칸 규모에 겹처마, 맞배지붕인 본 건물은 현재 ○○○ 대웅전 서쪽 상단에 위치하고 있는 부속 불전의 하나로, 적어도 1706년 이래로 존속했던 위치에서 변함없이 존속해 온 건물이다. 1902년에 조사된 자료에 의하면 당시까지는 중앙의 천태문(天台門)을 중심으로 좌우에 각각 ○○전과 ○○○이란 별개의 건물이 서 있다가, 1905년 11월～1906년 11월까지 약 1년에 걸친 공사 끝에 현재의 모습으로 새롭게 단장되었다.","a":"범어사 팔상·독성·나한전","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636722.jpg"},{"q":"임진왜란 때의 의병장인 김덕령 장군과 관련된 유적지로, 무기를 만들던 곳이다. 무등산 꼭대기에서 서북쪽으로 뻗은 능선이 비교적 완만한 경사지의 평탄한 곳에 자리하고 있으며, ‘주검동(鑄劍洞)’이라 불리우기도 한다. 이곳은 위아래 2단으로 돌을 쌓고, 제철 쓰레기를 처리하기 위한 급경사면을 만든 후 제철, 단조(緞造:광석에서 금속을 뽑아 두드려 만드는 과정)에 이르기까지 철기 생산에 필요한 기본과정과 시설을 배치해 놓았다. 제철로는 작은 판돌과 깬돌을 이용하여 직사각형으로 만든 후 그 안을 점토 등으로 다졌다.","a":"금곡동제철유적","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645768.jpg"},{"q":"○○○는 목포시내가 한눈에 내려다 보이는 유달산의 동남쪽 중턱에 있다. 목포시에서 발행한 『내고장전통가꾸기』(1981년간) 및 목포시사(1987년간, 인문편) 등에 의하면, 1913년 음 4월8일, 노대연(盧大蓮)선사가 창건하였다고 기록되고 있다. 현재 ○○○의 건물로는 ○○○○○을 봉안한 법당 1동과 지장보살 및 시왕상을 모신 명부전 1동, 요사채 2동, 산신각 및 종각 각1동과 3층석탑(3년전 조성) 1기가 있다. 적색의 필사본인 조성발원문(14㎝×25㎝)에 따르면 1678년(숙종 4) 만덕산 백련사에서 조성하였음을 알 수 있다.","a":"목포달성사목조아미타삼존불좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640156.jpg"},{"q":"○○○○는 공주시 금학동(金鶴洞) 남산에 있는 ○○○의 터로, 서북쪽의 망월산에 있는 서○○○와 마주 보고 있다. 서혈사와 함께 백제시대에 창건된 사찰로 추정되며, 고려의 고승 정진(靜眞)이 출가한 명찰(名刹)로 알려져 있다. 절터에서는 연화문(蓮花文)기와·명문(銘文)기와와 육조(六朝)양식의 금동보살입상(金銅菩薩立像)의 동체(胴體)가 발견되었다. 또한 석탑의 지대석(地臺石)과 탑재(塔材), 원래 자리에서 옮겨진 것으로 보이는 주초(柱礎)와 우물터 등이 발견되었다.","a":"공주남혈사지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652689.jpg"},{"q":"조선 초기의 문신인 청허당(淸虛堂) ○○○의 ○○이다. 이정(李挺)의 넷째 아들로 문과에 급제하였으며, 조선 왕조 건국에 공이 있어 태조 2년(1393)에 우산기상시에 임명되었고, 그 뒤에도 여러 관직을 역임하였다. 정종 2년(1400)에는 사병제도 혁파에 반대하다가 계림부윤으로 좌천되었다. 그러나 제1차 왕자의 난 직후에 공신이 되었고, 이후에 우의정을 거쳐 영의정까지 올랐다. 묘의 형태는 직사각형으로 흙과 돌을 섞어서 쌓았으며 원래의 모습이 잘 남아 있다.","a":"진천 이거이 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650313.jpg"},{"q":"경상남도 ○○시 영곡면 원내리 한산사에 모셔진 비로자나불이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위에 상투 모양의 머리묶음이 솟아 있다. 얼굴은 네모에 가까운 타원형이며, 입은 작지만 희미한 미소를 띠고 있다. 신체는 당당한 어깨에 허리가 잘록하여 사실성이 강하다. 손은 왼손 검지를 오른손으로 감싸고 있는 모습으로 비로바나불이 일반적으로 취하는 손모양이다. 대좌(臺座)는 상·중·하대로 구성되었으며 4각형의 하대에는 연꽃무늬가, 중대에는 사천왕상이 새겨져 있다. 9세기 말 10세기 초의 양식을 보여주는 작품이다.","a":"진주 고산암 석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642015.jpg"},{"q":"이 비는 도로를 개수하고 그 사실을 표석에 새긴 것이며 1725년에 건립되었다. 비문이 있는 면만 다듬어져 있고 나머지 면은 대략 형태만 갖추고 있다. 비문은 해서체 글씨로 13행 150자 이상이며 내용은 1725년 ○○○ 승려들이 자비를 내어 험난한 길을 평탄하게 정리한 것을 칭송한 것이다. 글씨가 깊고 수려하게 새겨져 있어 조선시대 금석문을 연구하는 데 좋은 자료가 된다.","a":"용천사동하도로수치송공표석","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641151.jpg"},{"q":"○○○○○은 중건된 지 250년이 된 전면 및 측면 1칸의 맞배지붕으로 지어진 건축로서 건물의 크기에 비해 지붕이 큰 특징을 지니고 있고, 그것을 받치고 있는 공포는 균형을 가질 수 없을 정도로 큰 특징을 지닌 건축물로서 사료적 가치를 인정하여 보존관리 되어야 할 건축물임","a":"하동 오천정씨 정려각","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666507.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 전기의 유학자인 ○○의 공적을 기록하고 있다. ○○은 연산군 10년(1504)에 과거에 합격한 후 여러 벼슬을 거쳐 관직이 승정원 동부승지에까지 올랐으나 기묘사화 때 화를 입어 17년간 유배생활을 하였다. 성품과 자질이 순수하고 행동에 지조가 굳고 법도가 있었다고 전한다. 비는 네모난 바닥돌 위에 비몸을 세우고 지붕돌을 올린 일반적인 모습으로, 지붕돌은 팔작지붕의 세부양식을 정교하게 본떴다.","a":"청주 박훈 신도비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638679.jpg"},{"q":"○○○○은 경상북도 민속문화유산으로 지정되어 있는 괴헌고택(槐軒古宅)과 접한 대지에 서남향으로 위치하여, 안마당을 중심으로 안채와 사랑채, 행랑채를 연결한 정면 6칸, 측면 6칸 규모의 전형적인 ㅁ자형 평면을 보여주고 있다. 정침 및 대문간채와 방앗간채, 서당이 잘 갖춰져 있는 민가로 다소 외부 형태의 변형이 보이지만 그 평면은 잘 보존되어 있으며, 마루를 설치한 곳간과 사랑채, 안채의 연결 동선 등 특징적인 부분이 잘 남아 있어 조선후기 사대부가의 생활을 보여주는 좋은 예이다.","a":"영주 덕산고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663618.jpg"},{"q":"조선 후기의 무신인 한원군 이만유(?∼1730)의 초상화로, 대·소본(大·小本) 2점이다. 이만유는 숙종 40년(1714) 무과에 오르고, 영조 4년(1728) 이인좌의 난을 평정하는데 공을 세워 자헌에 올랐다. 그 후 지중추부사를 거쳐 여러 지방의 목사를 지내었으며, 경상좌수사를 역임하던 중 생을 마치었다. 소본은 주인공이 약간 우측을 바라보고 있는 반신상으로서, 검은 사모를 머리에 쓰고 국가 의식 때에 대신들이 입던 조복을 단정하게 차려 입고 있다.","a":"이만유영정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640033.jpg"},{"q":"조선 현종 6년(1665)에 퇴계 이황(1501∼1570)이 후학들에게 도를 강의하던 자리를 기념하기 위해 세운 정자이다. 옛 이름은 ‘낙수대’였으나 육사형의 시 내용에 따라 ‘○○○’로 바꿔 불렀다고 한다. 앞면 2칸·옆면 2칸 규모이며, 4면은 모두 개방되어 있다. 원래 뒤쪽 2칸은 방으로 만들었으나 후대에 지금처럼 고친 것으로 보인다. 4면에 난간을 설치했으며 맞은편에 ‘○○○’라 새긴 바위가 남아 있다.","a":"명옥대","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662752.jpg"},{"q":"경주시 ○○○ 금강산의 정상 동쪽에 위치한 자연 바위벽에 새긴 ○○○상이다. 중앙에는 본존불이 앉아 있고, 양쪽에는 협시보살이 새겨져 있다. 오른쪽 협시보살의 머리에 쓴 보관(寶冠)에 작은 부처가 조각되어 있는 것으로 보아 아미타○○○을 표현한 것으로 보인다. 본존불의 높이가 약 3m에 이르는 거대한 마애불이지만 선각에 가깝게 새겨 부분적으로 마멸이 심하다. 조각된 옷의 표현과 손의 모습 등은 통일신라시대 마애불 연구에 귀중한 자료가 된다.","a":"경주동천동마애삼존불좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640678.jpg"},{"q":"‘여주 ○○○○○’은 6세기 중엽 이래로 신라가 한강 유역을 진출하는 과정에서 신라 영역에 편입된 여주 지역에 조성한 대규모 ○○○이다. ○○○은 여주시에서 동남쪽으로 3㎞ 가량 떨어진 황학산(해발 175.3m)의 북쪽 능선이 ○○○를 지나 남한강 변의 상동까지 이어지는 해발 80m 내외의 능선과 동으로 뻗은 가지 능선 일대에 분포한다. 지형과 고분 밀집도에 따라 크게 5개 지역에 모두 200여기 이상의 무덤이 분포하고 있지만, 본래 하나의 큰 ○○○에 포함된다. 발굴조사에 따르면, 석실과 석곽의 평면 형태는 장방형이며, 네 벽은 깬 돌로 축조하였다.","a":"여주매룡리고분군","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647178.jpg"},{"q":"천등산 기슭에 있는 ○○○는 신문왕 2년(682) 의상대사가 지었다고 한다. 부석사를 세운 의상대사가 부석사에서 종이로 봉황새를 만들어 날려 보냈는데, 그 새가 내려앉은 자리에 절을 짓고 ○○○라 이름지었다는 전설이 전하여 온다. ○○○의 ○○○은 지조암과 함께 ○○○의 부속암자로 응진전, 영화실, 송암당, 삼성각, 우화루·관심당 등 5동으로 이루어져 있고, 건물의 구체적인 건립연대는 알 수 없으나 '○○○○○향로전창건기'와 ○○○○○전중수기'등의 사료로 볼 때 19세기 말로 추정된다.","a":"봉정사영산암","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658876.jpg"},{"q":"조선 광해군과 인조 때에 여러 공을 세운 조익도에게 내린 ○○와 공신록권이다. 2책의 공신록권 가운데 하나는 광해군 5년(1613) 대북파가 소북파를 없애려고 김직재 등을 모반혐의로 처형시킨 공으로 그 이듬해 내린 「형난원종공신록권」이고, 다른 하나는 인조 2년(1624)에 이괄의 난을 평정한 공으로 인조 3년(1625)에 내린 「진무원정공신록권」이다.","a":"조익도공신록권 및 교지","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642299.jpg"},{"q":"이 ○○은 조선 중기 1608년 2월부터 1609년 7월까지 동래부사를 역임한 이안눌(1571∼1637) 선생의 「○○○○」와 「○○○증도원선인」시를 자필로 쓴 것을 판각한 것이다. 이안눌은 조선 중기의 문신으로, 29세 때 문과에 급제하여 여러 벼슬을 거쳤으며, 1636년 병자호란이 일어나자 왕을 따라 남한산성으로 갔다가 다시 돌아온 뒤 병이 심해져 죽었다. 시를 짓는데 뛰어나 문집에 4,379수의 엄청난 양의 시를 남겼다.","a":"범어사 청룡암시 목판","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101815552400.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 명주군 왕릉에서 서북쪽으로 약 1㎞ 떨어진 지점의 언덕지대로 산 기슭에서 아래쪽 계곡에 닿는 경사지의 중간지점에 있다. 강원특별자치도에서 발견된 가마터 중 유일한 분청사기 가마터로 『세종실록지리지』에는 “자기소는 보현촌의 서쪽부근에 1곳이 있다”라고 기록되어 있다. 수습된 분청사기와 청자조각들은 대접과 접시종류가 대부분이며, 그릇의 안쪽에 흑상감된 연당초문대접과 분청인화국화문접시, 분청인화연판문대접들과 약간의 백자조각들이 수습되었다.","a":"강릉보광리분청자요지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648380.jpg"},{"q":"1922년 전북 정읍에 지어진 보천사 십이전을 1938년 이곳으로 옮겨 태고사의 ○○○으로 사용하다가 ○○○○○으로 이름을 바꾼 것이다. ○○○은 앞면 7칸·옆면 4칸으로 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포양식을 이용하였다. 특히 모든 벽에 있는 문은 꽃 모양으로 장식된 문살로 되어 예술적 화려함과 정교함을 갖고 있다. 이 건물의 모든 것이 1920년대 조선시대 후기의 건축양식을 받아들이면서 전각의 대형화를 이룬 것이 특징이다.","a":"조계사 대웅전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2589984.jpg"},{"q":"이 책은 보물 제758호로 지정된 ○○○와 불갑사에 보관된 전라남도 유형문화유산 제244호 및 제245호와는 완전히 다른 것이다. 이들은 모두 주석이 있는데 비하여 이 책은 반곽에 32자의 원문만 크게 인쇄된 것이다. 선지식(禪知識)을 연구하기 위한 목적과 함께 조맹부(趙孟부)의 송설체(松雪體)를 익히기 위하여 인쇄된 것으로 보이지만, 인쇄된 연대를 1316년으로 보기는 어려운 듯하다. 그러나 이러한 형태의 ○○○는 잘 보이지 않는데다 어미의 형태나 지질로 보아 연대가 상당히 올라가는 것으로 생각된다.","a":"증도가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665073.jpg"},{"q":"조선 중기의 문신이자 서예가인 ○○○와 그의 부인 명안공주(明安公主 : 1665~1687)를 모신 합장묘의 유택이다. ○○○의 본관은 해주(海州)이며 자는 도장(道長), 호는 ○○○이다. 글씨를 잘 쌌으며 특히 예서에 능했다. 시호는 문효(文孝)이다. 봉분 좌측의 묘갈은 팔작지붕형 옥개석(屋蓋石), 비신(碑身), 기대(基臺)로 구성되어 있다. 묘갈문은 비의의 좌우측면 및 비음(碑陰)에 모두 기록을 새기고 있다.","a":"취몽헌오태주묘역","c":"시도기념물","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647198.jpg"},{"q":"자연 암석에 ‘○○○’라는 글씨를 전서체로 새긴 것이다. 조선 명종 때 ○○군수로 있던 퇴계 이황은 나랏일에 시달린 몸과 마음의 피로를 풀고자 매일 이곳에 와서 손발을 씻었다고 한다. 이황은 이곳이 사람의 마음까지도 깨끗하게 해준다는 의미로 ○○○라고 이름 짓고 손수 이곳에 글씨를 새겼다.","a":"단양 탁오대 암각자","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638509.jpg"},{"q":"조선조의 중규모 재실로써 주변의 영역이 잘 보존되어 있으며, 묘와 신도비 및 재실의 구성이 매우 조화롭게 형성되어 있다. 대문채 뒷면의 기단이나 ○○○의 기단 등은 원래의 구성이 훼손되지 않고 잘 보존되어 있다.","a":"진주 오방재","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666359.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 본래 지금의 노성초등학교 자리에 세웠다고 하나 세운 시기를 정확하게 알 수 없고, 1700여 년경 지금 있는 자리로 옮겨 세웠다. 단지 조선 인조 9년(1631)에 대성전을 보수하였다는 명륜당 현판의 기록으로 보아 오래된 건물임을 알 수 있다. 현재 대성전, 동재, 서재, 삼문 등이 남아 있다. 대성전은 앞면 3칸·옆면 2칸 규모의 건물로 안쪽에는 공자를 중심으로 증자·맹자·안자·자사의 위패를 모시고 있다.","a":"노성향교","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652916.jpg"},{"q":"이 전적은 안동의 권희학 가문이 소장하고 있는 것으로, 시기적으로는 17세기에서 19세기까지 걸쳐 있다. 지정된 전적을 보면 『연행일기』, 『서행일기』, 『남정목록』, 『감고당집』등이다. 『연행일기』는 숙종 23년(1697)에 우의정 최석정이 세자책봉 주청사로 연행(燕行:옛날 사신이 중국의 북경으로 가던 일)할 때 군관으로 수행한 선생의 일기이다. 『서행일기』는 숙종 24년(1698)에 최석정이 해군시랑 영사사로 서울에서 의주까지 행차할 때 군관으로 수행하면서 쓴 일기이다.","a":"감고당문적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640660.jpg"},{"q":"고분은 ○○○마을의 북서에서 남동으로 내려오는 낮은 구릉의 끝부분에 위치하고 있는데 구릉은 밭으로 개간되었고 구릉 주변의 충적지는 논으로 경작되고 있다. 구릉 끝부분에는 영광정씨(靈光丁氏)의 민묘 4기가 있으며 이 민묘들의 뒤쪽에 고분이 위치하고 있다. 고분은 주변 지역의 개간과 민묘의 조성으로 분구가 약간 변형되었지만 비교적 잘 남아있다. 분구는 많이 삭평되었는데 중앙에 남―북 장축의 석실 상부가 완전히 노출되어 있다. 석실은 분구를 성토하면서 구지표 위쪽에 만든 지상식으로 추정되는데 북서쪽에서 남동쪽으로 내려오는 지형과 상관없이 남―북 방향으로 축조하였다.","a":"고흥신호리동호덕고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020052414212400.JPG"},{"q":"취성산 기슭에 있는 절로 신라 진평왕 28년(606)에 혜공이 지었으며 ○○○라 하였다. 고려 공민왕 11년(1362)에 나옹이 다시 지으면서 현재의 이름 ○○○로 부르게 되었다. 그 뒤 조선 인조 19년(1641)과 영조 28년(1762)에 수리하였다. 석가모니를 모신 ○○○은 앞면 3칸·옆면 2칸 규모이며, 지붕은 여덟 팔(八)자 모양인 팔작지붕집이다. 내부는 우물천장과 빗천장으로 되어 있으며, 단청을 하여 전체적으로 매우 화려하게 장식한 조선 중기의 건물이다.","a":"상주사대웅전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639422.jpg"},{"q":"이 불화는 영취산(靈鷲山)에서 설법하는 석가모니를 그린 ○○○○○로서 1884년에 제작되었다. 가로로 긴 화면의 중앙에는 석가모니(釋迦牟尼)가 설법(說法)하는 모습을, 그리고 그 옆에 네 보살(菩薩)과 사천왕(四天王), 여섯 명의 제자(弟子)를 배치하였는데 화면의 빈 공간에 채운(彩雲)을 가득 그려 넣어 전체적으로 여백 없이 빽빽한 화면 구성을 보여준다. 본존인 석가모니는 붉은 색의 법의를 입고 연화대좌(蓮花臺座) 위에 결가부좌(結跏趺坐)한 모습으로서 양감(量感) 있는 얼굴과 당당한 신체로 인하여 건장한 느낌을 준다.","a":"진관사 영산회상도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636374.jpg"},{"q":"모두 9기의 비로, 그동안 마을도로 가에 흩어져 있던 것을 한자리에 모아놓은 것이다. 이 중 3기는 현감의 어진 정치를 기념하기 위한 선정비이고, 나머지 6기는 ○○○○○이다. ○○○○이란 조세를 거두어 충청·전라·경상 3도에 창고를 지어 보관하거나, 서울로 옮기는 조운업무를 담당하는 관리를 말한다. 이 비는 조선 중종 18년(1523) 이곳에 창고를 짓고, 보관과 서울로의 운송을 맡아보던 관리들의 청렴한 덕을 기념하기 위해 세운 것이다. 비의 앞면에는 모두 ‘○○○○○’라는 명칭을 새겨 놓았다.","a":"삼도해운판관비","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661295.jpg"},{"q":"○○○ 성보박물관에 소장되어 있는 신중탱화로서 견본채색(絹本彩色)이며, 제석천(帝釋天)과 동진보살(童眞菩薩)을 동자상(童子像)과 신중상(神衆像)이 둘러싸고 있는 모습이다. 1792년에 조성된 불화이다. 「건륭오십칠년임자팔월신중회화성우○○○봉안우원적산금봉암.....(乾隆五十七年壬子八月神衆會畵成于通度寺奉安于圓寂山金鳳庵.....)」의 화기(畵記)가 있다.","a":"양산 통도사 건륭57년명 신중도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642339.jpg"},{"q":"전라남도 해남군 성마산 북쪽 기슭에 있는 무덤으로 1986년 발견되었다. 무덤은 네모꼴로 된 바닥에서 흙으로 쌓아 올린 후, 그 위에 돌을 촘촘히 박아 놓은 방형즙석분(方形葺石墳)이다. 이러한 형태의 무덤이 우리나라 최남단인 이곳에서 발견되었다는 점은 학계에 주목을 받고 있는데 용운리의 장고산에 있는 앞이 네모나고 뒤가 둥근 전방후원형의 무덤과 함께 고대 한·일 무덤문화의 상호영향과 전남지방의 무덤문화를 밝히는데 중요한 유적이다.","a":"해남신월리방대형고분","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654259.jpg"},{"q":"○○○○○은 조선후기에 건립된 정자로 창건연대가 비교적 앞서는 마을내부의 무실(無室) 정자로 교류와 교육공간이며, 건축적 측면에서 보면 3칸 규모의 팔작집으로 충량을 비롯한 덤벙 주초나 원주 및 선자연 등의 결구방법과 자연스러움을 살린 부재 사용 등 고격(古格)을 갖추고 있다. ○○○○○은 조선시대에 세워진 다른 정자들이 선비들에 시문학과 원림문화의 본거지로 기능하면서 대부분 강변 등의 경승지에 위치하는데 반하여, ○○○은 마을 한 가운데에 있어 일종의 종회소 겸 교류공간으로서 기능하고 있다. 이러한 점이 다른 정자들과 대별되는 특징이라 하겠다.","a":"담양 척서정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640186.jpg"},{"q":"영원사터에 남아 있는 ○○○○의 탑비로, 주변에 흩어져 있던 여러 부재를 수습해 놓은 것이다. ○○○○는 고려 일연스님의 제자로, 충렬왕 때 대선사(大禪師)가 되었고 충숙왕 때 왕사(王師)가 되었다. 몇년 후 은퇴하여 영원사에 머무르다가 말년에 송림사로 옮겨 입적하였다. 국사로 추증되었고 ‘보감’은 그의 시호이며, 탑이름은 ‘묘응’이다. 비는 거북모양의 받침돌이 비몸을 잃어버린 채 머릿돌을 받치고 있다. 거북의 머리는 힘찬 형태로 매우 생동감 있게 표현되었으며, 입에는 여의주를 물고 있다.","a":"밀양 영원사지 보감국사 묘응탑비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641360.jpg"},{"q":"암행어사 ○○○의 공적을 기리고 있는 비와 이를 보호하고 있는 비각이다. ○○○는 조선시대의 문신으로, 순조 29년(1829) 통정대부 승지로서 암행어사가 되었다. 그해 10월 회덕지방의 가난과 질병에 허덕이던 서민들을 구제하고 민정을 살폈는데, 그의 어진 다스림을 잊지 못한 이 지역 사람들이 이 비와 비각을 세웠다. 비각은 네 기둥 위로 웅장한 모습의 지붕을 얹었다. 기둥은 굵은 팔각기둥 모양의 주춧돌 위에 서 있으며, 그 위로 처마의 무게를 받기 위한 공포가 설치되어 있다. 기둥머리에 짜맞춰진 공포는 연꽃과 연꽃봉오리들로 장식하여 매우 화려하다.","a":"어사홍원모영세불망비","c":"문화유산자료","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659731.jpg"},{"q":"○○○는 통일신라 후기에 진감국사가 연악산 상봉인 미봉에 하얀 연꽃 한 송이가 피어있는 것을 보고 절을 처음 세워 연화사라 하였다고 전한다. 고려 광종 26년(975)에 화재를 당해 명종 15년(1185)에 각원대사가 절을 다시 세우고 이름을 성암사라고 하였다. 원종 14년(1273)에 큰 물난리로 허물어진 것을 조선 선조 5년(1572)에 사명대사가 수리 보완하고 이름을 ○○○라 하였다. 그러나 숙종 31년(1705)에도 화재를 당해 현존하는 건물만 남기고 모두 불에 탔다.","a":"수다사 명부전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640542.jpg"},{"q":"1901년에 프랑스 신부인 안토니오 꽁베르(Antonio Combert, 1875~1950, 우리나라 이름 공안국)가 세운 성당이다. 1922년에 보개면 신안리 강당의 건축부재를 이용하여 한옥성당으로 고쳐지었다. 1955년에 전면의 반원형 아치의 입구와 종탑이 추가되어, 전형적인 서양식 교회건축의 정면을 갖고 있지만, 측면은 전통건축양식을 갖고 있는 한양절충식 교회건축이다. 중앙의 신도석과 양편에 복도가 위치한 전형적인 바실리카식 공간구조를 한옥의 목구조로 해결한 건축이다.","a":"안성성당","c":"시도기념물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646186.jpg"},{"q":"○○○○○에 모셔져 있는 앉은 모습의 ○○○○○상이다. 원래는 양 옆에 관세음보살과 대세지보살의 협시불과 함께 삼존의 형식을 갖추고 있었으나, 1989년 8월경 양 협시불을 도난당하여 이후에 새로 조성한 것이다. 나무로 만들어진 아○○○○○은 사각형에 가까운 얼굴을 하고 있으며 등이 약간 굽은 모습이다. 머리는 소라모양의 나발이고, 짧은 목에는 삼도가 얕게 그려져 있다. 양어깨를 모두 감싼 옷의 주름은 뚜렷하면서도 두툼한 느낌을 준다.","a":"화순쌍봉사극락전목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640160.jpg"},{"q":"대조사 원통보전 앞에 서 있는 탑으로, 일부만 남아있던 것을 1975년에 다른 일부를 찾아 다시 세운 것이다. 탑은 전체의 무게를 지탱해 주는 기단(基壇)을 2층으로 마련하고, 그 위로 3층의 탑신(塔身)을 올려놓은 모습인데, 탑신의 2·3층 몸돌과 꼭대기의 머리장식은 새로 만들어 놓은 것이다. 기단은 각 층마다 면의 모서리와 가운데에 기둥 모양을 본 뜬 조각을 두었다. 탑신의 지붕돌은 밑면에 받침을 두었는데, 1·2층은 3단, 3층은 2단으로 새겨 불규칙한 모습이다. 지붕돌의 처마는 가운데에서 수평을 이루다 네 귀퉁이에 이르러 가볍게 위로 들려있다.","a":"대조사석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661034.jpg"},{"q":"전라남도 고흥군 두원면 ○○○에 있는 높이 2.7m의 거대한 ○○○○상이다. 의자에 앉아 있는 모습인데, 오른발을 의자 위에 걸치고 있으면서 다른 신체 부위보다는 작게 표현해서 독특한 자세를 보여준다. 머리에는 작은 부처가 새겨진 높은 관(冠)을 쓰고 있다. 계란형의 얼굴은 살이 올라 풍만하며, 눈·코·입과 더불어 둔중해 보인다. 우람한 체격에 주먹을 쥔 채 내려진 왼팔은 터무니없이 크게 표현되어 있다. 굵은 어깨와 팔뚝에 비해서 손은 너무나 작고, 허리는 가늘게 표현해 균형감이 떨어진다. 왼쪽 어깨만 걸친 얇은 옷은 소매자락에서 넓어져서 아래로 휘어져 있다.","a":"고흥용산리석조보살좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640060.jpg"},{"q":"진주 강씨 문중들이 자녀교육을 목적으로 세운 건물이다. 조선 중기에 세운 것으로 효종 정묘호란 때 척화를 상소한 상곡 강유가 공부하던 곳이다. 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 중앙에는 대청마루를 조성하고 왼쪽에 방 2개, 오른쪽에 방 1개를 배치하였다. 현판은 조선 후기의 유명한 유학자이며 의병장인 유인석이 직접 쓴 것이다.","a":"제천 박약재","c":"시도기념물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650199.jpg"}]);